class TestV2041ADurableReceiptForALedgerThatLivesInAWindow(unittest.TestCase):
    """His grail and vault ledgers live ONLY in a window's localStorage - vault_ledger_load() says
    so in its own docstring: the console has never held them. A crash or a force-quit takes 404
    found uniques and 120 set pieces with it, silently.

    Made urgent 2026-08-24: spawned board windows are unclaimed GUEST worlds, and six of them in one
    night wrote six `I·<id>·` namespaces into the same on-disk store, leaving none of his bare keys
    on disk. His ledger was fine - verified live at 404/5/120 with real names - but nothing on disk
    could have proven it and nothing would have brought it back.
    """

    def _patch(self, ca, tmp, answer):
        import unittest.mock as mock
        return (mock.patch.object(ca, "_LEDGER_BACKUP_DIR", tmp),
                mock.patch.object(ca, "board_ownership", lambda sample=0, **kw: answer))

    def _run(self, answer, tmp, force=True, reset=True):
        import control_app as ca
        if reset:
            ca._LEDGER_BACKUP_STATE.update({"last": "", "counts": None, "writes": 0, "why": ""})
        a, b = self._patch(ca, tmp, answer)
        with a, b:
            return ca._ledger_snapshot_once(force=force)

    def test_a_refusal_never_becomes_a_backup(self):
        """board_ownership refuses honestly on a timeout. Filing that as a backup would record
        'he owns nothing' as though it had been measured. [[unknown-stays-unknown]]"""
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            path, why = self._run({"ok": False, "why": "the board did not answer in time"}, tmp)
            self.assertIsNone(path, "a refusal was written to disk as a backup")
            self.assertEqual(len(_fx_tmp.match_own(os.path.join(tmp, "*.json"))), 0)

    def test_an_empty_ledger_is_refused(self):
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            path, why = self._run({"ok": True, "counts": {"foundLog": 0, "owned": 0, "setPieces": 0},
                                   "sample": {"foundLog": [], "owned": [], "setPieces": []}}, tmp)
            self.assertIsNone(path, "an empty ledger was filed over real history")
            self.assertIn("EMPTY", why)

    def test_a_truncated_ledger_is_refused(self):
        """A partial copy that calls itself a backup is worse than no backup."""
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            path, why = self._run({"ok": True,
                                   "counts": {"foundLog": 404, "owned": 5, "setPieces": 120},
                                   "sample": {"foundLog": ["a", "b"], "owned": ["c"],
                                              "setPieces": ["d"]}}, tmp)
            self.assertIsNone(path, "a truncated ledger was written as if complete")
            self.assertIn("truncated", why)

    def _full(self):
        return {"ok": True, "counts": {"foundLog": 2, "owned": 1, "setPieces": 1},
                "sample": {"foundLog": ["Wormskull", "Wolfhowl"], "owned": ["Raven Frost"],
                           "setPieces": ["Angelic Halo (ring)"]}}

    def test_a_complete_ledger_is_written_with_its_names(self):
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            path, why = self._run(self._full(), tmp)
            self.assertIsNotNone(path, "a complete ledger was not written: %s" % why)
            d = json.load(open(path, encoding="utf-8"))
            self.assertEqual(d["counts"]["foundLog"], 2)
            self.assertIn("Wormskull", d["ledger"]["foundLog"])
            self.assertTrue(d.get("takenAt"), "a backup with no timestamp cannot be ordered")

    def test_an_unchanged_ledger_does_not_spam_a_second_copy(self):
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            self._run(self._full(), tmp)
            path, why = self._run(self._full(), tmp, force=False, reset=False)
            self.assertIsNone(path, "an identical ledger was filed twice")
            self.assertIn("unchanged", why)

    def test_it_keeps_a_bounded_number_of_copies(self):
        import tempfile, control_app as ca
        with tempfile.TemporaryDirectory() as tmp:
            for i in range(ca._LEDGER_BACKUP_KEEP + 6):
                open(os.path.join(tmp, "ledger_2020-01-01_%06d.json" % i), "w").write("{}")
            self._run(self._full(), tmp)
            left = _fx_tmp.match_own(os.path.join(tmp, "ledger_*.json"))
            self.assertLessEqual(len(left), ca._LEDGER_BACKUP_KEEP,
                                 "backups grow without bound")

    def test_the_backups_are_written_OUTSIDE_the_public_repo(self):
        """d2r-bible-tests is PUBLIC and a push to main PUBLISHES. His ledger must never land in it."""
        import control_app as ca
        repo = os.path.dirname(os.path.dirname(os.path.abspath(ca.__file__)))
        d = os.path.abspath(ca._LEDGER_BACKUP_DIR)
        self.assertFalse(d.startswith(os.path.abspath(repo) + os.sep),
                         "ledger backups are inside the PUBLIC repo (%s) - a push would publish "
                         "his entire grail history" % d)

    def test_the_backup_loop_is_actually_started(self):
        self.assertTrue(_watcher_is_armed("tvd-ledger-backup", "_ledger_backup_loop"),
                        "the backup loop is never started")



class TestV2048TheBoardWindowStaysIsolated(unittest.TestCase):
    """REVERTS v2043. A board window must NOT share the main window's localStorage.

    v2043 gave the board window `private_mode=False` so its own world would survive a relaunch, and
    it worked — install id c5c2c92d survived two launches beside the live console.

    THEN IT COST HIM HIS LEDGER. His main window's grail/vault world lives only in ITS memory —
    nothing on disk ever held his bare `d2r_foundLog`. After persistent WebKit probes ran beside the
    live console, that window went from 404 foundLog / 5 owned / 120 setPieces to ZERO, and the
    shared store held the probe's own key and none of his. A second persistent process on this
    origin can take the live window's world with it.

    v2045 had already removed the only reason a board window needed to persist: it is a GUEST world
    that can never be his real one, so nothing of value is stored there. Isolation is worth more
    than persistence for a window whose contents do not matter.
    """

    def _src(self):
        here = os.path.dirname(os.path.abspath(__file__))
        return open(os.path.join(here, "control_app.py"), encoding="utf-8").read()

    def test_the_board_window_does_NOT_ask_for_persistent_storage(self):
        blk = _between(self, self._src(), "def board_window():", "def main():",
                       what="board_window")
        # Check the CALL, not the prose. The comment above it legitimately contains the words
        # `private_mode=False` while explaining why they are gone, and a naive substring test would
        # be blinded by exactly that — the same way my own comment blinded a guard earlier tonight.
        self.assertFalse("private_mode=False)" in blk,
                         "the board window passes private_mode=False again — it would share the "
                         "MAIN window's localStorage, and that emptied his 404-entry ledger once")
        self.assertFalse("webview.start(**" in blk,
                         "the board window starts with kwargs again; the only kwarg this ever "
                         "carried was the persistence that cost him the ledger")
        self.assertTrue("webview.start()" in blk,
                        "board_window no longer starts a window at all")

    def test_the_MAIN_window_still_persists(self):
        """The revert must not reach the window that holds his real ledger."""
        self.assertTrue("_start_kw = dict(debug=False, private_mode=False)" in self._src(),
                        "the MAIN window stopped requesting persistent storage — his grail ledger "
                        "would reset on every quit")

class TestV2044TheDoctorCanSeeADoomedWorld(unittest.TestCase):
    """An unclaimed board world fails SILENTLY: the ledger counts read exactly the same in a doomed
    world as in a real one, so nothing on any screen distinguishes them. An apply into it returns
    ok:true, writes real rows, and they are unreachable from the next load. That cost a whole night.
    [[the-unjoined-end]]
    """

    def _cd(self):
        import console_doctor
        return console_doctor

    def test_an_ABSENT_ownership_field_is_unknown_never_a_pass(self):
        """An older console cannot answer. 'Nobody asked' must never read as 'all fine'."""
        import unittest.mock as mock
        cd = self._cd()
        with mock.patch.object(cd, "_post", lambda *a, **k: {
                "ok": True, "counts": {"foundLog": 404, "owned": 5, "setPieces": 120}}):
            state, why = cd._check_the_board_world_is_claimed()
        self.assertEqual(state, cd.UNKNOWN,
                         "a console that cannot report ownership was graded as healthy")

    def test_an_unclaimed_world_is_reported_MISSING_with_the_remedy(self):
        import unittest.mock as mock
        cd = self._cd()
        with mock.patch.object(cd, "_post", lambda *a, **k: {
                "ok": True, "owner": False, "pfx": "I\u00b7abc12345\u00b7",
                "counts": {"foundLog": 404, "owned": 5, "setPieces": 120}}):
            state, why = cd._check_the_board_world_is_claimed()
        self.assertEqual(state, cd.MISSING, "a doomed world was not flagged")
        self.assertIn("This browser is mine", why, "the report names no remedy")
        # 404 + 5 + 120 = 529. Naming the size is what makes the warning land: "your 529-entry
        # ledger is in a world that evaporates" is a different sentence from a generic caution.
        self.assertIn("529", why,
                      "the warning does not say how much is at stake, so it reads as boilerplate")

    def test_a_claimed_world_passes(self):
        import unittest.mock as mock
        cd = self._cd()
        with mock.patch.object(cd, "_post", lambda *a, **k: {
                "ok": True, "owner": True, "pfx": "",
                "counts": {"foundLog": 404, "owned": 5, "setPieces": 120}}):
            state, why = cd._check_the_board_world_is_claimed()
        self.assertEqual(state, cd.OK)

    def test_a_silent_console_is_unknown_not_ok(self):
        import unittest.mock as mock
        cd = self._cd()
        with mock.patch.object(cd, "_post", lambda *a, **k: None):
            state, why = cd._check_the_board_world_is_claimed()
        self.assertEqual(state, cd.UNKNOWN)

    def test_the_check_is_actually_in_the_CHECKS_list(self):
        """A check nobody runs is prose."""
        cd = self._cd()
        names = [n for n, _fn in cd.CHECKS]
        self.assertIn("board is claimed", names, "the check is never run by the Eagle Eye")

    def test_board_ownership_reports_which_world_it_read(self):
        here = os.path.dirname(os.path.abspath(__file__))
        src = open(os.path.join(here, "control_app.py"), encoding="utf-8").read()
        blk = _between(self, src, "def board_ownership", "def _jsq(", what="board_ownership")
        self.assertTrue("_D2R_OWNER" in blk,
                        "board_ownership no longer says which world the counts came from, so a real "
                        "ledger and a doomed one are indistinguishable to every caller")
        self.assertTrue("owner:owner" in blk)



class TestV2046TheDiskWarningMeasuresHisFootage(unittest.TestCase):
    """The disk check used to say "a reel writes roughly 9GB/hour".

    That number is REAL — v2019 clocked +37MB in 15s on a busy scene. So is 5.0-6.6GB/hour, measured
    2026-08-24 across his three newest reels at 1.44-1.90 MB/frame. Both are true, because JPEG size
    tracks scene complexity and the rate swings ~2x with what he is looking at. A single constant
    cannot describe that, and quoting one as though it could is a right number under a word that
    stopped being true. [[label-outlived-referent]]

    He acts on this figure — it is how he decides whether to start a session.
    """

    def _fixture(self, tmp, n_frames, minutes, kb):
        """A reel of n_frames spread over `minutes`, each kb kilobytes."""
        import time as _t
        d = os.path.join(tmp, "frames", "hist", "reel_s_1_1")
        os.makedirs(d)
        now = _t.time()
        for i in range(n_frames):
            q = os.path.join(d, "f_%d.jpg" % i)
            with open(q, "wb") as fh:
                fh.write(b"\0" * (kb * 1024))
            t = now - (minutes * 60.0) + (i * minutes * 60.0 / max(1, n_frames - 1))
            os.utime(q, (t, t))
        return d

    def _rate(self, tmp):
        import unittest.mock as mock
        import console_doctor as cd
        with mock.patch.object(cd, "HERE", tmp):
            return cd._measured_write_rate()

    def test_it_measures_the_real_rate_from_his_own_reels(self):
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            # 60 frames x 1MB over 1 minute = 60MB/min = 3.5GB/hour
            self._fixture(tmp, 60, 1.0, 1024)
            rate, n = self._rate(tmp)
            self.assertEqual(n, 1)
            self.assertAlmostEqual(rate, 60 * 1024 * 1024 * 60 / float(1 << 30), delta=0.3)

    def test_a_reel_too_short_to_time_produces_NO_rate(self):
        """Dividing by a near-zero window invents an enormous figure out of nothing."""
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            self._fixture(tmp, 60, 0.05, 1024)      # 3 seconds
            rate, n = self._rate(tmp)
            self.assertIsNone(rate, "a 3-second reel was extrapolated into an hourly rate")
            self.assertEqual(n, 0)

    def test_a_reel_with_too_few_frames_produces_NO_rate(self):
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            self._fixture(tmp, 5, 5.0, 1024)
            rate, n = self._rate(tmp)
            self.assertIsNone(rate, "five frames were treated as a measurement")

    def test_when_nothing_is_measurable_it_SAYS_it_is_a_worst_case(self):
        """An unmeasured number must never arrive dressed as a measured one."""
        import tempfile
        import unittest.mock as mock
        import console_doctor as cd
        import collections
        # Pin the FREE SPACE too. Reaching the warning branch must not depend on how full his disk
        # happens to be while the suite runs - that is a gate that passes for the wrong reason.
        fake = collections.namedtuple("du", "total used free")(500e9, 490e9, 10e9)
        with tempfile.TemporaryDirectory() as tmp:
            with mock.patch.object(cd, "HERE", tmp):
                with mock.patch.object(cd, "_measured_write_rate", lambda: (None, 0)):
                    with mock.patch("shutil.disk_usage", lambda _p: fake):
                        state, why = cd._check_disk_headroom()
        self.assertEqual(state, cd.MISSING, "10GB free did not reach the warning branch")
        self.assertIn("worst case", why,
                      "an unmeasured rate was reported without saying it was unmeasured")

    def test_the_warning_names_the_measured_rate_not_a_constant(self):
        here = os.path.dirname(os.path.abspath(__file__))
        src = open(os.path.join(here, "console_doctor.py"), encoding="utf-8").read()
        blk = _between(self, src, "def _check_disk_headroom():", "def _check_subscription_burn():",
                       what="the disk check")
        self.assertTrue("_measured_write_rate()" in blk,
                        "the disk check asserts a constant rate again instead of measuring his "
                        "footage - he decides whether to start a session on this number")
        self.assertFalse("roughly 9GB/hour" in blk,
                         "the old constant is back in the warning text")



class TestV2049TheVerdictNamesWhatDidNotRun(unittest.TestCase):
    """run_gates' own docstring already says it: *"Silence about a check that did not happen is the
    same lie as a false green."* That rule was enforced for a whole GATE that skips. It was NOT
    enforced one level down, and that is exactly where it hid.

    Measured 2026-08-24 in a true CI environment (a fresh clone, so tv/frames/ is absent because it
    is gitignored): **45 gates passed while 24 individual CASES skipped inside them** — 8 of them the
    entire scoring half of test_stash_eye_aspect. Meanwhile that hand-labelled corpus had rotted from
    14 frames to 7, losing EVERY negative, and CI stayed green because the cases that would have
    failed never executed.

    The per-gate line said `OK (skipped=8)`. The verdict said `45 gate(s) passed`. Only the verdict
    gets read. [[feedback-blind-fixture-green-gate]]
    """

    def _src(self):
        here = os.path.dirname(os.path.abspath(__file__))
        return open(os.path.join(here, "run_gates.py"), encoding="utf-8").read()

    def test_the_verdict_counts_cases_that_skipped_inside_passing_gates(self):
        blk = _between(self, self._src(), "COUNT THE CASES THAT DID NOT RUN", "return gate_set_exit(failed, _venue)",
                       what="the case-skip accounting")
        # REG-1819 - BEHAVIOUR, not the regex text: the census parses through run_gates.case_skips (one parser, shared with
        # what shard_suite prints). Drive it with the two forms a gate prints, and require the census to CALL it.
        import run_gates as _rg
        self.assertEqual(_rg.case_skips("OK (skipped=8 of 20)"), (8, 20),
                         "the verdict no longer parses the per-suite skip count, so a gate that "
                         "passes while its cases skip reads as full coverage again")
        self.assertEqual(_rg.case_skips("OK (skipped=3)"), (3, None))
        self.assertEqual(_rg.case_skips("\u2705 test_control: 9 of 9 case(s) across 4 shard(s) in 1.0s skipped=2 of 9"), (2, 9))
        self.assertIsNone(_rg.case_skips("OK"))
        self.assertIn("case_skips(", blk, "the census no longer reads a gate's last line through case_skips")
        # THE PRINTED STRING, not the phrase. A first cut asserted "DID NOT RUN" and passed
        # against a sabotage that rewrote the print, because the comment heading above it says
        # "COUNT THE CASES THAT DID NOT RUN". That is the third time tonight my own prose has
        # blinded my own guard. [[source-reading-guard]]
        self.assertTrue("CASE(S) DID NOT RUN inside those gates" in blk,
                        "the verdict no longer NAMES the cases that did not run — a gate that "
                        "passes while its cases skip reads as full coverage again")

    def test_it_does_not_double_count_a_gate_that_skipped_entirely(self):
        """A whole-gate SKIP is already reported and already counted; counting its cases again
        would inflate the number and make the honest one look wrong."""
        blk = _between(self, self._src(), "COUNT THE CASES THAT DID NOT RUN", "return gate_set_exit(failed, _venue)",
                       what="the case-skip accounting")
        live = [ln for ln in blk.splitlines() if ln.strip() and not ln.lstrip().startswith("#")]
        self.assertTrue(any("counts_as_ran(_st)" in ln for ln in live),
                        "the census no longer asks counts_as_ran, so a gate that skipped "
                        "entirely can be counted again as case skips")
        import run_gates as _rg
        self.assertFalse(_rg.counts_as_ran("SKIP"))
        self.assertFalse(_rg.counts_as_ran("CARRY"))
        self.assertTrue(_rg.counts_as_ran("PASS"))
        self.assertTrue(_rg.counts_as_ran("FAIL"))

    def test_the_gate_still_passes_when_nothing_skipped(self):
        """The warning must be conditional. A line that always prints is furniture."""
        blk = _between(self, self._src(), "COUNT THE CASES THAT DID NOT RUN", "return gate_set_exit(failed, _venue)",
                       what="the case-skip accounting")
        self.assertTrue("if _cases:" in blk,
                        "the warning prints unconditionally — it would appear on a clean run and "
                        "stop meaning anything")



class TestV2050TheSnapshotWindowIsHowMuchHeCanLose(unittest.TestCase):
    """These are VALUE assertions, deliberately — not greps over source.

    Three guards tonight passed against a sabotage because the explanatory comment above the code
    contained the string being searched for. A constant can be read directly and cannot lie about
    itself. [[source-reading-guard]]

    The number matters because it was nearly the whole story: on 2026-08-24 his live ledger went
    from 404 uniques / 5 owned / 120 set pieces to ZERO, and the only surviving copy was a snapshot
    taken minutes earlier. At a 30-minute interval, the gap between "it was fine" and "it is gone"
    was wide enough that surviving it was luck.
    """

    def _ca(self):
        import control_app
        return control_app

    def test_the_interval_is_ten_minutes_or_tighter(self):
        ca = self._ca()
        self.assertLessEqual(ca._LEDGER_BACKUP_EVERY_S, 600.0,
                             "the snapshot interval is %.0fs — that is how much of his grail "
                             "history a crash can take" % ca._LEDGER_BACKUP_EVERY_S)
        self.assertGreaterEqual(ca._LEDGER_BACKUP_EVERY_S, 60.0,
                                "polling faster than a minute costs an evaluate_js against his live "
                                "window for nothing — it only writes when the counts change")

    def test_the_FIRST_snapshot_does_not_wait_a_whole_interval(self):
        """A console that boots, inherits a world and dies before the first tick leaves no receipt."""
        ca = self._ca()
        self.assertLess(ca._LEDGER_BACKUP_FIRST_S, ca._LEDGER_BACKUP_EVERY_S,
                        "the first snapshot waits a full interval, so a short-lived console never "
                        "records the world it was handed")
        self.assertGreaterEqual(ca._LEDGER_BACKUP_FIRST_S, 10.0,
                                "snapshotting immediately at boot asks a window that may not exist "
                                "yet, and a refusal is not a backup")

    def test_tightening_the_interval_did_not_shrink_his_history(self):
        """3x the rate at the same depth would be 1/3 the history — a silent downgrade."""
        ca = self._ca()
        hours = ca._LEDGER_BACKUP_KEEP * ca._LEDGER_BACKUP_EVERY_S / 3600.0
        self.assertGreaterEqual(hours, 9.0,
                                "keeping %d snapshots every %.0fs covers only %.1f hours — the "
                                "30-minute era covered 10, and depth is what lets him go back past "
                                "a bad day" % (ca._LEDGER_BACKUP_KEEP, ca._LEDGER_BACKUP_EVERY_S, hours))

    def test_the_loop_still_refuses_to_file_nothing(self):
        """The interval is worthless if a snapshot can overwrite a good backup with an empty read."""
        import tempfile
        import unittest.mock as mock
        ca = self._ca()
        with tempfile.TemporaryDirectory() as tmp:
            with mock.patch.object(ca, "_LEDGER_BACKUP_DIR", tmp):
                with mock.patch.object(ca, "board_ownership", lambda sample=0, **kw: {
                        "ok": True, "counts": {"foundLog": 0, "owned": 0, "setPieces": 0},
                        "sample": {"foundLog": [], "owned": [], "setPieces": []}}):
                    path, why = ca._ledger_snapshot_once(force=True)
        self.assertIsNone(path, "an empty ledger is filed again — that would have destroyed the "
                                "only copy of his 404 uniques")



class TestV2051TwiceEverNotTwiceInOneSweep(unittest.TestCase):
    """vault_retro's own gate says a single witness "is remembered as unsure so a later session can
    corroborate it — the accumulator's whole point." Nothing was remembering it.

    An `unsure` row was `{name, why}`: no lane, no witnesses, no session, no confidence. And
    `_rows_of` absorbs only `owned`. So a sighting from one sweep could never pair with a sighting
    from the next, and the two-witness bar meant "twice inside ONE sweep run", never "twice ever".

    Measured across two real sweeps of his reels on 2026-08-24: TEN items were unsure in BOTH —
    Enigma, Dwarf Star, Bone Visor, Obsession among them — every sighting discarded. Three items
    that HAD grounded in the earlier sweep were not grounded in the later one, because a sweep's
    `owned` is a view of the reels read in that run.

    THE GATE IS NOT TOUCHED by the fix. A folded-in sighting only supplies a session id that
    `gate()` still has to accept on distinct-session and confidence terms.
    [[d2r-multiwitness-corroboration]] [[the-unjoined-end]]
    """

    NAME = "Enigma"

    def _reel(self, td, sid, frames=4):
        """One reel, one session, every frame identical so _distinct yields a single page —
        i.e. exactly ONE sighting from this session."""
        d = os.path.join(td, "reel_%s" % sid)
        os.makedirs(d, exist_ok=True)
        rows = []
        for i in range(frames):
            fn = "f_%03d.jpg" % i
            open(os.path.join(d, fn), "w").close()
            rows.append({"f": fn, "ts": 1000 + i})
        with open(os.path.join(d, "index.json"), "w", encoding="utf-8") as fh:
            json.dump({"sessionId": sid, "n": len(rows), "frames": rows}, fh)
        return d

    def _sweep(self, d, prior=None):
        import vault_retro as vr
        return vr.sweep([d], sig=lambda p: "SAME",
                        classify=lambda p: "stash",
                        reader=lambda p, s: {"items": [{"name": self.NAME, "conf": 0.9}]},
                        panel_gate=lambda p: "stash",
                        prior_seen=prior)

    def _names(self, prop, key):
        return {r.get("name") for r in (prop.get(key) or []) if isinstance(r, dict)}

    def test_one_sighting_in_one_session_does_not_ground(self):
        """The bar itself must still hold — this is the case the whole gate exists for."""
        import tempfile
        with tempfile.TemporaryDirectory() as td:
            p = self._sweep(self._reel(td, "s_A"))
            self.assertNotIn(self.NAME, self._names(p, "owned"),
                             "one session grounded an item — the two-witness bar is gone")
            self.assertIn(self.NAME, self._names(p, "unsure"))

    def test_an_unsure_row_carries_the_evidence_it_needs_to_be_corroborated(self):
        import tempfile
        with tempfile.TemporaryDirectory() as td:
            p = self._sweep(self._reel(td, "s_A"))
            row = [r for r in p["unsure"] if r.get("name") == self.NAME][0]
            self.assertTrue(row.get("lane"), "no lane — the row cannot be folded back in")
            self.assertTrue(row.get("witnesses"), "no witnesses — there is nothing to corroborate")
            self.assertEqual({w.get("session") for w in row["witnesses"]}, {"s_A"},
                             "the row does not say WHICH session saw it")

    def test_ENOUGH_sessions_ground_it_across_sweeps(self):
        """THE POINT, and it is about the ACCUMULATOR, not the number: seen once per sweep, in
        DIFFERENT sessions, the earlier sightings must survive to be counted with the later one.

        v2070 — driven off vr.KEEP_MIN_WITNESSES rather than a hardcoded 2, because his ruling moved
        the bar to 3 and a test that pins the number instead of the LAW has to be rewritten every
        time he rules. What this case defends is that a carried sighting still counts."""
        import tempfile
        import vault_retro as vr
        with tempfile.TemporaryDirectory() as td:
            carried = []
            for i in range(vr.KEEP_MIN_WITNESSES):
                out = self._sweep(self._reel(td, "s_%d" % i), prior=carried or None)
                carried = [r for r in out["unsure"] if r.get("name") == self.NAME] or carried
            self.assertIn(self.NAME, self._names(out, "owned"),
                          "%d DIFFERENT sessions still did not ground it — the sightings from the "
                          "earlier sweeps are being discarded, which is the whole defect"
                          % vr.KEEP_MIN_WITNESSES)

    def test_one_session_SHORT_of_the_bar_does_not_ground(self):
        """The mirror of the number: at KEEP_MIN_WITNESSES-1 distinct sessions it must still refuse,
        or the case above would pass at any bar and prove nothing about this one."""
        import tempfile
        import vault_retro as vr
        with tempfile.TemporaryDirectory() as td:
            carried = []
            for i in range(vr.KEEP_MIN_WITNESSES - 1):
                out = self._sweep(self._reel(td, "s_%d" % i), prior=carried or None)
                carried = [r for r in out["unsure"] if r.get("name") == self.NAME] or carried
            self.assertNotIn(self.NAME, self._names(out, "owned"),
                             "it grounded one session short of the bar")

    def test_without_the_prior_it_still_does_not_ground(self):
        """The mirror. If it grounds with prior=None the test above proves nothing."""
        import tempfile
        with tempfile.TemporaryDirectory() as td:
            self._sweep(self._reel(td, "s_A"))
            second = self._sweep(self._reel(td, "s_B"), prior=None)
            self.assertNotIn(self.NAME, self._names(second, "owned"),
                             "it grounded WITHOUT the carried sighting — so the previous test was "
                             "passing for the wrong reason")

    def test_the_same_session_twice_is_repetition_not_corroboration(self):
        """Law 2. Folding a prior sighting must not let ONE session count twice."""
        import tempfile
        with tempfile.TemporaryDirectory() as td:
            first = self._sweep(self._reel(td, "s_A"))
            carried = [r for r in first["unsure"] if r.get("name") == self.NAME]
            again = self._sweep(self._reel(td, "s_A"), prior=carried)
            self.assertNotIn(self.NAME, self._names(again, "owned"),
                             "the SAME session counted as two witnesses — one eye looking twice is "
                             "repetition, and that is exactly what law 2 forbids")


class TestV2052TheSeenFileIsTheJoin(unittest.TestCase):
    """v2051 remembered ungrounded sightings in tv/vault_seen.json. TestV2051 proves the
    in-memory fold; this proves the FILE layer, which is the half that actually persists
    across process restarts — and the half whose path shipped unregistered, so CI went red
    and the isolation test did not know to move it.
    [[the-unjoined-end]] [[feedback-fixtures-never-touch-live-data]]"""

    def _row(self, name, session):
        return {"name": name, "lane": "stash", "kind": "item", "conf": 0.9,
                "witnesses": [{"session": session, "frame": "f.jpg", "lane": "stash", "conf": 0.9}]}

    def test_a_row_survives_a_save_and_a_load(self):
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "vault_seen.json")
            with mock.patch.object(ca, "_VAULT_SEEN_PATH", path):
                n = ca.vault_seen_save([self._row("Enigma", "s_A")])
                self.assertEqual(n, 1)
                rows = ca.vault_seen_load()
            self.assertEqual([r.get("name") for r in rows], ["Enigma"])
            self.assertEqual({w.get("session") for w in rows[0]["witnesses"]}, {"s_A"})
            self.assertTrue(os.path.isfile(path), "the patched path was never written")

    def test_a_name_this_sweep_did_not_see_is_not_forgotten(self):
        """Absence of evidence is not evidence — vault_seen_save unions, it does not replace."""
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "vault_seen.json")
            with mock.patch.object(ca, "_VAULT_SEEN_PATH", path):
                ca.vault_seen_save([self._row("Enigma", "s_A")])
                ca.vault_seen_save([self._row("Dwarf Star", "s_B")])
                names = {r.get("name") for r in ca.vault_seen_load()}
            self.assertEqual(names, {"Enigma", "Dwarf Star"})

    def test_the_sweep_run_asks_both_ends_of_the_join(self):
        """Anchor on the CALL, not a comment that names the functions.
        co_names holds what the function actually references; a docstring mentioning
        vault_seen_save cannot satisfy this."""
        import inspect
        # REG-2466 (M4) - the sweep is wrapped by @_held_awake (functools.wraps), so the wrapper's code names only
        # _SweepHold; the body that must ask both ends is the wrapped function.
        names = set(inspect.unwrap(ca._vault_sweep_run).__code__.co_names)
        self.assertIn("vault_seen_load", names)
        self.assertIn("vault_seen_save", names)
        # keyword names of a CALL are not always in co_names (they can sit in co_consts).
        # the unique call form is: prior_seen=_prior_seen
        src = inspect.getsource(ca._vault_sweep_run)
        self.assertEqual(src.count("prior_seen=_prior_seen"), 1)


class TestV2053TheSpaceWardenNeverEatsHisFootage(unittest.TestCase):
    """Konyo, after a stuck Playwright run wrote 60,232 files / 9.5 GB into test-results/ in 95
    minutes and took his disk from 14 GB free to 2.8 GB: "is there a way we can do this
    automatically ... so we dont hit cap limit again?"

    Three pruners already existed and each owned something different — reel_retention owns reels,
    _prune_loop owns loose live frames, the ledger snapshot owns backups. Playwright's output had NO
    OWNER, so it grew unbounded and uncomplaining. The gap was an owner, not a policy.

    THE RULE THAT MAKES IT SAFE UNATTENDED: auto-delete only what a NAMED COMMAND can regenerate;
    propose everything else. A reel of his farming is regenerable by nothing, and no amount of
    free-space pressure changes that. [[feedback-fixtures-never-touch-live-data]]
    """

    def _sw(self):
        import space_warden
        return space_warden

    def test_his_footage_is_never_in_the_auto_tier(self):
        sw = self._sw()
        auto = [p for p, _ in sw.AUTO]
        for bad in ("tv/frames", "tv/frames/hist", "tv/frames/corpus", "art", ".git"):
            self.assertNotIn(bad, auto, "%s is in the AUTO delete tier" % bad)
        rows = sw.survey()["rows"]
        for r in rows:
            if r["path"].startswith("tv/frames"):
                self.assertEqual(r["tier"], "propose",
                                 "%s is not in the propose tier — it could be deleted" % r["path"])
                self.assertFalse(r["safe"], "%s is marked safe to auto-delete" % r["path"])

    def test_every_auto_path_names_the_command_that_regenerates_it(self):
        """If you cannot name that command, the path is not output — it is someone's data."""
        sw = self._sw()
        for path, regen in sw.AUTO:
            self.assertTrue(str(regen or "").strip(),
                            "%s is auto-deletable with no stated way to get it back" % path)

    def test_a_path_outside_the_repo_is_refused(self):
        sw = self._sw()
        ok, why = sw._safe("../../../etc")
        self.assertFalse(ok, "a path escaping the repo was accepted")
        self.assertIn("OUTSIDE", why)

    def test_a_TRACKED_path_is_refused_even_if_listed(self):
        """Being on the AUTO list is a proposal, not a warrant — git decides.

        A first cut used bible.html, which is refused EARLIER for not being gitignored, so the
        tracked-file check was never reached and deleting it left the test green. git's two answers
        are mocked here so this case can only pass by reaching the second one."""
        import collections
        import unittest.mock as mock
        sw = self._sw()
        R = collections.namedtuple("R", "returncode stdout")

        def fake_run(argv, **kw):
            if "check-ignore" in argv:
                return R(0, "")                      # git DOES ignore it
            if "ls-files" in argv:
                return R(0, "test-results/kept.txt\n")   # ...but a file inside is TRACKED
            return R(0, "0\t.")

        # a path that EXISTS — _safe short-circuits on "absent" before it ever asks git, so a
        # missing directory would pass this test for the wrong reason.
        #
        # v2065 — AND IT MUST NOT BE ON THE **NEVER** LIST, which is this docstring's own scar
        # arriving one layer up. The candidate list used to be
        # ("playwright-report", "node_modules", "tv"). `playwright-report` exists only after a local
        # Playwright run; once it was gone the list fell through to `node_modules`, which _safe
        # refuses EARLY with "lives under node_modules" — so the tracked-file check was never
        # reached and the assertion failed on a refusal it was not testing.
        #
        # The test was therefore green or red depending on whether a build artifact happened to be
        # on disk, which is not a property of the code at all. Candidates are now filtered against
        # sw.NEVER so the chosen path can only be refused for the reason under test.
        import os as _os
        target = next((d for d in ("playwright-report", "test-results", "tv")
                       if _os.path.isdir(_os.path.join(sw.REPO, d))
                       and not any(d == n or d.startswith(n.rstrip("/") + "/") for n in sw.NEVER)),
                      None)
        self.assertTrue(target, "no existing, non-NEVER directory to test against")
        self.assertFalse(any(target == n or target.startswith(n.rstrip("/") + "/") for n in sw.NEVER),
                         "%r is on the NEVER list, so it is refused before the tracked-file check "
                         "and this test would pass for the wrong reason" % target)
        with mock.patch.object(sw.subprocess, "run", fake_run):
            ok, why = sw._safe(target)
        self.assertFalse(ok, "a path with tracked files inside it was accepted for deletion")
        self.assertIn("tracks", why, "the refusal does not say git tracks something: %r" % why)

    def test_a_path_git_does_not_ignore_is_refused(self):
        sw = self._sw()
        ok, why = sw._safe("tv")
        self.assertFalse(ok, "a non-ignored directory was accepted for deletion")

    def test_it_does_nothing_while_there_is_room(self):
        """A full test-results/ is a debugging aid until space is actually short."""
        import unittest.mock as mock
        sw = self._sw()
        with mock.patch.object(sw, "_free_gb", lambda: sw.FLOOR_GB + 50):
            out = sw.reclaim(dry_run=False)
        self.assertFalse(out.get("acted"), "it deleted things while the disk had room")
        self.assertIn("above the", out["why"])

    def test_a_dry_run_deletes_nothing(self):
        import unittest.mock as mock
        sw = self._sw()
        with mock.patch.object(sw, "_free_gb", lambda: 1.0):
            out = sw.reclaim(dry_run=True)
        self.assertTrue(out.get("dryRun"))
        self.assertFalse(out.get("acted"))

    def test_an_unreadable_free_space_does_nothing(self):
        """'I could not measure' must never resolve to 'delete it'. [[unknown-stays-unknown]]"""
        import unittest.mock as mock
        sw = self._sw()
        with mock.patch.object(sw, "_free_gb", lambda: None):
            out = sw.reclaim(dry_run=False)
        self.assertFalse(out.get("acted"))
        self.assertIn("could not read", out["why"])

    def test_the_warden_loop_is_actually_started(self):
        self.assertTrue(_watcher_is_armed("tvd-space-warden", "_warden_loop"),
                        "the warden loop is never started")



class TestV2055NotOpenIsNotDoomed(unittest.TestCase):
    """v2044's check answered "the board is an UNCLAIMED guest world — anything applied here is lost
    on the next launch" whenever he simply was not looking at the board.

    `_D2R_OWNER` and `_D2R_PFX` are bible.html globals. On the CONSOLE RAIL they do not exist, so
    both read falsy. Measured live 2026-08-24: pfx=None while d2r_ownerClaim was '*' on disk and the
    ledger sat in BARE keys — claimed, persisted, entirely safe, and reported as doomed. After the
    night his ledger actually WAS emptied, that is the last sentence in this console that should
    ever be shown wrongly. [[unknown-stays-unknown]]
    """

    def _cd(self):
        import console_doctor
        return console_doctor

    COUNTS = {"foundLog": 390, "owned": 5, "setPieces": 121}

    def _ask(self, payload):
        import unittest.mock as mock
        cd = self._cd()
        with mock.patch.object(cd, "_post", lambda *a, **k: payload):
            return cd._check_the_board_world_is_claimed()

    def test_the_board_not_being_open_is_UNKNOWN_not_a_warning(self):
        state, why = self._ask({"ok": True, "boardLoaded": False, "owner": False, "pfx": None,
                                "counts": self.COUNTS})
        cd = self._cd()
        self.assertEqual(state, cd.UNKNOWN,
                         "a console showing the rail was told its vault will evaporate")
        self.assertIn("not open", why)

    def test_a_REAL_unclaimed_world_still_raises_the_alarm(self):
        """The alarm must survive. Silencing it would be worse than the false positive."""
        state, why = self._ask({"ok": True, "boardLoaded": True, "owner": False,
                                "pfx": "I\u00b7abc12345\u00b7", "counts": self.COUNTS})
        cd = self._cd()
        self.assertEqual(state, cd.MISSING,
                         "a genuinely unclaimed guest world is no longer flagged — that is the "
                         "state that cost him his ledger")
        self.assertIn("This browser is mine", why)

    def test_a_claimed_board_passes(self):
        state, why = self._ask({"ok": True, "boardLoaded": True, "owner": True, "pfx": "",
                                "counts": self.COUNTS})
        self.assertEqual(state, self._cd().OK)

    def test_an_older_console_without_the_field_gets_the_RIGHT_reason(self):
        """boardLoaded absent must not be read as False — that is a guess, not a measurement.

        Both answers are UNKNOWN, so asserting the STATE alone cannot tell them apart: a first cut
        did exactly that and passed against `if not got.get("boardLoaded")`. The distinction is the
        EXPLANATION — an old console has not been asked; it is not a console with a closed board."""
        state, why = self._ask({"ok": True, "counts": self.COUNTS})
        cd = self._cd()
        self.assertEqual(state, cd.UNKNOWN)
        self.assertIn("predates", why,
                      "an older console was told its BOARD is closed, when the truth is this "
                      "console cannot answer the question at all: %r" % why)
        self.assertNotIn("not open", why)

    def test_board_ownership_actually_reports_the_flag(self):
        here = os.path.dirname(os.path.abspath(__file__))
        src = open(os.path.join(here, "control_app.py"), encoding="utf-8").read()
        blk = _between(self, src, "def board_ownership", "def board_tick", what="board_ownership")
        self.assertTrue("boardLoaded:boardLoaded" in blk,
                        "the flag is never put in the payload, so the doctor cannot use it")
        self.assertTrue("typeof window._D2R_PFX==='string'" in blk,
                        "boardLoaded is not derived from whether bible.html's globals exist")



class TestV2058ThePruneStaysOffUntilItCanSeeATooltip(unittest.TestCase):
    """v2037's rolling prune was deleting the only frames that carry item names, and I shipped it.

    It dropped a frame when `sig_diff(kept, this) <= 0.02` using sig_diff at its DEFAULT tol=28. At
    that tolerance a D2R hover tooltip moves the whole-frame jpeg_sig by LITERALLY ZERO. A stash grid
    prints no names, so the tooltip is the only place a name exists — meaning the prune's
    "these are identical" rule selected almost exactly the frames the vault lane exists to read.

    MEASURED on reel_s_1787520892804_95400: f_1787520897795, f_1787520899289 and f_1787520901207
    produced three DIFFERENT owned rows ("Sullied Grand Charm of Blight", "Chaotic Grand Charm of
    Incineration", "Chaotic Grand Charm") and are pairwise 0.00000 apart at tol=28. Replaying the
    loop's own constants drops 67 frames from that reel including four witness frames, each the
    SECOND session for one of his seven owned rows — four rows would fall under law 2 and never be
    proposed.

    v2032 had already recorded this blindness and the sweep works around it with panel_gate.
    _prune_once never called panel_gate and ran UPSTREAM of the workaround.

    ⚠ v2037's own safety number ("worst loss 0.0117") was computed with THE SAME BLIND INSTRUMENT.
    Measuring tooltip frames with a signature that cannot see tooltips returns the reassuring answer
    it is incapable of not giving. [[feedback-suspect-the-instrument]]
    """

    def _ca(self):
        import control_app
        return control_app

    def test_the_prune_may_only_run_WITH_the_per_frame_proof(self):
        """v2154 REPLACES "it must be off" WITH "it must be proven".

        v2058's own words were not "never prune again" — they were "OFF until it can prove, per
        frame, that it is not deleting a panel. Disk is not worth a name." A permanent OFF is a
        different rule from the one that was written, and it left 609 MB locked and ON AIR
        refusing below the floor, which is the cost side he actually feels.

        So the law is now conditional, and the condition is the one v2058 named. If the switch is
        on, _prune_once MUST consult the panel gate. If it does not, this fails whichever way the
        switch is set."""
        ca = self._ca()
        names = set(ca._prune_once.__code__.co_names)
        # ⚠⚠ v2984 — THIS VOCABULARY WENT STALE AND THE LAW COULD NO LONGER GO RED FOR THE RIGHT
        # REASON. It accepted only {stash_screen_open, stash_screen_open_cached, panel_gate}. v2172
        # replaced all three with `stash_panel_verdict` (the three-state gate), so the moment anyone
        # armed the prune this refused — not because the panel check was missing, but because it had
        # been RENAMED. Measured on the live function: co_names carries `stash_panel_verdict`,
        # `_gate_receipt`, `_GATE_LAST` and `LaneCanary`, and none of the three old names exists
        # anywhere in the tree. A law that names a dead vocabulary is a law that has stopped reading
        # the code. [[source-reading-guard]] [[label-outlived-referent]]
        # The OLD names are KEPT in the set on purpose: if the gate is ever reverted to them the law
        # must still pass, because what it protects is "does it ask", not "what is it called".
        consults = bool({"stash_screen_open", "stash_screen_open_cached", "panel_gate",
                         "stash_panel_verdict"} & names)
        if ca._PRUNE_SAFE_TO_RUN or ca._PRUNE_STATS.get("enabled"):
            self.assertTrue(consults,
                            "the prune is armed and _prune_once still never asks whether the "
                            "frame it is deleting shows a stash panel — that is the v2037 defect "
                            "exactly, and it costs item names, not disk")
            # ⚠ v2984 — `_PANEL_UNKNOWN` was the two-state sentinel. v2172's gate answers THREE
            # ways instead ("panel" / text-but-no-panel / "broke" / silent), so the protection now
            # lives in the branches, not in one constant. Pinned where it actually is: an
            # unreadable frame must be KEPT, and that is `_why == "broke"` -> continue.
            self.assertIn("LaneCanary", names,
                          "armed without the OCR-liveness proof: a blank frame and a frame nobody "
                          "could read are the same observation without it, and the blank class is "
                          "the one this deletes from")
            _src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                     "control_app.py"), encoding="utf-8").read()
            self.assertIn('if _why == "broke":', _src,
                          "the gate's BROKE state no longer forces a keep, so a frame that was "
                          "never read could be deleted as a spare one")

    def test_the_refusal_is_CODE_not_only_a_flag(self):
        """A flag is data and data gets flipped. The loop must refuse on its own."""
        here = os.path.dirname(os.path.abspath(__file__))
        src = open(os.path.join(here, "control_app.py"), encoding="utf-8").read()
        blk = _between(self, src, "def _prune_loop():", "def vault_seen_load",
                       what="the prune loop")
        self.assertTrue("if not _PRUNE_SAFE_TO_RUN:" in blk,
                        "the loop no longer refuses independently of the enabled flag")

    def test_it_may_only_be_re_armed_once_it_consults_the_panel_gate(self):
        """The ONE condition. Re-arming without a per-frame panel check repeats the defect."""
        ca = self._ca()
        names = set(ca._prune_once.__code__.co_names)
        # ⚠⚠ v2984 — THIS VOCABULARY WENT STALE AND THE LAW COULD NO LONGER GO RED FOR THE RIGHT
        # REASON. It accepted only {stash_screen_open, stash_screen_open_cached, panel_gate}. v2172
        # replaced all three with `stash_panel_verdict` (the three-state gate), so the moment anyone
        # armed the prune this refused — not because the panel check was missing, but because it had
        # been RENAMED. Measured on the live function: co_names carries `stash_panel_verdict`,
        # `_gate_receipt`, `_GATE_LAST` and `LaneCanary`, and none of the three old names exists
        # anywhere in the tree. A law that names a dead vocabulary is a law that has stopped reading
        # the code. [[source-reading-guard]] [[label-outlived-referent]]
        # The OLD names are KEPT in the set on purpose: if the gate is ever reverted to them the law
        # must still pass, because what it protects is "does it ask", not "what is it called".
        consults = bool({"stash_screen_open", "stash_screen_open_cached", "panel_gate",
                         "stash_panel_verdict"} & names)
        if ca._PRUNE_SAFE_TO_RUN:
            self.assertTrue(consults,
                            "the prune is armed but _prune_once still never asks whether the frame "
                            "it is deleting shows a stash panel — that is exactly the v2037 defect")

    def test_the_blindness_that_caused_it_is_real_and_recorded(self):
        """Guard the FACT, so nobody re-derives 0.02/tol=28 as safe from first principles."""
        import chronicle_retro as cr
        import inspect
        sig = inspect.signature(cr.sig_diff)
        self.assertEqual(sig.parameters["tol"].default, 28,
                         "sig_diff's default tol changed — the measurement behind this guard "
                         "(a tooltip moving the signature by 0.00000) was taken at tol=28")



class TestV2060TheSealWaitsForTheLedger(unittest.TestCase):
    """v1779 SAID it had moved the swept marker after the ledger write. Its diff did not, and the
    failure message went on telling him "the reels stay unswept so nothing is lost" while both seal
    sites still ran ~56 lines EARLIER. A failed ledger save therefore sealed the reels anyway and
    the paid reads were gone for good — the precise loss that note claims to prevent.

    This guard is about CALL ORDER, read off the AST, so no comment or ship note can satisfy it.
    [[source-reading-guard]] §1 · [[label-outlived-referent]]"""

    def _fn(self):
        import ast
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "control_app.py")
        with open(_p, "r", encoding="utf-8") as _fh:
            src = _fh.read()
        fns = [n for n in ast.walk(ast.parse(src))
               if isinstance(n, ast.FunctionDef) and n.name == "_vault_sweep_run"]
        self.assertEqual(len(fns), 1, "_vault_sweep_run is not there under that name — this guard "
                                      "would then pass by being blind")
        return fns[0]

    def test_no_seal_is_persisted_before_the_ledger_is_down(self):
        import ast
        fn = self._fn()
        seals, ledgers = [], []
        for n in ast.walk(fn):
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name):
                if n.func.id == "_vault_swept_save":
                    seals.append(n.lineno)
                elif n.func.id == "vault_ledger_save":
                    ledgers.append(n.lineno)
        self.assertTrue(seals, "the sweep seals nothing at all — every reel would be re-read, and "
                               "paid for, forever")
        self.assertEqual(len(ledgers), 1,
                         "expected exactly one vault_ledger_save call to order against, got %d — "
                         "the ordering claim is meaningless with more" % len(ledgers))
        early = [ln for ln in seals if ln < ledgers[0]]
        self.assertEqual(early, [],
                         "control_app.py:%s seals the reels BEFORE the ledger write at :%d. If that "
                         "write then fails, the footage is marked read and its rows never landed."
                         % (early, ledgers[0]))

    def test_the_failure_message_no_longer_claims_the_reels_are_unswept(self):
        """A right rule under a dead reason is still a lie about the system. Checked against the
        function's STRING CONSTANTS, never its prose, so the guard cannot trip on its own text."""
        import ast
        fn = self._fn()
        consts = [n.value for n in ast.walk(fn)
                  if isinstance(n, ast.Constant) and isinstance(n.value, str)]
        stale = [c for c in consts if "stay unswept so nothing is lost" in c]
        self.assertEqual(stale, [], "the failure message still tells him nothing was lost")


class TestV2062OneDeletionAuthority(unittest.TestCase):
    """Three things could delete his footage and each had a different idea of "safe". The prune kept
    a frame only when it LOOKED different from the one before — and a hover tooltip, the only place
    D2R writes an item name, moves that number by zero. frame_authority asks the question that
    actually decides it: IS THIS FRAME EVIDENCE.

    Every case below runs on a FIXTURE TREE built in tmp. Nothing here reads or writes his reels,
    his ledger or his seal store. [[feedback-fixtures-never-touch-live-data]]"""

    def _tree(self, sealed=None, accum=None, seen=None, reels=None, broken=()):
        import tempfile, shutil, json as _j
        root = tempfile.mkdtemp(prefix="fa_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        for name, frames in (reels or {}).items():
            d = os.path.join(hist, "reel_" + name)
            os.makedirs(d)
            for f in frames:
                with open(os.path.join(d, f), "wb") as fh:
                    fh.write(b"x" * 1000)
        for fn, blob in (("vault_swept.json", sealed if sealed is not None else {}),
                         ("vault_accum.json", {"owned": accum or []}),
                         ("vault_seen.json", {"rows": seen or []})):
            with open(os.path.join(root, fn), "w", encoding="utf-8") as fh:
                _j.dump(blob, fh)
        for fn in broken:
            with open(os.path.join(root, fn), "w", encoding="utf-8") as fh:
                fh.write("{ this is not json")
        return root, hist

    def _mod(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import frame_authority
        return frame_authority

    # six reels so KEEP_RECENT=5 still leaves one old reel to reason about
    # ⚠⚠ v2876 — SIZED FROM KEEP_RECENT. This was six reels, chosen when the shield held five
    # so that exactly ONE fell outside it. Konyo raised the shield to 8 and all six went
    # inside, so "only the oldest may be offered" got an empty set and two laws went red on a
    # correct tree. The oldest keeps TWO frames because the witness law needs one frame that
    # witnessed and one that did not. [[feedback-blind-fixture-green-gate]]
    import reel_retention as _rr_keep
    _REELS = dict([("s_1000_1", ["f_1.jpg", "f_2.jpg"])] +
                  [("s_%d_%d" % ((i + 2) * 1000, i + 2), ["f_%d.jpg" % (i + 3)])
                   for i in range(_rr_keep.KEEP_RECENT)])

    def test_a_witness_frame_in_a_sealed_reel_is_never_prunable(self):
        """The row survives extraction — but the frame is the only way to ever SHOW him why the row
        is there, which is the retro debugging he asked for by name."""
        fa = self._mod()
        root, hist = self._tree(
            sealed={"s_1000_1": {"ts": 1, "rows": 1, "extracted": ["name", "location", "provenance"]}},
            accum=[{"name": "Shako", "witnesses": [{"session": "s_1000_1", "frame": "f_1.jpg"}]}],
            reels=self._REELS)
        # ⚠ held_reels={} — see the note on the recency test: this law is about the WITNESS rule,
        # and the cross-module evidence hold is gated separately.
        p = fa.plan_frames(hist, root=root, held_reels=set())
        names = [os.path.basename(f) for f in p["prunable"]]
        self.assertNotIn("f_1.jpg", names, "a witness frame was offered up for deletion")
        self.assertIn("f_2.jpg", names,
                      "f_2 is in the same SEALED reel and witnessed nothing — it should be prunable, "
                      "or the authority frees nothing and is just the disabled prune again")

    def test_an_unsealed_reel_is_never_touched(self):
        fa = self._mod()
        root, hist = self._tree(sealed={}, reels=self._REELS)
        p = fa.plan_frames(hist, root=root)
        self.assertEqual(p["prunable"], [],
                         "frames were offered from reels the sweep has never sealed — those pixels "
                         "may be the only copy of a name")

    def test_the_newest_five_recordings_are_held_even_when_sealed(self):
        fa = self._mod()
        root, hist = self._tree(sealed={k: {"ts": 1, "rows": 0, "extracted": ["name", "location", "provenance"]} for k in self._REELS},
                                reels=self._REELS)
        # ⚠ held_reels={} ISOLATES THE CROSS-MODULE HOLD, deliberately. v2740 taught plan_frames to
        # refuse frames in a reel reel_retention holds for an EVIDENCE reason; reel_retention
        # derives durability from the LIVE tree, so a fixture cannot state its own answer. This
        # test is about THIS module's recency rule, so the external input is supplied rather than
        # guessed. That rule has its own gate: tv/test_frames_respect_evidence_holds.py.
        p = fa.plan_frames(hist, root=root, held_reels=set())
        held = {os.path.basename(os.path.dirname(f)) for f in p["prunable"]}
        self.assertEqual(held, {"reel_s_1000_1"},
                         "only the single OLDEST reel may be offered; the newest five are held "
                         "whatever the seal store says")

    def test_an_unreadable_store_holds_everything(self):
        """The fail-safe direction. 'I could not tell' must never resolve to 'delete it'."""
        fa = self._mod()
        root, hist = self._tree(sealed={k: {"ts": 1} for k in self._REELS}, reels=self._REELS,
                                broken=("vault_accum.json",))
        p = fa.plan_frames(hist, root=root)
        self.assertFalse(p["witnessOk"], "an unparsable durable store must be reported, not skipped")
        self.assertEqual(p["prunable"], [],
                         "frames were offered while the witness list was incomplete — that deletes "
                         "on the strength of a file it could not open")

    def test_an_unreadable_seal_store_frees_nothing_and_says_so(self):
        fa = self._mod()
        root, hist = self._tree(reels=self._REELS, broken=("vault_swept.json",))
        p = fa.plan_frames(hist, root=root)
        self.assertFalse(p["sealOk"])
        self.assertEqual(p["prunable"], [])
        self.assertIn("could not be read", p["say"])

    def test_the_authority_is_actually_CALLED_by_the_console(self):
        """A module built right and called by nothing reads as wired from both ends and carries
        nothing. Asked of the COMPILER (co_names), not of the text, so a comment naming
        frame_authority cannot satisfy it. [[the-unjoined-end]] [[source-reading-guard]] §1"""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app as _ca
        self.assertTrue(hasattr(_ca, "prune_reclaimable"),
                        "the console has no reader for the authority at all")
        names = set(_ca.prune_reclaimable.__code__.co_names)
        self.assertIn("frame_authority", names,
                      "prune_reclaimable does not reference frame_authority")
        self.assertIn("plan_frames", names, "it imports the authority and never asks it anything")
        loop = set(_ca._prune_loop.__code__.co_names)
        self.assertIn("prune_reclaimable", loop,
                      "_prune_loop never calls prune_reclaimable, so while deleting is refused the "
                      "console can only ever report a zero — and 'off' then looks exactly like "
                      "'nothing to free'")

    def test_the_authority_answers_on_the_real_tree(self):
        """Not a fixture: the shipped console, his actual seal store and reels. A planner that only
        ever ran on tmp is a planner whose real answer nobody has seen."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app as _ca
        r = _ca.prune_reclaimable()
        self.assertTrue(r.get("ok"), "the authority could not answer on the real tree: %s" % r.get("why"))
        self.assertIsInstance(r.get("frames"), int)
        self.assertGreaterEqual(r.get("scanned", 0), 0)
        self.assertLessEqual(r["frames"], r["scanned"], "it offered more frames than it scanned")

    def test_reel_retention_ASKS_the_authority_instead_of_keeping_its_own_copy(self):
        """v2062 called frame_authority "the one deletion authority" and then wired only the frame
        prune to it — leaving reel_retention, the deleter that removes WHOLE REELS, reading its own
        private copy of the same two stores. Two copies of one rule is how they drift, and these two
        already differed: reel_retention swallowed an unreadable store silently, so "no witnesses"
        and "could not read the ledger" were the same answer.

        They agreed on his tree the day this was written, which is exactly when a duplicate is
        cheapest to remove and hardest to notice. Asked of the COMPILER, so a comment naming the
        module cannot satisfy it. [[copy-drift]] [[source-reading-guard]] §1"""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import reel_retention as _rr
        names = set(_rr._durable_sessions.__code__.co_names)
        self.assertIn("frame_authority", names,
                      "reel_retention._durable_sessions does not reference frame_authority — the "
                      "rule has two homes again")
        self.assertIn("witness_index", names,
                      "it imports the authority and never asks it anything")

    def test_the_two_deleters_cannot_disagree_about_what_is_durable(self):
        """The property the unification exists for, checked on the real tree rather than asserted."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import reel_retention as _rr
        import frame_authority as _fa
        here = os.path.dirname(os.path.abspath(__file__))
        # v2079 — _durable_sessions now returns (sessions, ok). The `ok` is the half that was being
        # dropped on the floor: it is False only when a durable store EXISTS AND WILL NOT PARSE, and
        # the caller holds every reel when it is. Both halves are compared, because agreeing about
        # the sessions while disagreeing about whether the index is complete is still a disagreement.
        idx = _fa.witness_index(here)
        # v2080 — three values now: the third is WHY, because "ok=False" was being reported with a
        # reason naming two files that may be perfectly readable (frame_authority failing to import
        # produces the same False). Right hold, wrong reason is still a wrong report.
        sessions, ok, why = _rr._durable_sessions(here)
        self.assertTrue(why is None or isinstance(why, str))
        self.assertEqual(sessions, set(idx.get("sessions") or ()),
                         "the reel deleter and the frame deleter disagree about which recordings "
                         "are durable — one of them is about to be wrong")
        self.assertEqual(ok, bool(idx.get("ok")),
                         "they disagree about whether the durable index is even COMPLETE")

    def test_it_deletes_nothing_itself(self):
        """A planner that deletes is a deleter. The whole point is that the acting stays with the
        caller, and there is exactly one place that decides."""
        import ast
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "frame_authority.py")
        with open(_p, "r", encoding="utf-8") as _fh:
            src = _fh.read()
        bad = []
        for n in ast.walk(ast.parse(src)):
            if isinstance(n, ast.Call):
                f = n.func
                nm = (f.attr if isinstance(f, ast.Attribute) else
                      f.id if isinstance(f, ast.Name) else "")
                if nm in ("remove", "unlink", "rmtree"):
                    bad.append((nm, n.lineno))
        self.assertEqual(bad, [], "frame_authority calls a deleter at %s — it decides, it never acts" % bad)


class TestV2063DoNotRecordAGameThatIsNotRunning(unittest.TestCase):
    """Konyo: "the shadow reader ... needs to know when diablo ii window is open so it doesnt just
    record for free".

    v899 built this check and spent it on the wrong half — its own comment reads "NO D2R WINDOW:
    film may keep running, but AI reads stay OFF". So the paid lane was protected and the DISK lane
    was not: with the game shut, frames landed at the full rate and the only thing that ever stopped
    them was running out of disk.

    Driven through the real function against a TMP reel dir. Nothing here touches his footage.
    [[feedback-fixtures-never-touch-live-data]]"""

    def setUp(self):
        import tempfile, shutil
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import tv_diablo
        self.t = tv_diablo
        self.tmp = tempfile.mkdtemp(prefix="nogame_")
        self.addCleanup(shutil.rmtree, self.tmp, True)
        self.hist = os.path.join(self.tmp, "hist")
        os.makedirs(self.hist)
        self.src = os.path.join(self.tmp, "live.jpg")
        with open(self.src, "wb") as fh:
            fh.write(b"\xff\xd8\xff" + b"J" * 9000)      # past the 4000-byte floor
        # point the archiver at the fixture and restore whatever was there
        self._old = {k: self.t.__dict__.get(k) for k in
                     ("HIST_DIR", "_FOOTAGE_WARM", "_GAME_OK", "_NOGAME_TAIL_KEPT", "_NOGAME_SKIPPED")}
        self.addCleanup(self._restore)
        self.t.HIST_DIR = self.hist
        self.t._FOOTAGE_WARM = True          # warm-up is v1548's gate, not this one
        # v2080 — AND NEITHER IS THE DISK. These five cases are about the GAME-WINDOW gate, and
        # every one of them went red on his Mac writing 0 frames — not because the gate was wrong
        # but because free space had fallen under MIN_FREE_GB (8 GB) and the archiver refuses to
        # record at all below it. A test that reports "the gate refused frames while the game was
        # OPEN" when the real answer is "the disk is full" is a gate going red for a NEIGHBOUR's
        # reason, which is the exact class the fixture canary was written to stop.
        # The disk governor is a real rule with its own tests; it must not be able to decide this
        # one. [[regression-guard]] [[feedback-blind-fixture-green-gate]]
        self._old["MIN_FREE_GB"] = self.t.__dict__.get("MIN_FREE_GB")
        self.t.MIN_FREE_GB = 0
        self.t._NOGAME_TAIL_KEPT = 0
        self.t._NOGAME_SKIPPED = 0
        for k in ("TV_STUB", "TV_NO_GAME_GUARD"):
            if os.environ.get(k):
                self.skipTest("%s is set — the guard is deliberately disabled for harnesses" % k)

    def _restore(self):
        for k, v in self._old.items():
            if v is None:
                self.t.__dict__.pop(k, None)
            else:
                self.t.__dict__[k] = v

    def _count(self):
        return len([f for f in _fx_tmp.list_own(self.hist) if f.startswith("f_")])

    def _shoot(self, n, ts0=1000.0):
        """n archive attempts; returns how many frames are on disk afterwards."""
        for i in range(n):
            self.t._archive_footage_copy(self.src, ts0 + i, why="test", _consume_due=False)
        return self._count()

    def test_with_the_game_open_it_records(self):
        self.t._GAME_OK = True
        self.assertEqual(self._shoot(5), 5,
                         "the gate refused frames while the game was OPEN — that loses real footage")

    def test_with_the_game_shut_it_keeps_a_short_tail_then_stops(self):
        self.t._GAME_OK = False
        got = self._shoot(40)
        self.assertEqual(got, self.t.NOGAME_TAIL_FRAMES,
                         "with no D2R window it wrote %d frames; the tail is %d and then it must "
                         "stop. Anything more is recording for nothing." % (got, self.t.NOGAME_TAIL_FRAMES))
        self.assertGreater(int(self.t.__dict__.get("_NOGAME_SKIPPED") or 0), 0,
                           "it stopped recording but counted no skips, so the console cannot tell "
                           "him WHY the reel went quiet")

    def test_the_tail_exists_at_all(self):
        """The window vanishing IS the event worth filming. v1548 makes the same argument for the
        other end of a session: a blank frame LATER is a crash, not startup noise."""
        self.t._GAME_OK = False
        self.assertGreater(self._shoot(1), 0,
                           "it stopped instantly, so the frames that show WHAT HAPPENED are gone")

    def test_when_the_game_comes_back_the_tail_RE_ARMS_for_the_next_absence(self):
        """The first cut of this test only checked that recording RESUMED, and a sabotage that
        deleted the reset passed it — resuming happens anyway, because the open-game branch archives
        regardless. What the reset actually buys is a fresh tail the SECOND time the window goes,
        so the test has to play the whole cycle: shut, exhaust, reopen, shut again."""
        tail = self.t.NOGAME_TAIL_FRAMES
        self.t._GAME_OK = False
        self._shoot(40)                                  # burn the first tail
        self.assertEqual(self._count(), tail)
        self.t._GAME_OK = True
        self._shoot(3, ts0=5000.0)                       # game is back: records normally
        self.assertEqual(self._count(), tail + 3, "it did not resume recording when the game returned")
        self.t._GAME_OK = False                          # and away again
        self._shoot(40, ts0=9000.0)
        self.assertEqual(self._count(), tail + 3 + tail,
                         "the second absence got no tail, so the frames showing what happened the "
                         "second time are gone — the gate never re-armed")

    def test_an_unmeasured_gate_fails_OPEN(self):
        """_GAME_OK is unset until _set_game_gate has run. A lane that has not measured yet must
        never be the reason footage is lost."""
        self.t.__dict__.pop("_GAME_OK", None)
        # MORE than the tail, deliberately: shooting fewer than NOGAME_TAIL_FRAMES cannot tell a
        # fail-open gate from a fail-closed one, because the tail would let them through either way.
        # A sabotage flipping the default to False passed the first version of this test.
        n = self.t.NOGAME_TAIL_FRAMES + 5
        self.assertEqual(self._shoot(n), n, "an UNSET game gate suppressed footage")


class TestV2064TheLedgerSaysWHENTheAiSawIt(unittest.TestCase):
    """Konyo: "the ledger should tell us when it was seen by AI so we can see visually in retro and
    visually debug in retro if needed surgically anything."

    The console vault row printed "2 witness(es)" and nothing about WHEN, so a sighting from tonight
    and one from three weeks ago read identically, and a row he wanted to check against the game had
    nothing pointing at the frames that produced it.

    RUNS THE REAL SHIPPED FUNCTION under node — not a grep, and not a copy. The renderer lives inside
    a large IIFE so it is unreachable from the page scope; extracting it by BRACE BALANCE (never a
    byte window) is what makes this testable at all. [[source-reading-guard]] §3"""

    def _render(self, rows):
        import json as _json, shutil as _sh, subprocess as _sp, tempfile as _tf
        node = _sh.which("node")
        if not node:
            self.skipTest("node is not installed on this machine")
        p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "control_ui.html")
        if not os.path.isfile(p):
            self.skipTest("control_ui.html is not on this machine")
        with open(p, encoding="utf-8") as fh:
            src = fh.read()

        def grab(sig):
            i = src.find(sig)
            self.assertGreater(i, 0, "%s is gone from control_ui.html" % sig)
            self.assertEqual(src.count(sig), 1, "%s appears more than once — the wrong copy would "
                                                "be extracted" % sig)
            j = src.index("{", i)
            depth = 0
            for k in range(j, len(src)):
                if src[k] == "{":
                    depth += 1
                elif src[k] == "}":
                    depth -= 1
                    if depth == 0:
                        return src[i:k + 1]
            self.fail("unbalanced braces reading %s" % sig)

        prog = ("\n\n".join([grab("function escC("), grab("function _agoMs("),
                              grab("function _vaultNames(")])
                + "\nconsole.log(JSON.stringify(_vaultNames(" + _json.dumps(rows) + ", true)));\n")
        with _tf.NamedTemporaryFile("w", suffix=".js", delete=False, encoding="utf-8") as f:
            f.write(prog)
            jp = f.name
        try:
            out = _sp.run([node, jp], capture_output=True, text=True, timeout=60)
            self.assertEqual(out.returncode, 0, out.stderr[:500])
            return _json.loads(out.stdout.strip().splitlines()[-1])
        finally:
            os.unlink(jp)

    NOW = 1787600000000

    def test_a_dated_sighting_shows_when_and_names_its_frames(self):
        html = self._render([{"name": "Harlequin Crest", "lane": "stash",
                              "witnesses": [{"frame": "f_111.jpg", "ts": self.NOW - 3 * 60000},
                                            {"frame": "f_222.jpg", "ts": self.NOW - 9 * 60000}],
                              "lastSeenTs": self.NOW - 3 * 60000}])
        self.assertIn("AI saw it", html, "the row does not say WHEN the AI saw it")
        self.assertIn("f_111.jpg", html,
                      "the row names no frame, so he cannot go back and look at what it read — "
                      "which is the whole point of debugging in retro")
        self.assertIn("f_222.jpg", html, "only one of two witness frames is reachable")
        self.assertIn("when the SIGHTING happened", html,
                      "nothing says the stamp is the age of the READ rather than of this render")

    def test_an_UNDATED_sighting_reads_UNKNOWN_and_is_never_called_recent(self):
        """A row nobody dated and a row seen this minute are opposite facts. Collapsing them is the
        lie with no author. [[unknown-stays-unknown]]

        v2065 REPOINTED THIS FIXTURE, and the reason matters: it used to carry a `session`, and a
        session now resolves to a RECORDING WINDOW rather than UNKNOWN — which is strictly better
        information, so the old expectation became wrong rather than the code. The intent is
        unchanged and still enforced here: a sighting whose time is not known must never render as
        recent. What changed is which input is genuinely unknown. See TestV2065."""
        html = self._render([{"name": "Stone of Jordan", "lane": "stash",
                              "witnesses": [{"conf": 0.44}]}])
        self.assertIn("UNKNOWN", html, "an undated sighting did not read UNKNOWN")
        self.assertNotIn("just now", html, "an undated sighting was rendered as recent")
        self.assertNotIn("AI saw it", html, "an undated sighting claimed a time it does not have")

    def test_a_row_with_no_witness_field_claims_nothing_either_way(self):
        html = self._render([{"name": "Shako", "lane": "stash"}])
        self.assertNotIn("AI saw it", html)
        self.assertNotIn("UNKNOWN", html,
                         "a row that never carried witnesses is not an undated sighting — saying "
                         "UNKNOWN there invents a reading that was never taken")

    def test_one_witness_is_not_written_as_witness_es(self):
        html = self._render([{"name": "Shako", "lane": "stash",
                              "witnesses": [{"frame": "f_1.jpg", "ts": self.NOW}]}])
        self.assertIn("1 witness<", html + "<", "singular row still reads '1 witness(es)'")


class TestV2065ABoundIsNotUnknown(unittest.TestCase):
    """17 of his 24 vault rows were rendering "AI sighting time UNKNOWN" — every ungrounded sighting,
    because they carry a session and no `ts`. But a recording id CONTAINS its own start time
    (s_<epoch_ms>_<n>), so the instant is unknown while the WINDOW is not.

    Reported as a recording, never as an instant. Rounding a range to a point is how a measurement
    becomes a claim it never earned. [[unknown-stays-unknown]]

    Reuses TestV2064's node harness, which runs the REAL shipped renderer."""

    NOW = 1787600000000

    def _render(self, rows):
        return TestV2064TheLedgerSaysWHENTheAiSawIt._render(self, rows)

    def test_a_session_only_sighting_reports_the_RECORDING_not_unknown(self):
        html = self._render([{"name": "Bone Visor", "lane": "stash",
                              "witnesses": [{"session": "s_1787520892804_95400"}]}])
        self.assertIn("in a recording from", html,
                      "a sighting that names its recording still read UNKNOWN — the window was "
                      "known and thrown away")
        self.assertNotIn("AI sighting time UNKNOWN", html)
        self.assertIn("s_1787520892804_95400", html,
                      "the recording is not named, so he cannot go and find it")

    def test_it_never_claims_an_INSTANT_it_does_not_have(self):
        html = self._render([{"name": "Bone Visor", "lane": "stash",
                              "witnesses": [{"session": "s_1787520892804_95400"}]}])
        self.assertNotIn("AI saw it 0m ago", html)
        self.assertNotIn("just now", html)
        self.assertIn("exact moment was not recorded", html,
                      "nothing tells him this is a window rather than a timestamp")

    def test_the_newest_recording_wins_when_there_are_several(self):
        html = self._render([{"name": "Enigma", "lane": "stash",
                              "witnesses": [{"session": "s_1784984019250_95276"},
                                            {"session": "s_1785078127173_28278"}]}])
        # s_1785078127173 = 2026-07-26, the newer of the two
        self.assertIn("2026", html)
        self.assertIn("s_1785078127173_28278", html)

    def test_an_exact_timestamp_still_beats_the_bound(self):
        """The bound is a fallback, not a replacement. A row that knows the instant must say the
        instant, or the good data is thrown away to make the rendering uniform."""
        html = self._render([{"name": "Harlequin Crest", "lane": "stash",
                              "witnesses": [{"session": "s_1787520892804_95400",
                                             "frame": "f_1.jpg", "ts": self.NOW}],
                              "lastSeenTs": self.NOW}])
        self.assertIn("AI saw it", html)
        self.assertNotIn("in a recording from", html,
                         "it downgraded an exact sighting time to a recording window")

    def test_a_witness_with_neither_a_ts_nor_a_recording_is_still_UNKNOWN(self):
        """The bound must not become a way of always having an answer."""
        html = self._render([{"name": "Mystery", "lane": "stash", "witnesses": [{"conf": 0.4}]}])
        self.assertIn("UNKNOWN", html)
        self.assertNotIn("in a recording from", html)

    def test_an_unparsable_recording_id_does_not_invent_a_date(self):
        html = self._render([{"name": "Odd", "lane": "stash",
                              "witnesses": [{"session": "not-a-session-id"}]}])
        self.assertIn("UNKNOWN", html,
                      "a recording id it could not parse produced a date anyway")
        self.assertNotIn("1970", html, "it fell back to the epoch and rendered 1970")


class TestV2067LookingAtTheLedgerIsFree(unittest.TestCase):
    """vault_ledger_load() had exactly ONE caller in the whole console — inside _vault_sweep_run — so
    the accumulated ledger, and every sighting time and frame id v2064/v2065 put on it, could only be
    seen as a SIDE EFFECT of paying for a sweep.

    Konyo: "i want it to visually render the backend through the ledger visually so we can visually
    surgically fix anything needed future wise."
    """

    def _ca(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app
        return control_app

    def _with_stores(self, accum, seen):
        """Point the view at FIXTURE stores. His real ledger is never read or written here.
        [[feedback-fixtures-never-touch-live-data]]"""
        import json as _j, tempfile, shutil
        import unittest.mock as mock
        ca = self._ca()
        root = tempfile.mkdtemp(prefix="ledgerview_")
        self.addCleanup(shutil.rmtree, root, True)
        ap = os.path.join(root, "vault_accum.json")
        sp = os.path.join(root, "vault_seen.json")
        for path, blob in ((ap, accum), (sp, seen)):
            if blob is None:
                continue                       # absent on purpose
            with open(path, "w", encoding="utf-8") as fh:
                if blob == "BROKEN":
                    fh.write("{ not json")
                else:
                    _j.dump(blob, fh)
        with mock.patch.object(ca, "VAULT_LEDGER_PATH", ap), \
             mock.patch.object(ca, "_VAULT_SEEN_PATH", sp):
            return ca.vault_ledger_view()

    def test_absent_unreadable_and_empty_are_three_different_answers(self):
        """vault_ledger_load() folds all three into {} — fine for the sweep, which only wants rows,
        and wrong for a viewer: "your ledger is empty" and "I could not open your ledger" must never
        look the same. [[unknown-stays-unknown]]"""
        absent = self._with_stores(None, None)
        self.assertEqual(absent["stores"]["accum"]["state"], "absent")
        self.assertIsNone(absent["stores"]["accum"]["ageS"],
                          "an absent store reported an age, which is a measurement it never took")

        empty = self._with_stores({"owned": []}, {"rows": []})
        self.assertEqual(empty["stores"]["accum"]["state"], "ok")
        self.assertEqual(empty["totals"]["owned"], 0)

        broke = self._with_stores("BROKEN", {"rows": []})
        self.assertTrue(broke["stores"]["accum"]["state"].startswith("unreadable"))
        self.assertIn("INCOMPLETE", broke["say"],
                      "a store that would not open was not announced — everything under it is "
                      "incomplete, not empty")

    def test_it_tallies_the_three_time_states_the_board_renders(self):
        v = self._with_stores(
            {"owned": [{"name": "A", "lastSeenTs": 1787600000000,
                        "witnesses": [{"frame": "f_1.jpg", "ts": 1787600000000}]}]},
            {"rows": [{"name": "B", "witnesses": [{"session": "s_1787520892804_95400"}]},
                      {"name": "C", "witnesses": [{"conf": 0.4}]}]})
        self.assertEqual(v["totals"]["when"], {"exact": 1, "recording": 1, "undated": 1},
                         "the tally disagrees with what the rows actually carry")
        self.assertEqual(v["totals"]["owned"], 1)
        self.assertEqual(v["totals"]["sightings"], 2)

    def test_the_age_belongs_to_the_STORE_not_to_this_call(self):
        """A ledger written three days ago is three days old however fresh the response is.
        [[stale-reading]]"""
        v = self._with_stores({"owned": []}, {"rows": []})
        self.assertIsNotNone(v["stores"]["accum"]["mtime"])
        self.assertLess(v["stores"]["accum"]["ageS"], 120,
                        "the fixture was written seconds ago and the store reports otherwise")
        self.assertIn("readTs", v, "nothing says when this READ happened, so the two ages cannot "
                                   "be told apart")

    def test_the_view_writes_nothing_and_calls_no_reader(self):
        """It exists so that LOOKING is free. A viewer that spends is not a viewer."""
        import ast
        ca = self._ca()
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "control_app.py")
        with open(_p, "r", encoding="utf-8") as fh:
            src = fh.read()
        fn = [n for n in ast.walk(ast.parse(src))
              if isinstance(n, ast.FunctionDef) and n.name == "vault_ledger_view"]
        self.assertEqual(len(fn), 1)
        called = {n.func.id for n in ast.walk(fn[0])
                  if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)}
        for banned in ("vault_ledger_save", "vault_seen_save", "_vault_json_save",
                       "claude_vault_read", "_vault_sweep_run"):
            self.assertNotIn(banned, called, "the free ledger view calls %s" % banned)

    def test_the_route_exists_and_is_wired_to_the_view(self):
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "control_app.py")
        with open(_p, "r", encoding="utf-8") as fh:
            src = fh.read()
        self.assertIn('path == "/api/vault_ledger"', src, "the route is gone")
        # bounded by the NEXT route, not by a byte count — a window sized in characters is a guess
        # about how long someone's comment is, and the meta-guard on byte-counted slices is right to
        # refuse new ones. [[source-reading-guard]] §3
        blk = _between(self, src, 'path == "/api/vault_ledger"', 'if path ==',
                       what="the vault_ledger route body")
        self.assertIn("vault_ledger_view()", blk, "the route does not call the view")

    def test_the_handler_can_actually_REACH_the_row_renderer(self):
        """The first cut of this handler was written beside the eagle's, which is a different
        closure from the one holding _vaultNames. It threw `_vaultNames is not defined` the moment
        it was clicked — a defect no amount of reading finds, because the call is spelled correctly.

        Checked STRUCTURALLY: the definition must sit inside the same closure as the renderer, so
        there must be no closure-closing `})();` between them."""
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "control_ui.html")
        with open(_p, "r", encoding="utf-8") as fh:
            ui = fh.read()
        self.assertEqual(ui.count("function _vaultNames("), 1)
        self.assertEqual(ui.count("window._ledgerView = async function"), 1)
        i = ui.index("function _vaultNames(")
        j = ui.index("window._ledgerView = async function")
        lo, hi = min(i, j), max(i, j)
        self.assertNotIn("})();", ui[lo:hi],
                         "a closure closes between _vaultNames and window._ledgerView, so the "
                         "handler cannot see the renderer it calls")
        self.assertIn("window._ledgerView", ui[ui.index("$('btn-ledger').onclick"):][:300],
                      "the button does not call the view function")

    def test_no_python_emoji_escape_survives_in_the_console_javascript(self):
        r"""JavaScript has no \U escape. `'\U0001F985 EAGLE EYE'` renders as the literal text
        "U0001F985 EAGLE EYE", which is what the eagle panel had been printing. Ten of these were in
        the file. [[feedback-generalize-fixes]]"""
        import re as _re
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "control_ui.html")
        with open(_p, "r", encoding="utf-8") as fh:
            ui = fh.read()
        bad = _re.findall(r"\\U0001[0-9A-Fa-f]{4}", ui)
        self.assertEqual(bad, [], "python-style emoji escapes render as literal text in JS: %s"
                         % sorted(set(bad)))


class TestV2068ARuleThatNeverRunsMustSaySo(unittest.TestCase):
    """The retention plan is a chain of REASONS NOT TO DELETE, checked in order, so an earlier one
    hides every later one. MEASURED on his 35 reels: 12 never-swept, 11 zero-pages, 5 recent, 1
    vault-owes, 6 eligible — and v2056's rule ("this reel produced rows and none are banked, so the
    frames ARE the record") fired ZERO times. On his data a working v2056 and a deleted one are
    indistinguishable: the mirror of a blind fixture — real data, right gate, still green.

    [[gate-blind-to-unexercised-input]] [[unknown-stays-unknown]]"""

    def _rr(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import reel_retention
        return reel_retention

    def _tree(self, reels, chron, vault, durable=()):
        """A FIXTURE hist dir. His reels, ledgers and seal store are never read here.
        [[feedback-fixtures-never-touch-live-data]]"""
        import json as _j, tempfile, shutil
        import unittest.mock as mock
        rr = self._rr()
        root = tempfile.mkdtemp(prefix="cov_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        for name in reels:
            d = os.path.join(hist, name)
            os.makedirs(d)
            with open(os.path.join(d, "f_1.jpg"), "wb") as fh:
                fh.write(b"x" * 2048)
        for fn, blob in (("chronicle_swept.json", chron), ("vault_swept.json", vault)):
            with open(os.path.join(root, fn), "w", encoding="utf-8") as fh:
                _j.dump(blob, fh)
        ctx = [mock.patch.object(rr, "CHRON_PATH", os.path.join(root, "chronicle_swept.json"), create=True),
               mock.patch.object(rr, "VAULT_PATH", os.path.join(root, "vault_swept.json"), create=True),
               mock.patch.object(rr, "_durable_sessions", lambda *_a, **_k: set(durable))]
        return rr, hist, root, ctx

    def test_the_plan_reports_which_rules_it_never_reached(self):
        import unittest.mock as mock
        rr = self._rr()
        root, hist = _fixture_hist(self)
        with mock.patch.object(rr, "HERE", root):
            p = rr.plan(hist)
        self.assertIn("coverage", p, "the plan does not report its own branch coverage")
        self.assertIn("neverFired", p)
        self.assertIn("coverageSay", p)
        self.assertEqual(sum(p["coverage"].values()), len(p["candidates"]) + len(p["kept"]),
                         "the coverage counts do not add up to the reels actually classified — "
                         "some reel took a branch nothing counted")

    def test_NOT_REACHED_and_NOT_APPLICABLE_are_kept_apart(self):
        """`target-met` cannot fire without a free_mb target: it is unreachable BY CONSTRUCTION, not
        unexercised by the footage. Reporting them together would make a structurally inert branch
        look like a rule that quietly stopped working."""
        import unittest.mock as mock
        rr = self._rr()
        root, hist = _fixture_hist(self)
        with mock.patch.object(rr, "HERE", root):
            no_target = rr.plan(hist)
        self.assertIn("target-met", no_target["notApplicable"],
                      "target-met was called a gap when no target was even asked for")
        self.assertNotIn("target-met", no_target["neverFired"])
        self.assertIn("cannot fire without a free_mb target", no_target["coverageSay"])

    def test_it_says_UNMEASURED_rather_than_fine_or_broken(self):
        import unittest.mock as mock
        rr = self._rr()
        root, hist = _fixture_hist(self)
        with mock.patch.object(rr, "HERE", root):
            p = rr.plan(hist)
        say = p["coverageSay"]
        # REG-1893 - this fixture leaves rules unreached; if neverFired came back empty the `if` below
        # would skip every claim and the law would pass having said nothing about UNMEASURED.
        self.assertTrue(p["neverFired"], "no rule reads never-fired on the fixture, so this law would "
                                         "check nothing: %r" % (p.get("coverage"),))
        if p["neverFired"]:
            self.assertIn("UNMEASURED", say)
            self.assertNotIn("broken", say.replace("not broken", ""))
            for r in p["neverFired"]:
                self.assertIn(r, say, "a rule was counted as never-reached and not NAMED")

    def test_the_v2056_rule_is_currently_one_of_them_on_his_tree(self):
        """The finding itself, pinned. If this ever starts failing it means his footage finally
        reaches that branch — which is good news, and the test should then be updated to say so
        rather than deleted.

        v2073 — this one is genuinely ABOUT his tree, so it SKIPS where his tree is absent rather
        than erroring. That is not the same as the four above it, which asked about the MECHANISM
        and had no business reading his footage at all."""
        rr = self._rr()
        if not os.path.isdir(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                          "frames", "hist")):
            self.skipTest("his footage is not on this machine")
        p = rr.plan()
        self.assertEqual(p["coverage"].get("rows-not-banked"), 0,
                         "rows-not-banked now fires on his footage — the v2056 rule is finally "
                         "exercised. Update this test; do not delete it.")
        self.assertIn("rows-not-banked", p["neverFired"])

    def test_every_declared_rule_has_a_counter(self):
        """A branch that forgets to call _rule() is invisible to the coverage report, which is the
        same defect one level up."""
        import ast
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reel_retention.py")
        with open(_p, "r", encoding="utf-8") as fh:
            src = fh.read()
        fn = [n for n in ast.walk(ast.parse(src))
              if isinstance(n, ast.FunctionDef) and n.name == "plan"][0]
        tagged = set()
        for n in ast.walk(fn):
            if (isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == "_rule"
                    and n.args and isinstance(n.args[0], ast.Constant)):
                tagged.add(n.args[0].value)
        import unittest.mock as mock
        rr = self._rr()
        root, hist = _fixture_hist(self)
        with mock.patch.object(rr, "HERE", root):
            declared = set(rr.plan(hist)["coverage"].keys())
        self.assertEqual(declared - tagged, set(),
                         "declared but never counted: %s" % sorted(declared - tagged))
        self.assertEqual(tagged - declared, set(),
                         "counted under a tag nothing declares: %s" % sorted(tagged - declared))


class TestV2069TheRecordOutLIVESTheFrames(unittest.TestCase):
    """apply_plan used to rmtree and return a count, so a deleted reel left NOTHING behind — not its
    id, not how much was read from it, not why it was judged spent. "I never recorded that" and
    "that was pruned in August" became the same answer.

    And 3,420 frames — 3.41 GB, a third of his footage — sat DIRECTLY in hist/, belonging to no
    reel and therefore to no authority: reel_retention iterates reel_* dirs, frame_authority globbed
    hist/reel_*, space_warden has tv/frames on its NEVER list. Not protected. Unseen, which reads as
    protected and is worse.

    All fixtures. His reels are never read or written here.
    [[feedback-fixtures-never-touch-live-data]]"""

    def _rr(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import reel_retention
        return reel_retention

    def _fa(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import frame_authority
        return frame_authority

    def _hist(self, reels=(), loose=()):
        import tempfile, shutil, json as _j
        root = tempfile.mkdtemp(prefix="v2069_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        for name, nframes, focus in reels:
            d = os.path.join(hist, name)
            os.makedirs(d)
            for k in range(nframes):
                with open(os.path.join(d, "f_%d.jpg" % (1000 + k)), "wb") as fh:
                    fh.write(b"x" * 512)
            if focus:
                with open(os.path.join(d, "index.json"), "w", encoding="utf-8") as fh:
                    _j.dump({"focus": focus}, fh)
        for name in loose:
            with open(os.path.join(hist, name), "wb") as fh:
                fh.write(b"y" * 1024)
        # v2122 (#32) — a durable witness store, because his tree has one. reel_retention now holds
        # EVERY reel while `haveIndex` is False, matching frame_authority, which has always refused
        # to delete a single FRAME in that state. Without this the fixture asks the reel deleter to
        # release footage the frame deleter would not touch — and these cases are about the
        # test-fixture hold, not about that one.
        with open(os.path.join(root, "vault_accum.json"), "w", encoding="utf-8") as fh:
            _j.dump({}, fh)
        return root, hist

    def test_the_tombstone_is_written_BEFORE_anything_is_deleted(self):
        """A crash halfway must leave a record of MORE than was removed, never less."""
        import unittest.mock as mock
        rr = self._rr()
        root, hist = self._hist(reels=[("reel_s_111_1", 3, "stash")])
        seen = {}

        def boom(path):
            seen["tomb_exists_at_delete_time"] = os.path.exists(rr._tombstone_path())
            raise OSError("refusing, on purpose")

        # v2080 — patch the RESOLVER, not the constant. `_tombstone_path()` is computed per call
        # so a fixture cannot write his real file; a constant bound at import could not do that, and
        # 89 fixture tombstones in his tree proved it. A test that patches the constant is now
        # patching something the writer never reads. [[feedback-fixtures-never-touch-live-data]]
        _tp = os.path.join(root, "tomb.json")
        with mock.patch.object(rr, "_tombstone_path", lambda *a: _tp), \
             mock.patch.object(rr.shutil, "rmtree", boom):
            r = rr.apply_plan({"hist": hist, "freeMb": 1,
                               "candidates": [{"reel": "reel_s_111_1", "mb": 1.0, "pages": 4,
                                               "why": "fixture"}]}, yes=True)
        self.assertTrue(seen.get("tomb_exists_at_delete_time"),
                        "the delete ran before the record was on disk — a crash there loses the "
                        "reel AND its record")
        self.assertEqual(r["tombstoned"], 1)
        self.assertFalse(r["ok"], "a failed delete was reported as success")

    def test_the_tombstone_records_what_the_reel_WAS(self):
        import unittest.mock as mock, json as _j
        rr = self._rr()
        root, hist = self._hist(reels=[("reel_s_222_2", 4, "chronicle-sets")])
        tp = os.path.join(root, "tomb.json")
        with mock.patch.object(rr, "_tombstone_path", lambda *a: tp):
            rr.apply_plan({"hist": hist, "freeMb": 1,
                           "candidates": [{"reel": "reel_s_222_2", "mb": 9.5, "pages": 31,
                                           "why": "read and sealed by BOTH lanes"}]}, yes=True)
        rec = _j.load(open(tp, encoding="utf-8"))["reels"][0]
        self.assertEqual(rec["reel"], "reel_s_222_2")
        self.assertEqual(rec["session"], "s_222_2")
        self.assertEqual(rec["frames"], 4, "the frame count was not captured before deletion")
        self.assertEqual(rec["pages"], 31)
        self.assertEqual(rec["focus"], "chronicle-sets")
        self.assertIn("sealed by BOTH lanes", rec["why"])
        self.assertTrue(rec["deletedTs"])
        self.assertFalse(os.path.isdir(os.path.join(hist, "reel_s_222_2")), "the reel survived")

    def test_a_second_prune_APPENDS_rather_than_replacing(self):
        """A tombstone file that only remembers the last run is a tombstone that forgets."""
        import unittest.mock as mock, json as _j
        rr = self._rr()
        root, hist = self._hist(reels=[("reel_s_1_1", 1, None), ("reel_s_2_2", 1, None)])
        tp = os.path.join(root, "tomb.json")
        with mock.patch.object(rr, "_tombstone_path", lambda *a: tp):
            rr.apply_plan({"hist": hist, "freeMb": 1,
                           "candidates": [{"reel": "reel_s_1_1", "mb": 1, "pages": 1, "why": "a"}]},
                          yes=True)
            rr.apply_plan({"hist": hist, "freeMb": 1,
                           "candidates": [{"reel": "reel_s_2_2", "mb": 1, "pages": 1, "why": "b"}]},
                          yes=True)
        rows = _j.load(open(tp, encoding="utf-8"))["reels"]
        self.assertEqual([r["reel"] for r in rows], ["reel_s_1_1", "reel_s_2_2"],
                         "the second prune overwrote the first run's record")

    def test_a_reel_the_SUITE_opens_is_never_a_deletion_candidate(self):
        if not os.path.isdir(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                          "frames", "hist")):
            self.skipTest("his footage is not on this machine")
        """Six reels were pruned as "sealed by both lanes" and THREE were named by this very file.
        The suite did not go red — those cases skipTest when the footage is absent — so a real check
        silently became a permanent skip. Of the 17 reels the suite names, EIGHT are already gone.
        [[feedback-blind-fixture-green-gate]]"""
        rr = self._rr()
        fa = self._fa()
        fixtures = fa.test_referenced_reels()
        self.assertTrue(fixtures, "the authority found no test-referenced reels at all — the scan "
                                  "is broken and every fixture is deletable again")
        p = rr.plan()
        cand = {c["reel"] for c in p["candidates"]}
        self.assertEqual(cand & fixtures, set(),
                         "these reels are opened by the test suite and were offered for deletion: "
                         "%s" % sorted(cand & fixtures))

    def test_a_fixture_reel_that_WOULD_be_eligible_is_held(self):
        """⚠ THE FIRST VERSION OF THIS GUARD PROVED NOTHING, and only a sabotage showed it: deleting
        the fixture hold outright left every test green, because after the prune his tree has NO
        eligible reels at all — the fixtures never reach that branch, so holding them changes no
        observable output.

        A guard that can only pass is the thing this whole file keeps finding. So the case is built:
        a reel sealed by BOTH lanes and old enough to be eligible, which is ALSO named by the suite.
        Without the hold it is offered for deletion; with it, it is kept and says why.
        [[feedback-blind-fixture-green-gate]]"""
        import unittest.mock as mock, json as _j, tempfile, shutil
        rr = self._rr()
        fa = self._fa()
        root = tempfile.mkdtemp(prefix="fixhold_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "frames", "hist")
        os.makedirs(hist)
        # oldest first; KEEP_RECENT protects the newest N, so build N+2 and target the oldest.
        # ⚠ v2876 — DERIVED, NOT 7. The comment named the constant and the code hard-coded it,
        # so raising KEEP_RECENT 5 -> 8 swallowed the whole fixture and this law went red on a
        # correct tree. [[feedback-blind-fixture-green-gate]]
        import reel_retention as _rr_keep
        names = ["reel_s_17840000%04d_1" % i for i in range(_rr_keep.KEEP_RECENT + 2)]
        for n in names:
            d = os.path.join(hist, n)
            os.makedirs(d)
            with open(os.path.join(d, "f_1.jpg"), "wb") as fh:
                fh.write(b"x" * 4096)
        target = names[0]
        # sealed by BOTH lanes with real pages -> would otherwise be "eligible"
        with open(os.path.join(root, "chronicle_swept.json"), "w", encoding="utf-8") as fh:
            _j.dump({n: {"pages": 9} for n in names}, fh)
        with open(os.path.join(root, "vault_swept.json"), "w", encoding="utf-8") as fh:
            _j.dump({n: {"ts": 1, "rows": 0, "extracted": ["name", "location", "provenance"]} for n in names}, fh)
        # v2122 (#32) — and a durable witness store, or NOTHING is offered and the baseline
        # assertion below (which exists precisely so this case cannot measure nothing) is the one
        # that goes red. reel_retention now holds every reel while haveIndex is False, matching
        # frame_authority's refusal to delete a single frame in that state.
        with open(os.path.join(root, "vault_accum.json"), "w", encoding="utf-8") as fh:
            _j.dump({}, fh)

        def run(fixtures):
            with mock.patch.object(rr, "HERE", root), \
                 mock.patch.object(fa, "test_referenced_reels", lambda *a, **k: set(fixtures)):
                return rr.plan(hist)

        # BASELINE: with nothing declared a fixture, the target IS offered for deletion
        base = run(set())
        self.assertIn(target, {c["reel"] for c in base["candidates"]},
                      "the fixture-free baseline does not offer the reel, so this case cannot tell "
                      "the hold from its absence — the test would be measuring nothing")
        # AND WITH THE HOLD: it is kept, for the fixture reason
        held = run({target})
        self.assertNotIn(target, {c["reel"] for c in held["candidates"]},
                         "a reel the suite opens by name was offered for deletion")
        why = [k["why"] for k in held["kept"] if k["reel"] == target]
        self.assertTrue(why and "TEST SUITE" in why[0],
                        "it was kept, but for some other reason — the fixture rule did not fire")
        self.assertEqual(held["coverage"]["test-fixture"], 1)

    def test_the_fixture_hold_is_checked_FIRST(self):
        if not os.path.isdir(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                          "frames", "hist")):
            self.skipTest("his footage is not on this machine")
        """Order matters: if `recent` or `eligible` were checked first, a fixture would be reported
        under the wrong reason and the coverage line would say the fixture rule never fired — which
        is exactly the shape v2068 exists to surface."""
        rr = self._rr()
        p = rr.plan()
        self.assertIn("test-fixture", p["coverage"],
                      "the fixture rule is not counted, so nothing can tell whether it ran")
        if p["coverage"]["test-fixture"]:
            held = [k["reel"] for k in p["kept"] if "TEST SUITE" in k["why"]]
            self.assertEqual(len(held), p["coverage"]["test-fixture"],
                             "the counter and the reasons disagree about how many reels were held "
                             "as fixtures")

    def test_only_REAL_reel_ids_count_as_fixtures(self):
        """Tests build throwaway dirs called reel_s_1_1; holding those would be holding nothing, and
        would make the fixture count look healthy while protecting no footage."""
        fa = self._fa()
        got = fa.test_referenced_reels()
        # REG-1893 - the suite names real reels; a scan that found none would pass "only real ids" about none.
        self.assertTrue(got, "the fixture scan found no reel the suite names, so this law would judge none")
        for name in got:
            stamp = name.split("_")[2]
            self.assertGreaterEqual(len(stamp), 10,
                                    "%r was counted as a fixture reel; a throwaway test dir is not "
                                    "footage" % name)

    def test_it_survives_the_authority_being_unavailable(self):
        """reel_retention must still plan if frame_authority cannot be imported — it just holds
        nothing extra. A deleter that CRASHES when a helper is missing is worse than one that is
        merely less careful."""
        import unittest.mock as mock
        rr = self._rr()
        real = __import__("builtins").__import__

        def no_fa(name, *a, **k):
            if name == "frame_authority":
                raise ImportError("gone")
            return real(name, *a, **k)

        root, hist = _fixture_hist(self)
        with mock.patch.object(rr, "HERE", root), mock.patch("builtins.__import__", no_fa):
            p = rr.plan(hist)
        self.assertTrue(p["ok"], "the plan died when frame_authority was unavailable")
        self.assertEqual(p["coverage"]["test-fixture"], 0)

    def test_loose_frames_are_SEEN_and_split_by_what_they_are(self):
        fa = self._fa()
        root, hist = self._hist(reels=[("reel_s_9_9", 1, None)],
                                loose=["f_1787520892804.jpg", "f_1787520892999.jpg",
                                       "197_1787525952517.jpg", ".stash_eye_tab.jpg"])
        lf = fa.loose_frames(hist)
        self.assertTrue(lf["ok"])
        self.assertEqual(len(lf["recording"]), 2,
                         "an ungrouped RECORDING was not recognised — those may hold names no lane "
                         "has read")
        self.assertEqual(len(lf["artifact"]), 2)
        self.assertIn("NONE is offered for deletion", lf["say"])

    def test_loose_frames_are_never_offered_for_deletion(self):
        """A frame nothing has classified is not a frame anything may delete."""
        fa = self._fa()
        root, hist = self._hist(reels=[], loose=["f_1787520892804.jpg", "9_1787525952517.jpg"])
        p = fa.plan_frames(hist, root=root)
        self.assertEqual(p["prunable"], [],
                         "a loose frame was offered up — it belongs to no reel, so nothing has "
                         "sealed it and nothing has read it")
        self.assertEqual(p["scanned"], 0, "plan_frames counted loose frames as reel frames")

    def test_an_empty_hist_says_so_rather_than_warning(self):
        fa = self._fa()
        root, hist = self._hist(reels=[("reel_s_3_3", 1, None)])
        lf = fa.loose_frames(hist)
        self.assertEqual(lf["recording"], [])
        self.assertIn("no loose frames", lf["say"])


class TestV2070TheGrantLampCanActuallyMove(unittest.TestCase):
    """`screenRecordingBefore` has read false on every relaunch since v2027.

    The route did `bool((doctor_payload() or {}).get("screen_recording"))` and doctor_payload() has
    no top-level key of that name — the grant lives in checks[]. Its own comment calls this field the
    way a DROP would be noticed; a lamp that cannot move cannot notice anything, which is the same
    defect as a gate that is always green. MEASURED: the console reported false while its own doctor
    said "granted to this process".

    And bool(None) == bool(False), so MISSING and DENIED read identically. They are different facts.
    [[unknown-stays-unknown]]

    REG-1788 — the two tests that call doctor_payload() are about the grant key. The
    extract row must not walk his shelf while they look.
    """

    def setUp(self):
        self._extract = mock.patch.object(
            ca, "_extract_moving_facts",
            lambda: {"owed": 0, "memory": "absent", "ageKnown": True})
        self._extract.start()
        self.addCleanup(self._extract.stop)

    def _block(self):
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "control_app.py")
        with open(_p, "r", encoding="utf-8") as fh:
            src = fh.read()
        # ⚠ THE END ANCHOR WAS "screenRecordingBefore" AND MY OWN COMMENT TRUNCATED THE WINDOW.
        # The v2070 note above the fix quotes the field name while explaining it, so the slice ended
        # at the prose and stopped six lines short of the code it was written to read — every
        # assertion then failed against a block that did not contain the subject. Anchored on a
        # code-only string that appears exactly once instead. [[source-reading-guard]] §2, §3
        end = '"why": "replacing this process with the version on disk"'
        self.assertEqual(src.count(end), 1,
                         "the end anchor is not unique, so the slice is a guess")
        return _between(self, src, 'if path == "/api/relaunch"', end,
                        what="the relaunch route's grant read")

    def test_it_no_longer_asks_for_a_key_that_does_not_exist(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app as _ca
        top = set((_ca.doctor_payload() or {}).keys())
        self.assertNotIn("screen_recording", top,
                         "doctor_payload now HAS a top-level screen_recording key — this guard was "
                         "written for a world where it does not, so re-derive it rather than "
                         "trusting it")
        blk = self._block()
        # ⚠ AND THE NEGATIVE TRIPPED ON MY OWN COMMENT, which QUOTES the broken line in order to
        # explain it. A negative assertion has to be true of the whole searched text including the
        # prose about it, so the code is separated from the commentary first — line-based, which
        # cannot over-reach the way a block-comment stripper can. [[source-reading-guard]] §4
        code = "\n".join(l for l in blk.splitlines() if not l.lstrip().startswith("#"))
        self.assertIn("screen_recording", blk,
                      "the subject is not in this slice at all — the anchors moved")
        self.assertNotIn('.get("screen_recording")', code,
                         "the route still reads a top-level key that does not exist, so the lamp is "
                         "stuck at false again")
        self.assertIn('"checks"', code, "the route does not read checks[], where the grant lives")

    def test_the_grant_is_read_correctly_on_THIS_machine(self):
        """Not a fixture: the real doctor. If the grant is genuinely absent here this SKIPS rather
        than asserting a value it cannot know."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app as _ca
        found = [c for c in ((_ca.doctor_payload() or {}).get("checks") or [])
                 if isinstance(c, dict) and c.get("id") == "screen_recording"]
        if not found:
            self.skipTest("this machine's doctor publishes no screen_recording check")
        blk = self._block()
        self.assertIn('_c.get("id") == "screen_recording"', blk,
                      "the route does not look for the check by id")
        self.assertIn("bool(_c.get(\"ok\"))", blk,
                      "the route does not read the check's ok field")

    def test_ABSENT_reads_as_None_and_never_as_denied(self):
        """The half that matters when something breaks: an unmeasurable grant must not be published
        as a denial, or the fallback advice fires for a machine that was never asked."""
        blk = self._block()
        self.assertIn("_grant = None", blk,
                      "there is no None path — a missing check would collapse into False, and "
                      "'nobody looked' would read the same as 'denied'")
        # the initial value must be None, i.e. set BEFORE the loop that may or may not find it
        i_none = blk.find("_grant = None")
        i_loop = blk.find("for _c in")
        self.assertGreater(i_loop, i_none,
                           "_grant is not initialised to None before the search, so a payload with "
                           "no checks at all would leave it undefined or false")


class TestV2071OrphanFoldNeverForgesASession(unittest.TestCase):
    """An unsealed session's frames stay loose forever, invisible to every lane and every deleter.
    Folding them into a reel makes them readable — and is the one operation here that could
    manufacture EVIDENCE, so the refusal is the load-bearing half.

    reel_index.ensure_reel_index writes its index via chronicle_retro.reconstruct_index, which sets
    sessionId from the DIRECTORY NAME with `reel_` stripped. PROVEN in test_the_name_decides_the_
    session_id below. So folding leftovers of an ALREADY-SEALED session under a new name mints a new
    session id for one recording, forging the independence the keep and throw bars demand.

    All fixtures. His reels are never read or written here.
    [[feedback-fixtures-never-touch-live-data]]"""

    def _of(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import orphan_fold
        return orphan_fold

    def _tree(self, loose=(), reels=()):
        import tempfile, shutil
        root = tempfile.mkdtemp(prefix="orphan_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        for t in loose:
            with open(os.path.join(hist, "f_%d.jpg" % t), "wb") as fh:
                fh.write(b"x" * 256)
        for name, times in reels:
            d = os.path.join(hist, name)
            os.makedirs(d)
            for t in times:
                with open(os.path.join(d, "f_%d.jpg" % t), "wb") as fh:
                    fh.write(b"y" * 256)
        return hist

    def test_the_name_decides_the_session_id(self):
        """The mechanism the whole refusal rests on, proven rather than cited."""
        import tempfile, shutil
        import chronicle_retro as cr
        root = tempfile.mkdtemp(prefix="sid_")
        self.addCleanup(shutil.rmtree, root, True)
        got = {}
        for name in ("reel_orphan_1500000000000_1", "reel_s_1500000000000_1"):
            d = os.path.join(root, name)
            os.makedirs(d)
            with open(os.path.join(d, "f_1500000000000.jpg"), "wb") as fh:
                fh.write(b"x")
            got[name] = (cr.reconstruct_index(d) or {}).get("sessionId")
        self.assertEqual(got["reel_s_1500000000000_1"], "s_1500000000000_1")
        self.assertEqual(got["reel_orphan_1500000000000_1"], "orphan_1500000000000_1")
        import re as _re
        rec = _re.compile(r"^s_(\d{10,16})(?:_|$)")     # v2065's recording parser
        self.assertTrue(rec.match(got["reel_s_1500000000000_1"]))
        self.assertFalse(rec.match(got["reel_orphan_1500000000000_1"]),
                         "an orphan-named reel would read as UNKNOWN time in the ledger")

    def test_a_cluster_that_OVERLAPS_a_reel_is_refused(self):
        """THE ONE THAT MATTERS. Baseline first, or this case cannot tell a refusal from a plan that
        offers nothing. [[feedback-blind-fixture-green-gate]]"""
        of = self._of()
        base = 1787520000000
        # BASELINE: the same loose frames with NO reel nearby are eligible
        h1 = self._tree(loose=[base + i * 1000 for i in range(5)])
        p1 = of.plan(h1)
        self.assertTrue(p1["clusters"][0]["eligible"],
                        "the no-reel baseline is not foldable, so the overlap case below would pass "
                        "for the wrong reason")
        # AND NOW with a reel covering the same window
        h2 = self._tree(loose=[base + i * 1000 for i in range(5)],
                        reels=[("reel_s_%d_9" % base, [base + 2000])])
        p2 = of.plan(h2)
        c = p2["clusters"][0]
        self.assertFalse(c["eligible"], "a window an existing reel already covers was offered — "
                                        "folding it forges a second session for one recording")
        self.assertIn("reel_s_%d_9" % base, c["overlaps"])
        self.assertIn("forges", c["why"])

    def test_an_overlapping_cluster_is_not_moved_even_with_yes(self):
        """The refusal must live in the ACT, not only in the report."""
        of = self._of()
        base = 1787520000000
        h = self._tree(loose=[base + i * 1000 for i in range(5)],
                       reels=[("reel_s_%d_9" % base, [base + 2000])])
        p = of.plan(h)
        of.apply_plan(p, yes=True)
        left = [n for n in _fx_tmp.list_own(h) if n.startswith("f_")]
        self.assertEqual(len(left), 5, "an overlapping cluster was folded anyway")

    def test_the_folded_reel_is_named_so_its_session_parses(self):
        of = self._of()
        base = 1500000000000
        h = self._tree(loose=[base + i * 1000 for i in range(4)])
        p = of.plan(h)
        self.assertEqual(p["clusters"][0]["reel"], "reel_s_%d_1" % base)
        r = of.apply_plan(p, yes=True)
        self.assertTrue(r["ok"], r)
        d = os.path.join(h, "reel_s_%d_1" % base)
        self.assertTrue(os.path.isdir(d))
        self.assertTrue(os.path.isfile(os.path.join(d, "index.json")),
                        "no index — the lanes still cannot read what was just folded (v1608: the "
                        "index IS the reel)")
        with open(os.path.join(d, "index.json"), encoding="utf-8") as fh:
            self.assertEqual(json.load(fh).get("sessionId"), "s_%d_1" % base)

    def test_probe_artifacts_are_never_moved(self):
        of = self._of()
        base = 1500000000000
        h = self._tree(loose=[base + i * 1000 for i in range(3)])
        with open(os.path.join(h, "197_%d.jpg" % base), "wb") as fh:
            fh.write(b"z" * 64)
        of.apply_plan(of.plan(h), yes=True)
        self.assertTrue(os.path.isfile(os.path.join(h, "197_%d.jpg" % base)),
                        "a probe artifact was folded into a reel as if it were footage")

    def test_it_deletes_nothing(self):
        import ast
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "orphan_fold.py")
        with open(_p, "r", encoding="utf-8") as fh:
            src = fh.read()
        bad = [n.lineno for n in ast.walk(ast.parse(src))
               if isinstance(n, ast.Call)
               and (getattr(n.func, "attr", "") in ("remove", "unlink", "rmtree")
                    or getattr(n.func, "id", "") in ("remove", "unlink", "rmtree"))]
        self.assertEqual(bad, [], "orphan_fold calls a deleter at line(s) %s — it moves, never "
                                  "removes" % bad)

    def test_it_refuses_without_yes(self):
        of = self._of()
        base = 1500000000000
        h = self._tree(loose=[base, base + 1000])
        r = of.apply_plan(of.plan(h), yes=False)
        self.assertFalse(r["ok"])
        self.assertIn("--yes", r["why"])
        self.assertEqual(len([n for n in _fx_tmp.list_own(h) if n.startswith("f_")]), 2)

    def test_a_long_silence_starts_a_new_cluster(self):
        of = self._of()
        base = 1787520000000
        h = self._tree(loose=[base, base + 1000, base + 1000 + of.GAP_MS + 5000])
        p = of.plan(h)
        self.assertEqual(len(p["clusters"]), 2,
                         "a gap longer than GAP_MS did not split the recording")


class TestV2072TheDriftNobodyWasWatching(unittest.TestCase):
    """Both halves existed and nothing joined them. `ver_match` in the farm gate compares the RUNNING
    stamp against control/agent/board and is block-severity; /api/relaunch replaces the process with
    os.execv. But ver_match only runs when he presses 🛡 gate, so the console can sit five ships
    behind all night and never say so — it did: v2064 running against v2069 on disk.

    ⚠ ANNOUNCING IS THE DEFAULT. The third eye refused an earlier version that called execv
    automatically and was right twice: a relaunch mid-film interrupts the session AND orphans the
    frames of the session it kills, because the reel fold runs at seal (v2071). Automating a restart
    without the agent check would manufacture work for the module that cleans up after crashes."""

    def _ca(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app
        return control_app

    # ══ v2324 — THESE TESTS MUST NOT DEPEND ON WHETHER SOMEBODY HAS UNCOMMITTED WORK ══════════
    # v2323 taught drift_may_relaunch() to refuse while the working tree is mid-edit (REG-400).
    # That is correct in production and WRONG as a hidden input here: these cases are about the
    # other interlocks — a film rolling, a sweep reading, a drifted world — and they would other-
    # wise pass on a clean checkout and fail on the machine of anyone actually editing the repo.
    # CI checks out clean, so it would have gone green while his Mac went red, which is the same
    # green-that-lies in the other direction. The mid-edit rule has its own dedicated class.
    # [[feedback-blind-fixture-green-gate]]
    def setUp(self):
        self._mid_edit = self._ca()._tree_is_mid_edit
        self._ca()._tree_is_mid_edit = lambda *a, **k: (False, "")
        # ⚠ v3183 — AND THE SWEEP LOCK, for the same reason the line above exists: it is REAL
        # STATE ON HIS DISK. v3180 taught drift_may_relaunch to refuse while `.sweep.lock` is
        # warm, which is correct and which made every test in this class hostage to whether a
        # sweep happened to be running while the suite ran. It caught 8 of them 113 seconds
        # after a real 100-minute vault read finished. A fixture that reads live data measures
        # the machine, not the code. [[feedback-fixtures-never-touch-live-data]]
        #
        # Pointed at a path that cannot exist, so getmtime raises and the guard takes its
        # "no sweep has ever declared itself" branch. The tests that WANT the lock to bite
        # (test_it_refuses_while_a_sweep_is_reading) drive the in-memory job instead, which is
        # the same refusal by the more specific door.
        self._lock_path = self._ca()._sweep_lock_path
        self._ca()._sweep_lock_path = lambda *a, **k: os.path.join(
            tempfile.gettempdir(), "no_such_sweep_lock_%d" % os.getpid())

    def tearDown(self):
        self._ca()._tree_is_mid_edit = self._mid_edit
        self._ca()._sweep_lock_path = self._lock_path


    def test_auto_relaunch_is_ON_because_he_asked_for_it_but_OFF_is_still_HIS(self):
        """⚠ THE RULING CHANGED, AND IT IS HIS RULING BOTH TIMES.

        v2072 pinned "OFF unless he asks", and v2146 disarmed it again deliberately one version
        after arming it. That was correct then. He has since said, in as many words:

            "its still not auto relaunching for the newer updates. we said it should relaunch by
             itself based on updates we do. automatically"

        So the default flips, and this test flips with it rather than being deleted — the law it
        guards is not "off", it is "the console does what he last told it to". What must NOT
        change, and is asserted below, is that a default only ever fills an UNANSWERED question:
        a saved OFF and TV_AUTO_RELAUNCH=0 both still win. [[unknown-stays-unknown]]

        The v2180 defect this sits on top of: the arming was read from an env var exported by
        exactly one launcher, so on his own console — which that launcher did not start — the
        answer was neither ON nor OFF but ABSENT, and had been for the life of the feature."""
        import unittest.mock as mock
        ca = self._ca()
        with mock.patch.dict(os.environ, {}, clear=False):
            os.environ.pop("TV_AUTO_RELAUNCH", None)
            with mock.patch.object(ca, "board_identity_drift",
                                   lambda: {"state": "ok", "why": "world pinned by the test"}), \
                 mock.patch.object(ca, "auto_relaunch_setting", lambda: None):
                ok, why = ca.drift_may_relaunch()
        self.assertNotIn("opt-in", (why or ""),
                         "auto-relaunch is still refusing as opt-in with nothing chosen, which is "
                         "every console the supervisor did not start")
        # ⚠ v2284 — THE LAW CHANGED, AND THIS IS THE HALF THAT CHANGED. Konyo, about Dean's
        # console sitting on an old build: "this isnt optional the updates need to be going up.
        # not a on or off button at all". A stored answer no longer participates: there is no
        # switch to be off. Raising the default would have done nothing, because a default cannot
        # beat a stored value — which is exactly why the stored value had to stop being consulted.
        with mock.patch.dict(os.environ, {}, clear=False):
            os.environ.pop("TV_AUTO_RELAUNCH", None)
            with mock.patch.object(ca, "board_identity_drift",
                                   lambda: {"state": "ok", "why": "world pinned by the test"}), \
                 mock.patch.object(ca, "auto_relaunch_setting", lambda: False):
                ok2, why2 = ca.drift_may_relaunch()
        self.assertTrue(ok2, "a stored 'off' is stopping an update again — updates are not "
                             "optional and there is no longer a button for this")
        # ⚠ AND THE MACHINE OVERRIDE MUST SURVIVE. Ten specs use TV_AUTO_RELAUNCH to stop a TEST
        # console restarting itself mid-suite; a harness that can execv during its own run is a
        # hazard, not a feature. It is not a user toggle and is not reachable from the UI.
        with mock.patch.dict(os.environ, {"TV_AUTO_RELAUNCH": "0"}):
            ok3, why3 = ca.drift_may_relaunch()
        self.assertFalse(ok3, "TV_AUTO_RELAUNCH=0 no longer stops a relaunch — the test harness "
                              "can now restart itself in the middle of a run")
        self.assertIn("switched off", (why3 or "").lower())

    def test_it_refuses_while_he_is_ACTUALLY_FILMING(self):
        """The check the relaunch route does NOT make, and the one that means he is filming.

        ⚠ v2155 CORRECTS THE PROXY, NOT THE PROTECTION. This asserted that a live AGENT PROCESS
        blocks a relaunch. The protection is right — killing a session mid-film orphans its
        frames, because the reel fold runs at seal (v2071) — but `_agent_alive()` is true whenever
        the process merely exists, and v1823 had already recorded what that costs: "He plays with
        the console capturing, so a session was live almost whenever he was at the machine ... 'A
        session exists' is a proxy; 'this directory is still growing' is the fact."

        Measured on his live console right after v2153 armed auto-relaunch: mode 'off',
        engineAlive True, ZERO frames written in three minutes, drift True with v2154 on disk —
        and it refused every 300s because a process existed. This test was pinning that.

        Both halves of the real fact still refuse, and both are asserted here."""
        import unittest.mock as mock
        ca = self._ca()
        # (a) ON AIR
        for mode in ("live", "sim"):
            with mock.patch.dict(os.environ, {"TV_AUTO_RELAUNCH": "1"}), \
             mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "world pinned by the test"}), \
                 mock.patch.object(ca, "_agent_mode", mode), \
                 mock.patch.object(ca, "_agent_alive", lambda: True), \
                 mock.patch.object(ca, "mini_state", lambda: {"running": False}):
                ok, why = ca.drift_may_relaunch()
            self.assertFalse(ok, "it would have restarted the console while ON AIR (%s) — and "
                                 "orphaned the frames of the session it killed" % mode)
            self.assertIn("ON AIR", why)
        # (b) off air by the mode, but frames are still landing.
        # A REAL directory: the code checks isdir first, so without one the mock below is never
        # reached — green here, red on a CI runner that has no hist dir. [[test-venue]]
        import tempfile as _tf
        _hist = _tf.mkdtemp()
        with mock.patch.dict(os.environ, {"TV_AUTO_RELAUNCH": "1"}), \
             mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "world pinned by the test"}), \
             mock.patch.object(ca, "_agent_mode", "off"), \
             mock.patch.object(ca, "_agent_alive", lambda: True), \
             mock.patch.object(ca, "HIST_DIR", _hist), \
             mock.patch.object(ca, "_reel_is_growing", lambda *a, **k: True), \
             mock.patch.object(ca, "mini_state", lambda: {"running": False}):
            ok, why = ca.drift_may_relaunch()
        self.assertFalse(ok, "frames are still landing and it would have restarted anyway")
        self.assertIn("mid-film", why)

    def test_an_IDLE_agent_does_not_block_forever(self):
        """The other side of the same correction, and the reason the feature did nothing. If this
        cannot pass, auto-relaunch is armed onto a permanently-true refusal and he will ask a
        third time. [[feedback-blind-fixture-green-gate]]"""
        import unittest.mock as mock
        ca = self._ca()
        with mock.patch.dict(os.environ, {"TV_AUTO_RELAUNCH": "1"}), \
             mock.patch.object(ca, "_agent_mode", "off"), \
             mock.patch.object(ca, "_agent_alive", lambda: True), \
             mock.patch.object(ca, "_reel_is_growing", lambda *a, **k: False), \
             mock.patch.object(ca, "_CHRON_JOB", {"running": False}), \
             mock.patch.object(ca, "_VAULT_JOB", {"running": False}), \
             mock.patch.object(ca, "board_identity_drift", lambda: {"state": "ok", "why": ""}), \
             mock.patch.object(ca, "mini_state", lambda: {"running": False}):
            ok, why = ca.drift_may_relaunch()
        self.assertTrue(ok, "an agent that merely EXISTS still blocks the relaunch: %s" % why)

    def test_it_refuses_while_a_sweep_is_reading(self):
        import unittest.mock as mock
        ca = self._ca()
        for job, label in (("_CHRON_JOB", "chronicle"), ("_VAULT_JOB", "vault")):
            with mock.patch.dict(os.environ, {"TV_AUTO_RELAUNCH": "1"}), \
             mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "world pinned by the test"}), \
                 mock.patch.object(ca, job, {"running": True}), \
                 mock.patch.object(ca, "_agent_alive", lambda: False), \
                 mock.patch.object(ca, "mini_state", lambda: {"running": False}):
                ok, why = ca.drift_may_relaunch()
            self.assertFalse(ok, "%s sweep in flight and it would still relaunch" % label)
            self.assertIn(label, why)

    def test_an_unmeasurable_state_is_never_a_green_light(self):
        import unittest.mock as mock
        ca = self._ca()

        def boom():
            raise RuntimeError("cannot tell")

        with mock.patch.dict(os.environ, {"TV_AUTO_RELAUNCH": "1"}), \
             mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "world pinned by the test"}), \
             mock.patch.object(ca, "_agent_alive", boom):
            ok, why = ca.drift_may_relaunch()
        self.assertFalse(ok, "it acted on a state it could not read")
        self.assertIn("could not tell", why)

    def test_it_DOES_allow_it_when_asked_and_idle(self):
        """The mirror. If it refused in every case the tests above would prove nothing."""
        import unittest.mock as mock
        ca = self._ca()
        with mock.patch.dict(os.environ, {"TV_AUTO_RELAUNCH": "1"}), \
             mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "world pinned by the test"}), \
             mock.patch.object(ca, "_CHRON_JOB", {"running": False}), \
             mock.patch.object(ca, "_VAULT_JOB", {"running": False}), \
             mock.patch.object(ca, "_agent_alive", lambda: False), \
             mock.patch.object(ca, "mini_state", lambda: {"running": False}):
            ok, why = ca.drift_may_relaunch()
        self.assertTrue(ok, why)

    def test_an_ambiguous_disk_stamp_is_UNKNOWN_not_a_guess(self):
        """_disk_ver returns None unless the literal appears EXACTLY once. Picking the first of two
        would be a coin toss reported as a measurement. [[unknown-stays-unknown]]"""
        import unittest.mock as mock, tempfile, shutil
        ca = self._ca()
        root = tempfile.mkdtemp(prefix="ver_")
        self.addCleanup(shutil.rmtree, root, True)
        for label, body, want in (
                ("one", '"ver": "v2072"\n', "v2072"),
                ("two", '"ver": "v2072"\n"ver": "v9999"\n', None),
                ("none", "nothing here\n", None)):
            f = os.path.join(root, "%s.py" % label)
            with open(f, "w", encoding="utf-8") as fh:
                fh.write(body)
            with mock.patch.object(ca, "__file__", f):
                self.assertEqual(ca._disk_ver(), want, "the %s-literal case is wrong" % label)

    def test_the_drift_is_PUBLISHED_or_nothing_can_show_it(self):
        ca = self._ca()
        st = ca.status_payload() or {}
        self.assertIn("drift", st, "the status payload does not carry drift, so no surface can "
                                   "ever show him that his window is behind")
        d = st["drift"]
        for k in ("checked", "running", "disk", "drift", "say"):
            self.assertIn(k, d)
        # v2120 (#24) — see the eagle twin: PUBLISHED is not SHOWN.
        # v2121 (#133) — AND STRIP THE PROSE, or this is the same defect it replaced. The live
        # reader is ONE line (`var _d = st.drift || {}, _e = st.eagle || {};`); comment that line
        # out and a raw grep still finds the string inside the comment. The sibling assertion in
        # this same commit already strips for exactly this reason.
        # [[feedback-comments-vs-code]] [[source-reading-guard]]
        with io.open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as _fh:
            _ui = _fh.read()
        _ui_code = re.sub(r"/\*.{0,4000}?\*/", " ", _ui, flags=re.S)
        _ui_code = re.sub(r"(?m)^\s*//.*$", "", _ui_code)
        self.assertGreater(len(_ui_code), len(_ui) * 0.5, "the comment strip ate the console")
        self.assertIn("st.drift", _ui_code, "nothing on the console reads the version drift")

    def test_before_it_has_run_it_says_so_rather_than_in_sync(self):
        """A drift field defaulting to False would read as 'in sync' from the first second, which is
        a claim nobody measured."""
        ca = self._ca()
        import inspect
        src = inspect.getsource(ca)
        i = src.index('_DRIFT = {')
        blk = src[i:src.index("\n\n", i)]
        self.assertIn('"drift": None', blk, "drift defaults to something other than None")
        self.assertIn("not measured yet", blk)

    def test_the_loop_is_actually_started(self):
        """A watcher nobody starts is the defect it was written to fix. [[the-unjoined-end]]"""
        self.assertTrue(_watcher_is_armed("tvd-version-drift", "_drift_loop"),
                        "_drift_loop is never spawned, so the console still says nothing")




#: REG-1990 - the fixed workload the cheap-subset gate reads a core's speed with, and its CPU cost on a FAST core of his
#: M4 (MEASURED 2026-10-07, 12 runs: min 102, median 106, max 118 ms). REF_CAP bounds how far a slow machine can widen
#: the budget: past 3x the reading says more about the machine than the subset, and the gate still judges it.
REF_FAST_MS = 105.0
REF_CAP = 3.0


def _cheap_budget(refs, base_ms):
    """REG-1990 - the cheap-subset budget for a pass read beside these reference timings. -> (budget ms, scale)

    The scale is how much slower the reference ran than on a fast core: never below 1 (a faster machine is judged at
    the full budget, never a tighter one), never above REF_CAP. No reading is the fast-core budget, never a guess."""
    good = [float(r) for r in (refs or []) if isinstance(r, (int, float)) and r > 0]
    if not good:
        return float(base_ms), 1.0
    scale = max(1.0, min(REF_CAP, (sum(good) / len(good)) / REF_FAST_MS))
    return float(base_ms) * scale, scale


def _ref_cpu_ms():
    """REG-1990 - one fixed pure-python workload's CPU time on whatever core runs it now. -> ms"""
    import time as _tt
    c = _tt.process_time()
    s = 0
    for i in range(2000000):
        s += i * i % 7
    return (_tt.process_time() - c) * 1000.0


class TestREG1990TheCheapBudgetReadsTheCore(unittest.TestCase):
    """REG-1990 - the cheap-subset budget grows by how much slower a reference workload ran here, and only that."""

    def test_a_fast_core_gets_the_plain_budget_and_a_faster_one_never_a_tighter_one(self):
        self.assertEqual(_cheap_budget([REF_FAST_MS, REF_FAST_MS], 9000), (9000.0, 1.0))
        self.assertEqual(_cheap_budget([REF_FAST_MS / 2], 9000), (9000.0, 1.0),
                         "a machine faster than his M4 was judged on a TIGHTER budget")

    def test_a_slow_core_widens_it_by_exactly_the_ratio(self):
        b, sc = _cheap_budget([REF_FAST_MS * 1.5, REF_FAST_MS * 2.5], 9000)
        self.assertAlmostEqual(sc, 2.0)
        self.assertAlmostEqual(b, 18000.0)

    def test_the_widening_is_capped_and_no_reading_is_no_widening(self):
        self.assertEqual(_cheap_budget([REF_FAST_MS * 10], 9000), (9000.0 * REF_CAP, REF_CAP),
                         "an overloaded machine widened the budget without limit")
        self.assertEqual(_cheap_budget([], 9000), (9000.0, 1.0), "no reference reading was read as a slow core")
        self.assertEqual(_cheap_budget([None, -3, "x"], 9000), (9000.0, 1.0))

    def test_the_reference_workload_measures_something(self):
        self.assertGreater(_ref_cpu_ms(), 1.0, "the reference workload costs nothing, so it scales nothing")


class TestV2078TheWatchdogLooksByItself(unittest.TestCase):
    """Konyo: "put it all under eagle eye and watchdog so if something within the console is out of
    sync it can catch it."

    The eagle eye only ever ran when he PRESSED it. Every defect it exists to see is one where NO
    COMPONENT IS WRONG and two correct things disagree — a process serving the code it booted with
    while the page reads stamps from disk; a lane locked on the board and open in the engine; frames
    belonging to no reel; sprites the board draws quietly gone. Those states persist for exactly as
    long as nobody looks."""

    def _ca(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app
        return control_app

    def _cd(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import console_doctor
        return console_doctor

    def test_the_watchdog_is_actually_started(self):
        """A watcher nobody spawns is the defect it was written to fix. [[the-unjoined-end]]"""
        self.assertTrue(_watcher_is_armed("tvd-eagle-watch", "_eagle_watch_loop"),
                        "_eagle_watch_loop is never spawned, so the eagle still only runs when he "
                        "presses the button")

    def test_it_is_published_or_no_surface_can_show_it(self):
        st = self._ca().status_payload() or {}
        self.assertIn("eagle", st, "the status payload does not carry the watchdog's last look")
        for k in ("checked", "needsYou", "unknown", "rows", "say"):
            self.assertIn(k, st["eagle"])
        # v2120 (#24) — AND A SURFACE MUST ACTUALLY READ IT. A key on /api/status is the same shape
        # as a route with no consumer: the footer block that paints this could be deleted and this
        # test stayed green. Its own retention sibling already asserts its reader.
        # [[the-unjoined-end]] [[plumbing-with-no-tap]]
        # v2121 (#133) — AND STRIP THE PROSE, or this is the same defect it replaced. The live
        # reader is ONE line (`var _d = st.drift || {}, _e = st.eagle || {};`); comment that line
        # out and a raw grep still finds the string inside the comment. The sibling assertion in
        # this same commit already strips for exactly this reason.
        # [[feedback-comments-vs-code]] [[source-reading-guard]]
        with io.open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as _fh:
            _ui = _fh.read()
        _ui_code = re.sub(r"/\*.{0,4000}?\*/", " ", _ui, flags=re.S)
        _ui_code = re.sub(r"(?m)^\s*//.*$", "", _ui_code)
        self.assertGreater(len(_ui_code), len(_ui) * 0.5, "the comment strip ate the console")
        self.assertIn("st.eagle", _ui_code, "nothing on the console reads the eagle")

    def test_before_it_has_run_it_says_so_rather_than_all_clear(self):
        """A watchdog defaulting to 'all clear' reads as reassurance nobody measured."""
        import inspect
        src = inspect.getsource(self._ca())
        i = src.index("_EAGLE = {")
        blk = src[i:src.index("\n\n", i)]
        self.assertIn('"needsYou": None', blk, "needsYou defaults to a number nobody counted")
        self.assertIn("not measured yet", blk)

    def test_UNKNOWN_is_never_folded_into_all_clear(self):
        """The design rule: a watchdog that says 'fine' because it could not look is the defect it
        exists to catch. [[unknown-stays-unknown]]"""
        import unittest.mock as mock
        ca = self._ca()
        rows = [{"check": "a", "state": "ok", "why": ""},
                {"check": "b", "state": "unknown", "why": "console not answering"}]
        # ⚠⚠ v3319 — THE MOCK DID NOT REACH THE WHOLE POPULATION, AND IT COST TEN DEPLOYS.
        # This patched `run` only. But `_eagle_once` counts over `_drawn = rows + slowRows`, and
        # slowRows comes from `slow_surface()` — a CACHED read of _load_slow, not a sub-doctor
        # run, so no patch of `run` can touch it. `slow_surface` ALWAYS returns len(SLOW) rows and
        # emits UNMEASURED when no full pass was ever stored ("NEVER, not missing"), and the
        # counter buckets 'unknown' OR 'unmeasured' since v3293.
        #
        # MEASURED 2026-09-18: on HIS Mac the stored pass exists so `the other doctors` reads ok
        # and the count is 1; on a GitHub runner nothing was ever stored, so it is UNMEASURED and
        # the count is 2. The Publish workflow failed on TEN CONSECUTIVE RUNS with `2 != 1` — the
        # live site did not deploy all day — and the code was right every time.
        # Same command locally: 2283 tests OK with 14 skips; CI: 27 skips and this one failure.
        # THE VENUE WAS THE VARIABLE. [[regression-guard]] §3 — a test that needs his machine is a
        # test that runs nowhere else.
        with mock.patch.dict(sys.modules):
            import console_doctor as cd
            with mock.patch.object(cd, "run", lambda **k: rows), \
                 mock.patch.object(cd, "slow_surface", lambda *a, **k: []):
                ca._eagle_once()
        st = ca.eagle_state()
        # THE LAW, not the count. The rule this test is named for is that an UNMEASURED check is
        # never folded into all-clear — not that exactly one thing is unknown on every machine.
        self.assertGreaterEqual(
            st["unknown"], 1,
            "the unknown row was not counted AT ALL — that is the fold this test exists to catch")
        self.assertIn(
            "b", [r.get("check") for r in (st.get("rows") or [])],
            "the unknown row was dropped from the drawn population, so the count above could be "
            "reached by something else entirely")
        self.assertNotIn("all clear", st["say"],
                         "a check that could not be measured was reported as all clear")
        # ...and with the slow surface neutralised the figure is DETERMINISTIC, so the venue can
        # no longer move it. Asserting only >= 1 would pass on a board drowning in unknowns.
        self.assertEqual(
            st["unknown"], 1,
            "with slow_surface stubbed empty the only unknown is the mocked one; a different "
            "number means something outside this fixture is still contributing rows")

    def test_the_five_new_checks_are_on_the_roster(self):
        """Each one exists because a defect of that exact shape shipped and HE found it."""
        names = [n for n, _ in self._cd().CHECKS]
        for want in ("visual lock", "art corpus", "footage has a reel",
                     "vault stores", "locked lanes"):
            self.assertIn(want, names, "the eagle no longer watches %r" % want)

    def test_the_cheap_subset_is_actually_CHEAP(self):
        """v2080 — PIN THE LAW, NOT THE MEMBERSHIP.

        The first cut asserted `set(SLOW) == {"the other doctors"}`. That is a claim about a list,
        and the list was wrong: `sweep would find` sat in the CHEAP subset costing 16,585 ms of a
        17,069 ms tick — 97% of it — and the guard was perfectly green about it. It cost a gate,
        because the eagle runs that subset at every console boot.

        So this measures. A subset called cheap that takes 17 seconds is not a naming problem."""
        import time as _t
        cd = self._cd()
        # ⚠⚠ REG-1463 (2026-09-29) — MEASURE THE PATH THE CONSOLE TAKES, the v2815 lesson one layer down.
        # v3523 (#66, REG-1412) gave reel_retention.plan() a memo that exists ONLY on the console path
        # (frame_ref.mark_console_path(), set by control_app.main()) - off in every law, correctly, because a
        # law may monkeypatch what plan() reads. So this gate timed the UNMEMOIZED plan: each river check
        # re-walked the shelf, ~320 ms a plan and ~650 ms a route, and v3523's 16-reel FIFO doubled the shelf.
        # MEASURED on his Mac, load ~4: 8,869 / 9,093 ms against the 9,000 budget - v3523 push #5 REFUSED at
        # 129 min - while plan() itself costs the same in v3522 (296 ms) and v3523 (318 ms) on the same shelf.
        # The console pays the memoized cost; this gate now measures that, for its own duration only.
        import frame_ref as _frc
        _was_console = _frc.on_console_path()
        _frc.mark_console_path(True)
        self.addCleanup(_frc.mark_console_path, _was_console)
        BUDGET_MS = 3000        # generous: the whole cheap tick, on a cold fixture tree
        slow = []
        total = 0.0
        # ⚠ v2086 — THIS COULD ONLY GO RED ON HIS MACHINE, which is the mirror of a blind fixture.
        # On a clean CI checkout every console- and footage-dependent check returns instantly:
        # there is no console to time out against, no art dir, no frames. So the budget it enforces
        # is unreachable there, and the 16,585 ms check it caught was only ever catchable HERE.
        # A guard that can fire on one machine and never on another is a guard that has an opinion
        # about which machine you are on. So it now names WHICH checks actually did work, and
        # refuses to call the run a pass when none of them did. [[feedback-blind-fixture-green-gate]]
        # ⚠ v2354 — A WALL-CLOCK BUDGET CANNOT BE MEASURED ON A SATURATED MACHINE. This went red
        # on 2026-08-31 with "panels on screen (4020 ms)" while he was PLAYING: load average 33,
        # D2R at 260% CPU, a chronicle sweep running. The check makes one HTTP call to his
        # console; at that load, 4s is the machine, not the code. It passed at v2349 on the same
        # code with the machine idle.
        #
        # A timing gate that goes red every time he plays is a gate he learns to ignore, which is
        # the same defect as a gate that is always green. So it now REFUSES TO JUDGE rather than
        # judging wrongly - and says so loudly, because a skip is not a pass. [[test-venue]]
        # [[regression-guard]]
        # ⚠⚠ v2801 — THE SKIP THRESHOLD SAT ABOVE THE CEILING, SO IT WAS AN ABSENT ONE.
        # v2354 added this guard so the gate would refuse to judge on a saturated machine. It
        # fires above `cpus * 1.5`, which on his 10-core Mac is **15.0** — and the load average
        # measured during EVERY red run of 2026-09-08 was 12.82, 12.51, 10.18, 9.22, 4.45, 3.27.
        # It has never once fired when it was needed, while /api/status was taking 52 seconds.
        # The guard was real, correct in intent, and unreachable in practice.
        # [[feedback-threshold-above-the-ceiling]]
        #
        # ⚠ LOAD AVERAGE IS ALSO THE WRONG INSTRUMENT: it is a one-minute average, so it lags
        # precisely the burst that distorts a 13-second measurement. The tell was that the NAMED
        # CULPRITS changed between runs on identical code — 'stage shows the dom (7301 ms)' and
        # 'engines corroborate' one run, 'armed migration (3645 ms)' and 'panels on screen
        # (3384 ms)' the next, then 141 ms each on a quiet machine minutes later. A property that
        # moves between runs of the same code is not a property of the code.
        # [[feedback-suspect-the-instrument]]
        #
        # CALIBRATE INSTEAD. Run a fixed amount of arithmetic and see what the machine makes of
        # it. Measured on his Mac near-idle: 77 ms, five runs inside 6 ms of each other, so a 3x
        # reading is unambiguous rather than a judgement call.
        # ⚠⚠ v2802 — THE CALIBRATION PROBE IS GONE, AND REMOVING IT IS THE FIX.
        # It replaced a load-average threshold that never fired (cpus*1.5 = 15.0 against measured
        # loads of 12.82 and below). That diagnosis was right. What shipped was a 2,000,000-add
        # loop whose result was then referenced ONLY inside two failure-message strings — no
        # branch, no threshold, no skip depended on it. A cross-family review of the pushed diff
        # put it plainly: the commit replaced a threshold that never fired with a measurement that
        # never gates, at 80-300 ms of CPU burned on every run of this suite. Its constant was also
        # pinned to his 10-core Mac, so on the CI runners where [[test-venue]] says this suite
        # belongs it would have reported "busy" on essentially every run while changing no verdict.
        # A number on screen that nobody acts on is not instrumentation. [[plumbing-with-no-tap]]
        #
        # The retry below is what actually decides, and it needs no calibration: it re-measures the
        # thing it is about to accuse and keeps only what is slow twice.
        #
        # ⚠ KNOWN AND STATED, not hidden: re-running in-process measures a WARM cost. Import,
        # first-touch and page-cache effects — precisely what a console pays at BOOT, and precisely
        # what the 16,585 ms scar was — are absolved by a retry. That is a real limit of this
        # instrument, it is why the 5x hard ceiling below is judged with no retry at all, and the
        # cold-boot figure needs its own measurement rather than being read out of this one.
        did_work = 0
        _timed = []
        # v2802 — the EVERY-TICK set is what this budget is about, and that is now SLOW *and*
        # PERIODIC removed. PERIODIC exists because `engines corroborate` was too costly for a
        # ten-minute tick and too important to go unwatched; it runs unattended on a longer
        # cadence. Measuring it here would price a cost the every-tick path does not pay.
        _skip = set(cd.SLOW) | set(getattr(cd, "PERIODIC", ()))
        # ⚠⚠ v2815 (#50) — THIS TIMED THE BRANCH THE CONSOLE NEVER TAKES.
        # console_doctor.run() is the ONLY caller of a check in production, and it primes three
        # per-tick caches first. So _board_read() in production ALWAYS returns the cached value:
        #     if _board_cache["active"]: return _board_cache["got"]      <- production, always
        #     return _post("/api/board_ownership", ...)                  <- this gate, always
        # Same for _health_report() and _route_read(). Roughly 9-15 of ~34 checks read through
        # them, so this loop was pricing live fetches the every-tick path does not pay — and,
        # worse, break the cached line and the gate could not notice, because that line is never
        # executed under test.
        # ★ NOT "make the gate call run()" — run()'s own comment records why: "Opened HERE and
        # nowhere else, so a check called on its own still reads fresh — which is what every guard
        # that stubs _post expects, and what my first cut broke eight of." Calling checks BARE is
        # deliberate and eight guards depend on it. So the PRIMING became shareable instead, and
        # only the gate that measures TIMING opts in. [[feedback-blind-fixture-green-gate]]
        # ⚠⚠ v3199 — THE PRIMING IS NOW TIMED UNDER ITS OWN NAME, AND THAT IS THE WHOLE POINT
        # OF THE CHANGE THAT MADE THIS GATE STOP FLAPPING. tick_caches() marked the health cache
        # active and left it EMPTY, while its two siblings were primed with a real read. So the
        # first health-backed check in the roster built the entire health report and was billed
        # for all of it. MEASURED 2026-09-16 inside tick_caches():
        #
        #     armed migration, call 1:  3654 ms     <- the whole health report
        #     armed migration, call 2:     0 ms     <- cached
        #     check_armed_migrations() direct: 15 ms
        #
        # `armed migration` costs FIFTEEN MILLISECONDS. The gate said 3,654 and named it as the
        # culprit, four runs running. That is the flapping recorded at console_doctor.py:3465
        # ("the name it printed CHANGED EVERY RUN ... each of those was innocent") — and the note
        # blamed machine bursts while the mechanism sat three lines from the two caches that do
        # it correctly. [[label-outlived-referent]] [[feedback-suspect-the-instrument]]
        #
        # ⚠⚠ PRIMING IT MUST NOT HIDE THE COST, WHICH IS REAL AND WHICH PRODUCTION PAYS ONCE PER
        # TICK. So it is measured here, printed every run, and judged. Broken down on his Mac:
        #     board_ownership POST    47 ms
        #     health report        2,976 ms      <- this is the tick's real cost
        #     route census           170 ms
        # A fix that moved a 3-second cost somewhere nobody looks would be worse than the wrong
        # name it replaced. [[zero-needs-a-denominator]] [[regression-guard]]
        _t_prime = _t.time()
        with cd.tick_caches():
            _prime_ms = (_t.time() - _t_prime) * 1000
            # REG-1748 — the CPU clock starts AFTER the priming, on the span the wall total covers. It started before
            # `tick_caches()` and so charged the priming (board, health report, route census - judged on its own
            # ceiling above) to the subset, while the wall figure printed beside it did not. (the v3563 second eye)
            _refs = [_ref_cpu_ms()]                   # REG-1990 - this core's speed, read beside the pass it scales
            _cpu0 = _t.process_time()
            for name, fn in cd.CHECKS:
                if name in _skip:
                    continue
                t0 = _t.time()
                try:
                    fn()
                except Exception:
                    pass
                ms = (_t.time() - t0) * 1000
                total += ms
                _timed.append((name, ms))
                if ms > 1.0:
                    did_work += 1
                if ms > BUDGET_MS:
                    slow.append("%s (%.0f ms)" % (name, ms))
        _cpu_total = (_t.process_time() - _cpu0) * 1000.0
        _refs.append(_ref_cpu_ms())
        # ── the priming, reported every run so it can never go back to being unmeasured ──
        print("   tick priming (board + health report + route census): %.0f ms" % _prime_ms)
        print("   dearest check on the every-tick roster: %s"
              % (max(("%s (%.0f ms)" % (n, m) for n, m in _timed), key=lambda x: float(
                  x.rsplit("(", 1)[1].split(" ")[0])) if _timed else "nothing was timed"))
        self.assertTrue(_timed,
                        "no check on the every-tick roster was timed at all, so a green result "
                        "here is UNMEASURED, not clean")
        # ⚠⚠ REG-1997 - INSIDE THE PROVER'S PARALLEL LANES EVERY COST HERE IS THE PROVER'S OWN LOAD. MEASURED: the v3603
        # push #8 clean wave ran this law in one of 4 lanes beside three other law runs and it went red on this case;
        # alone in main minutes later it read 6,607 ms CPU on a fast core against a 9,000 ms budget. "A hard ceiling
        # that no contention explains" holds for his machine's contention, never for four copies of the test suite the
        # prover itself started. So with HEART2_LANES > 1 the readings are printed and the budget is NOT judged here -
        # the push's own suite stage and CI run this case with no lanes and judge it. Never a pass: said, every time.
        _lanes = int(os.environ.get("HEART2_LANES") or 1) if str(os.environ.get("HEART2_LANES") or "1").isdigit() else 1
        if _lanes > 1:
            print("   \u24d8 REG-1997: measured inside %d parallel proving lanes - the cost above is the prover's own "
                  "load, so the budget is UNMEASURED here; the push's suite stage and CI judge it with no lanes" % _lanes)
            return
        # judged like the checks are: a hard ceiling that no contention explains. It is ONE read
        # of his board, one health report and one route census -- if that passes 5x the per-check
        # budget the tick itself is the defect, whatever the machine is doing.
        self.assertLess(_prime_ms, BUDGET_MS * 5,
                        "priming a single doctor tick cost %.0f ms — over %d ms. Every console "
                        "boot and every ten-minute watchdog tick pays this before a single check "
                        "runs, and it is now the tick's largest cost by an order of magnitude."
                        % (_prime_ms, BUDGET_MS * 5))
        # ★ A CALIBRATION MAY NEVER EXCUSE A PATHOLOGICAL COST. The check this gate was built to
        # catch cost 16,585 ms of a 17,069 ms tick. No contention explains 5x the budget, and a
        # guard that skipped THAT would have deleted the only reason this file exists. So the hard
        # ceiling is judged ALWAYS, whatever the machine is doing. [[regression-guard]]
        _pathological = [r for r in slow
                         if float(r.rsplit("(", 1)[1].split(" ")[0]) > BUDGET_MS * 5]
        self.assertEqual(_pathological, [],
                         "no amount of machine contention explains this — a cheap check costing "
                         "over %d ms is a defect wherever it is measured: %s"
                         % (BUDGET_MS * 5, ", ".join(_pathological)))
        # ⚠⚠ RETRY BEFORE ACCUSING — the calibration alone was not enough, and finding that out is
        # what produced this block. A calibration is a POINT SAMPLE taken before the loop, while
        # the loop itself spans eight seconds; a burst inside that window is invisible to it. It
        # measured 43 ms against a 77 ms idle baseline — i.e. "this machine is fast" — in the same
        # run that reported `armed migration (3339 ms)`, a check that costs 75-131 ms when timed
        # six times in a row immediately afterwards. The probe was better than load average and
        # still not an alibi. [[feedback-suspect-the-instrument]] [[zero-needs-a-denominator]]
        #
        # So the gate re-runs whatever went over budget and keeps only what is slow TWICE. A real
        # cost reproduces; a burst does not. This is also the only version of the check that can
        # tell him WHICH it was, and it costs nothing on a green run because nothing is retried.
        if slow:
            _by_name = dict(cd.CHECKS)
            _confirmed, _absolved = [], []
            for _entry in slow:
                _name = _entry.rsplit(" (", 1)[0]
                _first = _entry.rsplit("(", 1)[1].rstrip(")")
                _fn = _by_name.get(_name)
                if _fn is None:                       # roster changed under us — cannot re-measure
                    _confirmed.append(_entry)
                    continue
                _r0 = _t.time()
                try:
                    _fn()
                except Exception:
                    pass
                _again = (_t.time() - _r0) * 1000
                if _again > BUDGET_MS:
                    _confirmed.append("%s (%s, again %.0f ms)" % (_name, _first, _again))
                else:
                    _absolved.append("%s (%s -> %.0f ms on retry)" % (_name, _first, _again))
            for _a in _absolved:
                print("   \u21bb %s — the first reading was the machine, not the code" % _a,
                      flush=True)
            slow = _confirmed
        self.assertEqual(slow, [],
                         "these run on the watchdog's 10-minute timer AND at every console boot, "
                         "and they are not cheap — each was re-measured and slow BOTH times, "
                         "so a passing burst is not the cause: %s" % ", ".join(slow))
        # ⚠⚠ AND THE SAME DISCIPLINE ON THE TOTAL, for the same reason. Measured back to back on
        # unchanged code, minutes apart: **4,132 ms and 11,105 ms**. A wall-clock figure that moves
        # 2.7x between runs of identical code is not a property of that code, and taking the WORSE
        # of two readings makes the gate report the machine's worst moment as the subsystem's cost.
        #
        # For a floor-bounded quantity the MINIMUM is the honest estimator: no run can be faster
        # than the code allows, so noise can only ever push a reading UP. This is not leniency —
        # a genuine 17-second tick is slow on both passes and still fails, which is the case the
        # gate exists for. [[unknown-stays-unknown]] [[feedback-suspect-the-instrument]]
        # ⚠⚠ v3320 — AND THE RE-MEASURE PRICED A DIFFERENT, LARGER POPULATION THAN THE FIRST
        # PASS. The first loop skips `_skip` = SLOW | PERIODIC; this one skipped only SLOW, so it
        # re-ran `engines corroborate` and `sweep would find` — the two checks PERIODIC exists to
        # keep OFF the every-tick bill. MEASURED on his Mac 2026-09-18, same tick, same code:
        #
        #     first-pass population (63 checks)   4,134 ms    <- under the 9,000 ms budget
        #     retry population      (65 checks)   8,859 ms
        #     the surcharge: engines corroborate 3,057 + sweep would find 1,667 = 4,725 ms
        #
        # `min()` over two different populations is not a minimum of anything. It meant the retry
        # could only ever absolve a burst LARGER than 8,859 ms — so the mechanism this block calls
        # "what actually decides" was unreachable for every realistic burst, and the gate refused
        # a legitimate push at 10,146 ms while the subset it names cost 4,134. A reading is only
        # comparable to a reading of the SAME population. [[v3313]] [[v3317]]
        if total >= BUDGET_MS * 3:
            # ⚠⚠ v3456 — AND THE RE-READ MUST BE PRIMED TOO, OR IT IS NOT THE SAME READING.
            # v3313/v3317 taught this block that "a reading is only comparable to a reading of the
            # SAME population". The same rule governs CACHE STATE and this retry sat OUTSIDE the
            # `with cd.tick_caches()` block above (proved by AST: the with spans 22281-22297, this
            # branch 22386-22401), so pass 1 measured the PRIMED path production takes and pass 2
            # measured the UNPRIMED one it never takes.
            # MEASURED on a quiet machine, same 94 checks, same minute:
            #     primed    5,092 ms      unprimed   16,791 ms
            # The unprimed read is ~3x dearer, so it is ALWAYS the larger of the two and
            # `min(total, _t2)` could only ever return pass 1. The mechanism this block calls
            # "what actually decides" was inert: it can never absolve anything.
            # [[feedback-suspect-the-instrument]] [[a-gate-can-perturb-what-it-measures]]
            _t2 = 0.0
            with cd.tick_caches():
                _refs.append(_ref_cpu_ms())
                _c2 = _t.process_time()        # REG-1748 — after this pass's priming too
                for _n, _f in cd.CHECKS:
                    if _n in _skip:
                        continue
                    _r0 = _t.time()
                    try:
                        _f()
                    except Exception:
                        pass
                    _t2 += (_t.time() - _r0) * 1000.0
            print("   \u21bb the same %d-check population re-measured: %.0f ms "
                  "(first pass %.0f ms) — taking the lower of the two"
                  % (len([n for n, _ in cd.CHECKS if n not in _skip]), _t2, total),
                  flush=True)
            total = min(total, _t2)
            _cpu_total = min(_cpu_total, (_t.process_time() - _c2) * 1000.0)
            _refs.append(_ref_cpu_ms())
        # ⚠ #42 (2026-10-02) - THE WHOLE-SUBSET TOTAL IS JUDGED ON CPU TIME, the work these checks do. Wall clock counts
        # every other process on his Mac: the v3562/v3563 pushes were refused at 9,882 / 10,115 ms while he played,
        # Time Machine backed up and GrokBot drove (load 5-6); alone, minutes later, the same case passed. The
        # per-check limits above stay on wall clock - a single heavy check (the 16,585 ms sweep this gate exists for)
        # is still caught there, twice-confirmed or past the 5x ceiling.
        # ⚠⚠ REG-1990 - CPU TIME IS NOT WORK ON HIS MAC. The M4 has 4 fast cores and 6 slow ones, and MEASURED on
        # 2026-10-07 the same fixed loop cost 102-118 ms of CPU on a fast core and ~1,000 ms per 6M on a slow one
        # (2.5x). Under load (his console reading, a push proving) the scheduler moves this process to the slow
        # cores and every "CPU ms" grows with it: the v3596, v3599 and v3602 pushes were refused at 10,083 /
        # 12,730 / 11,147 ms, and the last, run ALONE minutes later, read 11,039. So the figure is judged against a
        # REFERENCE workload read in this same process before and after each pass: the budget is BUDGET_MS * 3 at
        # the fast-core reference speed and grows by the ratio the reference itself slowed, capped at REF_CAP. A
        # subset that really got dearer is dearer than the reference too, and still fails. [[suspect-the-instrument]]
        _ref = sum(_refs) / float(len(_refs))
        _budget, _scale = _cheap_budget(_refs, BUDGET_MS * 3)
        print("   the whole cheap subset: %.0f ms wall, %.0f ms CPU (the CPU figure is judged); the reference workload read %.0f ms here against %.0f ms on a fast core, so the budget is %.0f ms (x%.2f)"
              % (total, _cpu_total, _ref, REF_FAST_MS, _budget, _scale))
        total = _cpu_total
        self.assertLess(total, _budget,
                        "the whole cheap subset costs %.0f ms across TWO passes — it is in the "
                        "boot path of every console a test spawns, and a second reading confirmed "
                        "it across two passes (the budget %.0f ms already allows for a core %.2fx slower)"
                        % (total, _budget, _scale))
        # And say plainly when the measurement was thin, rather than reporting a pass that measured
        # nothing. This is UNMEASURED, not fine — the distinction the whole tree is built on.
        if did_work < 2:
            print("   \u26a0 the cheap-subset budget measured almost nothing on this machine "
                  "(%d of %d check(s) took over 1 ms). A green result here is UNMEASURED, not "
                  "proof the subset is cheap — the 16.6 s check this caught was only catchable on "
                  "a tree with a console, art and footage."
                  % (did_work, len([n for n, _ in cd.CHECKS if n not in _skip])), flush=True)

    def test_a_check_moved_to_SLOW_is_still_RUN_somewhere(self):
        """The mirror: moving a check into SLOW stops the watchdog running it. That is only safe
        because the full run still does. A check in neither is a check nobody performs."""
        cd = self._cd()
        names = [n for n, _ in cd.CHECKS]
        for s in cd.SLOW:
            self.assertIn(s, names, "%r is in SLOW and not on the roster at all" % s)
        # #42 (2026-10-02) - THE QUESTION IS WHICH CHECKS run() SELECTS, NOT WHAT THEY FIND. Running every real check
        # cost 23.1 s of the push gate (measured per case); the same roster with stand-in checks drives the same
        # selection loop, and nothing is written to the doctor's saved reading.
        import unittest.mock as mock

        def stand_in():
            raise RuntimeError("stand-in")
        with mock.patch.object(cd, "CHECKS", [(n, stand_in) for n in names]), \
                mock.patch.object(cd, "_persist_slow", lambda rows: None):
            full = [r["check"] for r in cd.run(include_slow=True)]
            cheap = [r["check"] for r in cd.run(include_slow=False) if not r.get("notAsked")]
        for s in cd.SLOW:
            self.assertIn(s, full, "%r is skipped by BOTH the cheap and the full run" % s)
        self.assertTrue(set(cd.SLOW) - set(cheap) or not cd.SLOW,
                        "PREMISE: the cheap run skips none of SLOW, so this case cannot tell the two runs apart")

    def test_a_check_that_throws_becomes_UNKNOWN_not_a_crash(self):
        cd = self._cd()
        import unittest.mock as mock
        def boom():
            raise RuntimeError("deliberate")
        with mock.patch.object(cd, "CHECKS", [("exploder", boom)]):
            rows = cd.run(include_slow=False)
        self.assertEqual(rows[0]["state"], cd.UNKNOWN)
        self.assertIn("threw", rows[0]["why"])


class TestV2079TheWallKeepsHisPlace(unittest.TestCase):
    """Konyo: "grail wall ✓ snaps the drawer shut."

    v2077 removed the d2r_grailWallOpen persistence so the wall starts COLLAPSED on every load —
    correct, and it took the re-render with it: every ✓ rebuilds the forge, the fresh <details> has
    no open attribute, and the drawer he is working inside closes under his hand, filter and scroll
    gone, on the exact action the wall exists for."""

    def _html(self):
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            return fh.read()

    def test_the_open_state_lives_in_the_page_not_the_browser(self):
        """Both rulings hold only because the lifetimes differ. If this state ever reaches
        localStorage, v2077's defect is back and this test is the thing that says so."""
        s = self._html()
        i = s.index("var _wallOpen = {}")
        blk = s[i:s.index("function _allGrid(", i)]
        self.assertNotIn("localStorage", blk,
                         "the wall's open state reached storage — a reload will start it OPEN again")
        # Anchored on the CALL, never the NAME. The name appears in v2077's own comment explaining
        # that the key was removed, so `assertNotIn("d2r_grailWallOpen")` fails on my prose while
        # the code is correct — the guard going red for its own reasons rather than the subject's.
        # A storage call naming the key cannot appear in a sentence about it. [[source-reading-guard]]
        for call in ("getItem('d2r_grailWallOpen'", 'getItem("d2r_grailWallOpen"',
                     "setItem('d2r_grailWallOpen'", 'setItem("d2r_grailWallOpen"'):
            self.assertNotIn(call, s, "the persisted key v2077 removed is being %s again"
                             % ("read" if "get" in call else "written"))

    def test_a_re_render_restores_it_and_both_forges_call_that(self):
        """Anchored on the CALL, never the name — a name appears in every sentence about it and a
        guard that matches prose passes with the code deleted. [[source-reading-guard]] 4b"""
        s = self._html()
        # Counting the SUBSTRING is blind: commenting a call out leaves it in the file and the
        # count unchanged. Proven — that exact sabotage passed on the first cut of this guard.
        # Count LIVE call sites: the text present on a line whose code half is not commented out.
        live = [ln for ln in s.splitlines()
                if "window.gfWallRestore(box);" in ln
                and not ln.strip().startswith("//")
                and ln.index("window.gfWallRestore") < (ln.index("//") if "//" in ln
                                                        else len(ln))]
        self.assertEqual(len(live), 2,
                         "the uniques forge and the sets forge must BOTH restore the wall after "
                         "they rewrite innerHTML; found %d LIVE call site(s)" % len(live))
        self.assertIn("ontoggle=\"window.gfWallToggled(this)\"", s,
                      "nothing records that he opened it, so a re-render has nothing to restore")

    def test_the_filter_and_the_scroll_come_back_too(self):
        """Restoring `open` while the list underneath shows all 398 rows from the top is a drawer
        that only LOOKS like it kept his place."""
        s = self._html()
        i = s.index("window.gfWallRestore=function(root)")
        blk = s[i:s.index("</script>", i)]
        self.assertIn("window.gfWallFilter(inp)", blk, "the typed filter is not re-applied")
        self.assertIn("grid.scrollTop=st.top", blk, "the scroll offset is not restored")
        self.assertIn("st.q = inp.value", self._html(), "typing is never banked")


class TestV2079OneSpellingForARarityColour(unittest.TestCase):
    """v2073 fixed the flat-cream grail wall by INVENTING `.gp-nm-uni` / `.gp-nm-set`, three new
    rules sitting a few hundred lines below two that had been colouring item names in these exact
    two tabs since v1625. Nobody was wrong at any step and the page looked right — but two
    spellings of one idea is how they drift, and the next person to retune the rarity palette would
    have found one of them. [[copy-drift]]"""

    def _html(self):
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            return fh.read()

    def _css_only(self, s):
        """Strip HTML comments and JS-style block comments so this grades RULES, not the prose that
        explains them — including the paragraph above the fix, which names both dead classes.
        Bounded so a stray `/*` inside a string cannot eat a third of the file.
        [[source-reading-guard]] §4"""
        s = re.sub(r"<!--.{0,6000}?-->", " ", s, flags=re.S)
        return re.sub(r"/\*.{0,6000}?\*/", " ", s, flags=re.S)

    def test_the_invented_classes_are_gone_from_the_STYLESHEET(self):
        css = self._css_only(self._html())
        for dead in ("gp-nm-uni", "gp-nm-set"):
            self.assertNotIn(dead, css,
                             "%s is a second spelling of a colour rule this page already had" % dead)

    def test_the_rule_that_survived_covers_the_wall_too(self):
        """The whole point of collapsing them: the ONE surviving rule must reach the missing chips,
        or the wall goes back to flat cream and the merge was a silent regression."""
        css = self._css_only(self._html())
        self.assertIn("#tab-funi .gf-piece .gf-nm,#tab-funi .gf-piece .gp-nm", css)
        self.assertIn("#tab-fsets .gf-nm,#tab-fsets .gp-nm", css)

    def test_the_glow_stays_on_FOUND_only(self):
        """Colour says WHAT IT IS, glow says YOU HAVE IT. 398 glowing missing names say both at
        once and neither clearly — and that is what plain `#tab-funi .gf-piece .gf-nm{...glow}`
        would do the moment the wall started using a matched class."""
        css = self._css_only(self._html())
        # Match the PROPERTY at a declaration boundary, not the substring. `xtext-shadow:` contains
        # "text-shadow" and is inert CSS — a sabotage that killed the glow passed the first cut of
        # this assertion for exactly that reason.
        prop = re.compile(r"[{;]\s*text-shadow\s*:")
        i = css.index("#tab-funi .gf-piece.have .gf-nm")
        self.assertTrue(prop.search(css[i:css.index("}", i) + 1]),
                        "the found glow was lost in the merge")
        j = css.index("#tab-funi .gf-piece .gf-nm,#tab-funi .gf-piece .gp-nm")
        self.assertFalse(prop.search(css[j:css.index("}", j) + 1]),
                         "the glow leaked onto every MISSING name")

    def test_the_renderer_no_longer_takes_an_argument_its_container_knows(self):
        """`rar` only existed to tell a shared renderer something the tab scope already decides."""
        s = self._html()
        self.assertIn("function _allGrid(title, sub, entries, fn){", s)
        self.assertNotIn("' gp-nm-' + rar", s)


class TestV2079AnUnreadableLedgerHoldsTheFootage(unittest.TestCase):
    """THE ONE WITH NO UN-DELETE. On origin since v2065.

    `_load` answered {} for both "never written" and "exists and will not parse". With an
    unreadable vault_swept.json, `_entry(vault, reel)` is None for EVERY reel, so every reel a
    chronicle sweep has read falls past `ve is None and _vault_lane_owes(...)` — false for any reel
    that declared a chronicle focus — into `else:` and out as ELIGIBLE, reported as "sealed by BOTH
    lanes"."""

    def _tree(self, n=None):
        """⚠ v2876 — SIZED FROM KEEP_RECENT, NOT FROM A LITERAL. Konyo raised the shield
        from 5 to 8; this fixture built exactly 6 reels, so the WHOLE shelf fell inside it
        and eleven laws went red on a correct tree ("8 not less than 8"). A fixture whose
        size is tied to a constant must be DERIVED from it. [[feedback-blind-fixture-green-gate]]
        """
        import reel_retention as _rr_keep
        if n is None:
            n = _rr_keep.KEEP_RECENT + 3
        import json as _j
        root = tempfile.mkdtemp(prefix="reelledger_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "frames", "hist")
        os.makedirs(hist)
        chron = {}
        for i in range(n):
            sid = "s_150000000%04d" % i
            d = os.path.join(hist, "reel_" + sid)
            os.makedirs(d)
            io.open(os.path.join(d, "f_%s_1.jpg" % sid), "w").write("x" * 1000)
            chron["reel_" + sid] = {"pages": 9}
        io.open(os.path.join(root, "chronicle_swept.json"), "w").write(_j.dumps(chron))
        io.open(os.path.join(root, "vault_swept.json"), "w").write(
            _j.dumps(dict((k, {"rows": 0}) for k in chron)))
        io.open(os.path.join(root, "vault_accum.json"), "w").write(_j.dumps({"owned": []}))
        io.open(os.path.join(root, "vault_seen.json"), "w").write(_j.dumps({"rows": []}))
        return root, hist

    def _plan(self, root, hist):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import reel_retention as rr
        old = rr.HERE
        rr.HERE = root
        self.addCleanup(setattr, rr, "HERE", old)
        return rr.plan(hist_dir=hist)

    def test_the_branch_is_reachable_or_this_whole_case_proves_nothing(self):
        """A gate that could never release a reel cannot be shown to have stopped releasing one.
        [[feedback-blind-fixture-green-gate]]"""
        root, hist = self._tree()
        p = self._plan(root, hist)
        self.assertTrue(p["candidates"],
                        "with every ledger readable nothing was eligible — the fixture cannot "
                        "demonstrate a hold, so the cases below would pass vacuously")
        self.assertEqual(p["unreadable"], [])

    def test_a_seal_store_that_will_not_parse_holds_every_reel(self):
        root, hist = self._tree()
        io.open(os.path.join(root, "vault_swept.json"), "w").write("{ this is not json")
        p = self._plan(root, hist)
        self.assertEqual(p["candidates"], [],
                         "footage was released for deletion on the strength of a ledger that "
                         "could not be opened")
        self.assertIn("vault_swept.json", p["unreadable"])
        self.assertTrue(any("ledger-unreadable" in (k.get("why") or "") or "will not parse"
                            in (k.get("why") or "") for k in p["kept"]),
                        "everything was held but he is not told why")

    def test_a_durable_store_that_will_not_parse_holds_every_reel(self):
        root, hist = self._tree()
        io.open(os.path.join(root, "vault_accum.json"), "w").write("]]not json[[")
        p = self._plan(root, hist)
        self.assertEqual(p["candidates"], [])
        self.assertTrue(p["unreadable"], "witness_index reported ok=False and it was dropped again")

    def test_ABSENT_is_a_measurement_and_must_not_be_treated_as_unknown(self):
        """The mirror, and the reason this is not just 'hold on any falsy load': vault_swept.json
        genuinely does not exist on a tree that has never run a vault sweep. Holding forever on a
        file that was never supposed to be there is the same defect pointed the other way."""
        root, hist = self._tree()
        os.remove(os.path.join(root, "vault_swept.json"))
        p = self._plan(root, hist)
        self.assertEqual(p["unreadable"], [],
                         "an absent store was reported as unreadable — 'never written' and 'will "
                         "not parse' are opposite facts")

    def test_the_inert_rule_is_not_reported_as_an_unmeasured_gap(self):
        """`ledger-unreadable` cannot fire on a healthy tree. Listing it under neverFired would
        train him to ignore the list that names real gaps."""
        root, hist = self._tree()
        p = self._plan(root, hist)
        self.assertNotIn("ledger-unreadable", p["neverFired"])
        self.assertIn("ledger-unreadable", p["notApplicable"])


class TestV2079EveryWatcherStartsInBothModes(unittest.TestCase):
    """v1761 carved this and paid for it: "A background job attached to a WINDOW is a background
    job that vanishes the moment you run without one." It then fixed it for ONE thread by writing a
    SECOND start site in the headless branch, and every watcher added afterwards went into the
    window branch only.

    Measured 2026-08-24 on a headless console: seven of nine threads never existed — the rolling
    prune, the only durable copy of his grail ledgers, the space warden, the version-drift watcher
    and the eagle watchdog itself. [[copy-drift]] [[the-unjoined-end]]"""

    def _ca(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app
        return control_app

    def test_there_is_exactly_one_roster(self):
        """Two start sites for one roster IS the defect. Anchored on the CALL: a thread start
        cannot appear inside a sentence about one."""
        import inspect
        src = inspect.getsource(self._ca())
        starts = re.findall(r"threading\.Thread\(target=(\w+)", src)
        in_roster = re.search(r"def start_background_watchers.*?\n(?=\ndef |\n# )", src, re.S)
        self.assertTrue(in_roster, "the roster function is gone")
        for name in ("_prune_loop", "_ledger_backup_loop", "_warden_loop", "_drift_loop",
                     "_eagle_watch_loop", "_chron_autoread_loop", "_stash_watch_loop"):
            self.assertEqual(starts.count(name), 0,
                             "%s is started by a hand-written threading.Thread again — it belongs "
                             "in the roster, or one start path will lose it" % name)
            self.assertIn(name, in_roster.group(0), "%s fell out of the roster" % name)

    def test_both_start_paths_call_it(self):
        import inspect
        src = inspect.getsource(self._ca())
        self.assertEqual(src.count("start_background_watchers("), 3,
                         "expected the definition plus exactly two callers (window + headless); "
                         "found %d mention(s)" % src.count("start_background_watchers("))

    def test_it_actually_starts_them_and_names_any_that_fail(self):
        with inert_roster() as start:
            r = start("test")
            # v2120 (#27) — PROVE IT INSIDE THE `with`. inert_roster's finally calls stop.set(),
            # which releases every sleeper, so a liveness assert placed after the block races
            # threads that are already exiting: green if no daemon has noticed yet, red if one
            # has. Its own sibling test was rewritten at v2088 for exactly that flake and this
            # one never got the same treatment. [[feedback-suspect-the-instrument]]
            live = set(t.name for t in threading.enumerate())
        self.assertEqual(r["failed"], [], "a watcher failed to start: %r" % r["failed"])
        # REG-1893 - an empty roster passes "every roster name is running" while starting nothing.
        self.assertTrue(r["roster"], "start() returned an empty roster, so 'it actually starts them' "
                                     "would be vacuous")
        for name in r["roster"]:
            self.assertIn(name, live, "%s is in the roster and not running" % name)

    def test_it_is_idempotent_so_a_second_call_cannot_double_a_watcher(self):
        """v2088 — ASSERT THE PROPERTY, NOT A PROXY THAT DEPENDS ON A RACE.

        This asserted `again["started"] == []`, which is only true if every thread the FIRST call
        armed is still alive when the second runs. threading.enumerate() is process-global and the
        inert stub is `lambda: stop.wait(30)`, so a leftover watcher from an earlier test in the
        same process can be alive at call one (which therefore skips it), die, and be legitimately
        started by call two. Then `started == ['tvd-stash-watch']` and the test fails having found
        no defect at all.

        It failed exactly that way on CI — one name, tvd-stash-watch — and passed here every time,
        including in CI's own two-module invocation. A test whose verdict depends on thread
        scheduling is not measuring the code. [[feedback-suspect-the-instrument]]

        "Cannot double a watcher" means: never two LIVE threads with the same name, and never
        re-arm one that is already running. Both are race-free. Restarting a watcher that has
        genuinely DIED is correct behaviour, not a defect — that is recovery.
        """
        import threading as _th
        # ⚠⚠ v3150 — THE RACE THE DOCSTRING ABOVE DESCRIBES WAS ONLY HALF FIXED. `started` stopped
        # being a proxy, but BOTH readings below still enumerated threads PROCESS-GLOBALLY, and
        # threading.enumerate() returns every leftover `tvd-*` watcher an earlier test in this
        # process armed. One of those alive under a name this test also arms counts as a duplicate
        # `start()` never created — and the same leftover in `before` can flag a legitimate restart
        # as a re-arm. The comment here once read "MEASURED on a clean tree: 2 OK, 1 FAILED in
        # three consecutive runs, and it blocked a ship on ['tvd-orphan-exit'] having found no
        # defect at all" — and that diagnosis was WRONG. v3177: tvd-orphan-exit was started
        # unconditionally ABOVE the roster, so it never went through the name check this function
        # promises, and a second call really did spawn a second copy. The variability was only
        # whether the FIRST one was still alive at check time (_orphan_exit_loop exits early with
        # no console to watch); with a console running on :17772 it is deterministic — measured
        # 5 of 5, and 3 of 3 against already-shipped v3175. The instrument was right and was
        # filed as noise. [[feedback-suspect-the-instrument]]
        # The threads THIS test armed are the only ones it may judge; holding the pre-existing
        # objects in a set (rather than their ids) also stops a recycled id from re-introducing it.
        # A genuine doubling is still caught: both threads would be new, so both are counted.
        # [[feedback-suspect-the-instrument]] [[gate-blind-to-unexercised-input]]
        _pre = set(_th.enumerate())

        def _mine():
            return [t for t in _th.enumerate()
                    if t.name.startswith("tvd-") and t.is_alive() and t not in _pre]

        with inert_roster() as start:
            start("first")
            before = set(t.name for t in _mine())
            again = start("second")
            after = [t.name for t in _mine()]

        doubled = sorted(n for n in set(after) if after.count(n) > 1)
        self.assertEqual(doubled, [],
                         "two live threads share a watcher name — the roster doubled it: %r" % doubled)

        re_armed = sorted(set(again["started"]) & before)
        self.assertEqual(re_armed, [],
                         "these watchers were ALREADY RUNNING and were started a second time: %r"
                         % re_armed)

    def test_a_watcher_measures_before_it_sleeps(self):
        """`time.sleep()` at the top of the loop publishes `checked: None` for the whole first
        period, and a surface reading it cannot tell 'all clear' from 'nobody looked yet'."""
        import inspect
        for fn in ("_drift_loop", "_eagle_watch_loop"):
            src = inspect.getsource(getattr(self._ca(), fn))
            body = src[src.index("while True:"):]
            sleep_at = body.index("time.sleep(")
            work_at = min(body.index("_drift_once()") if "_drift_once()" in body else 10 ** 9,
                          body.index("_eagle_once()") if "_eagle_once()" in body else 10 ** 9)
            self.assertIn("if not first:", body[:sleep_at],
                          "%s sleeps before its first measurement" % fn)
            self.assertLess(work_at, 10 ** 9)


class TestV2079TheScarLedgerAndTheHealer(unittest.TestCase):
    """Konyo: "give it the capabilities to see this so when it happens in the future it can auto
    scar / auto heal / auto fix."

    SCAR is unconditional — remembering costs nothing. HEAL is opt-in and exists only where the
    repair is RE-DERIVABLE FROM EVIDENCE rather than an act of judgement."""

    def _ch(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import console_healer
        return console_healer

    def _isolated(self):
        ch = self._ch()
        d = tempfile.mkdtemp(prefix="scarledger_")
        self.addCleanup(shutil.rmtree, d, True)
        prev = os.environ.get("TV_SCAR_ROOT")
        os.environ["TV_SCAR_ROOT"] = d
        self.addCleanup(lambda: os.environ.__setitem__("TV_SCAR_ROOT", prev) if prev
                        else os.environ.pop("TV_SCAR_ROOT", None))
        old = ch.LEDGER
        ch.LEDGER = os.path.join(d, ".scars.json")
        self.addCleanup(setattr, ch, "LEDGER", old)
        ch._DISARMED.clear()
        return ch

    def test_a_returning_fault_is_named_a_RETURN(self):
        """The one sentence nothing in the system could say before, and the reason he kept meeting
        the same defect as a surprise.

        ⚠ v2080 — "IT CLEARED" IS AN OK ROW, NOT AN EMPTY READING. The first cut of this case
        expressed the clear as `record([])`, which is exactly the confusion that produced the
        manufactured-returns bug: absence of a fault in a reading is not evidence the fault is gone.
        A watchdog running the cheap subset omits whole checks every tick."""
        ch = self._isolated()
        red = [{"check": "visual lock", "state": "missing", "why": "the wall lost its colour"}]
        green = [{"check": "visual lock", "state": "ok", "why": "all four pins hold"}]
        ch.record(red, now_ms=1000)
        ch.record(green, now_ms=2000)                    # it cleared, and SAID so
        out = ch.record(red, now_ms=3000)                # and came back
        self.assertEqual(out[0]["returns"], 1)
        self.assertIn("COME BACK 1 time", ch.says(out[0]))
        ch.record(green, now_ms=4000)
        ch.record(red, now_ms=5000)
        self.assertEqual(ch.record(red, now_ms=6000)[0]["returns"], 2,
                         "the return count reset — a fault that keeps coming back must keep saying so")

    def test_ONE_CHECK_REPHRASING_ITSELF_IS_NOT_A_RETURN(self):
        """FOUND ON HIS LIVE LEDGER: two `disk headroom` fingerprints, each reporting returns=6.
        Twelve returns, none of which happened.

        `_check_disk_headroom` emits one shape under the 8GB floor and a different one above it, so
        a disk oscillating across that line made shape A vanish and shape B appear, over and over,
        with the check RED throughout. The return count is the one number this module exists to
        produce and it was counting a rephrasing."""
        ch = self._isolated()
        below = {"check": "disk headroom", "state": "missing", "why": "7.9GB free — BELOW the 8GB floor"}
        above = {"check": "disk headroom", "state": "missing",
                 "why": "9.2GB free — your last 3 reel(s) averaged 2.1GB/hour, about 1.8 hour(s)"}
        for i, row in enumerate([below, above] * 4):
            out = ch.record([row], now_ms=1000 + i)
        self.assertEqual(out[0]["returns"], 0,
                         "a check that never stopped failing was reported as having COME BACK %d "
                         "time(s)" % out[0]["returns"])

    def test_a_check_the_reading_never_RAN_does_not_clear(self):
        """The watchdog runs include_slow=False, so whole checks are absent from most readings.
        Treating that as "fixed" is the same error one step further out. [[unknown-stays-unknown]]"""
        ch = self._isolated()
        ch.record([{"check": "visual lock", "state": "missing", "why": "drifted"}], now_ms=1000)
        ch.record([{"check": "disk headroom", "state": "ok", "why": "fine"}], now_ms=2000)
        held = [v for v in ch.history().values() if v["check"] == "visual lock"][0]
        self.assertIsNone(held.get("clearedAt"),
                          "a check that was not measured this round was recorded as cleared")

    def test_two_DIFFERENT_failures_of_one_check_stay_two_scars(self):
        """The mirror: keying on the check alone would let fixing one defect clear the other."""
        ch = self._isolated()
        a = {"check": "visual lock", "state": "missing", "why": "the wall lost its colour"}
        b = {"check": "visual lock", "state": "missing", "why": "the sealed title stopped speaking"}
        ch.record([a, b], now_ms=1000)
        self.assertEqual(len([v for v in ch.history().values() if v["check"] == "visual lock"]), 2,
                         "two distinct failures of one check collapsed into a single scar")

    def test_the_SIZE_of_a_fault_is_not_its_identity(self):
        """"2385 frames belong to no reel" and "12 frames belong to no reel" are one scar
        returning. Fingerprinted on the shape or every recurrence reads as a first sighting."""
        ch = self._isolated()
        a = ch.fingerprint("footage", "2385 frame(s) (3.15 GB) belong to NO reel")
        b = ch.fingerprint("footage", "12 frame(s) (0.01 GB) belong to NO reel")
        self.assertEqual(a, b)
        self.assertNotEqual(a, ch.fingerprint("footage", "the hist directory is unreadable"))

    def test_healing_is_OFF_unless_armed_and_says_what_it_would_do(self):
        ch = self._isolated()
        os.environ.pop("TV_AUTO_HEAL", None)
        state, said = ch.heal({"check": "footage has a reel", "why": "x", "heal": {}})
        self.assertEqual(state, "not-armed")
        self.assertIn("TV_AUTO_HEAL=1", said)

    def test_a_remedy_that_does_not_clear_its_check_is_DISARMED(self):
        """LAW 2, and it is what stops a repair loop from touching his files forever."""
        ch = self._isolated()
        os.environ["TV_AUTO_HEAL"] = "1"
        self.addCleanup(os.environ.pop, "TV_AUTO_HEAL", None)
        old = ch.REMEDIES.get("footage has a reel")
        ch.REMEDIES["footage has a reel"] = ("test double", lambda: (True, "pretended to fold"))
        self.addCleanup(ch.REMEDIES.__setitem__, "footage has a reel", old)
        scar = ch.record([{"check": "footage has a reel", "state": "missing", "why": "12 loose"}])[0]
        first = ch.heal(scar, recheck=lambda: ("missing", "still 12 loose"))
        self.assertEqual(first[0], "still-red",
                         "a remedy graded its own homework — the check was never re-run")
        second = ch.heal(scar, recheck=lambda: ("missing", "still 12 loose"))
        self.assertEqual(second[0], "disarmed", "the failed remedy would be retried forever")

    def test_a_code_regression_gets_NO_remedy_and_says_so(self):
        """A module that silently rewrote code to make its own gate go green would be the single
        most dangerous thing in this tree."""
        ch = self._isolated()
        for check in ("visual lock", "locked lanes", "art corpus", "disk headroom"):
            state, said = ch.heal({"check": check, "why": "x", "heal": {}})
            self.assertEqual(state, "no-remedy", "%s acquired a machine repair" % check)
            self.assertIn("needs a person", said)

    def test_no_remedy_deletes_anything_of_his(self):
        """LAW 3, read off the remedies themselves rather than asserted about them."""
        import inspect
        ch = self._ch()
        # v2080 — AND FOLLOW THE CALLEES. The first cut inspected only each remedy's OWN frame,
        # so `of.apply_plan(p, yes=True)` was certified without the guard ever reading apply_plan.
        # A promise about what code does must cover the code it delegates to, or it is a promise
        # about one stack frame. [[source-reading-guard]]
        import orphan_fold as _of
        subjects = [(n, fn) for n, (_w, fn) in ch.REMEDIES.items()]
        subjects += [("orphan_fold.apply_plan", _of.apply_plan),
                     ("orphan_fold.plan", _of.plan)]
        for name, fn in subjects:
            src = inspect.getsource(fn)
            src = re.sub(r'"""..*?"""', " ", src, flags=re.S)     # the prose says "deleted" a lot
            src = "\n".join(ln for ln in src.splitlines() if not ln.lstrip().startswith("#"))
            for banned in ("os.remove(", "shutil.rmtree(", "os.unlink(", "os.rmdir("):
                self.assertNotIn(banned, src,
                                 "the remedy path %r calls %s — no remedy may destroy his data"
                                 % (name, banned))

    def test_the_watchdog_actually_calls_the_ledger(self):
        """Built on both ends and never joined is the failure mode this whole file exists for.

        ⚠ v2080 — THE FIRST CUT OF THIS GUARD COULD NOT GO RED, and an adversarial review proved
        it: `assertIn("_ch.tend(rows", src)` passes with the call commented out, because a `#` does
        not remove the text. The guard written to catch "the eagle sees and never remembers" would
        have stayed green through exactly that. Count LIVE lines, not substrings.
        [[source-reading-guard]] 4b"""
        import inspect
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app
        src = inspect.getsource(control_app._eagle_once)
        live = [ln for ln in src.splitlines()
                if "_ch.tend(rows" in ln and not ln.lstrip().startswith("#")]
        self.assertEqual(len(live), 1,
                         "the eagle sees and never remembers: %d LIVE call(s) to the scar ledger"
                         % len(live))
        # and it must be REACHED, not merely present in a branch that never runs
        self.assertTrue(any("import console_healer as _ch" in ln for ln in src.splitlines()
                            if not ln.lstrip().startswith("#")),
                        "the ledger module is never imported on a live line")


class TestV2080TheExtractPruneCycleIsClosed(unittest.TestCase):
    """Konyo: "why is this not being optimized and pruned automatically like we said based on data
    and reels getting extracted".

    Because it never was. v2006 gave reel_retention a caller for the first time and wrote, in as
    many words: "IT REPORTS, IT NEVER DELETES ... `--apply --yes` stays a thing he types." So the
    EXTRACT half ran on its own and the PRUNE half always needed him. Measured the day he asked: 30
    reels, 0 MB reclaimable, 1.6 GB free on a 228 GB disk, and his own gates failing with DISK TOO
    FULL TO RECORD — while 11 reels (609 MB) sat locked behind a sweep that had never run.

    The ORDER is the safety. Every case here is a REFUSAL except two."""

    def _tree(self, n=None, mb_each=1.2):
        """⚠ v2876 — SIZED FROM KEEP_RECENT, NOT FROM A LITERAL. Konyo raised the shield
        from 5 to 8; this fixture built exactly 8 reels, so the WHOLE shelf fell inside it
        and eleven laws went red on a correct tree ("8 not less than 8"). A fixture whose
        size is tied to a constant must be DERIVED from it. [[feedback-blind-fixture-green-gate]]
        """
        import reel_retention as _rr_keep
        if n is None:
            n = _rr_keep.KEEP_RECENT + 3
        import json as _j
        root = tempfile.mkdtemp(prefix="prunecycle_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        chron = {}
        for i in range(n):
            sid = "s_150000000%04d" % i
            d = os.path.join(hist, "reel_" + sid)
            os.makedirs(d)
            io.open(os.path.join(d, "f_%s_0.jpg" % sid), "w").write("x" * int(mb_each * 1e6))
            chron["reel_" + sid] = {"pages": 9}
        io.open(os.path.join(root, "chronicle_swept.json"), "w").write(_j.dumps(chron))
        io.open(os.path.join(root, "vault_swept.json"), "w").write(
            _j.dumps(dict((k, {"rows": 0}) for k in chron)))
        io.open(os.path.join(root, "vault_accum.json"), "w").write(_j.dumps({"owned": []}))
        io.open(os.path.join(root, "vault_seen.json"), "w").write(_j.dumps({"rows": []}))
        return root, hist

    def _bind(self, root, hist, floor):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app as ca
        import reel_retention as rr
        for mod, attr, val in ((rr, "HERE", root), (ca, "HERE", root),
                               (ca, "ON_AIR_FLOOR_GB", floor), (ca, "PRUNE_HEADROOM_GB", 0.0)):
            self.addCleanup(setattr, mod, attr, getattr(mod, attr))
            setattr(mod, attr, val)
        old = os.environ.get("TV_HIST")
        os.environ["TV_HIST"] = hist
        self.addCleanup(lambda: os.environ.__setitem__("TV_HIST", old) if old
                        else os.environ.pop("TV_HIST", None))
        return ca

    def _reels(self, hist):
        return len([d for d in _fx_tmp.list_own(hist) if d.startswith("reel_")])

    def test_ABOVE_the_floor_it_still_frees_what_has_GIVEN_UP_ITS_INFORMATION(self):
        """⚠⚠ v2226 REVERSED THIS TEST, ON HIS EXPLICIT RULING, AND THE INTENT IS PRESERVED.

        It used to assert that being above the floor deletes NOTHING, on the reasoning that "the
        floor is the entire justification for acting without him". That reasoning was wrong about
        what he wanted, twice stated: "regardless of room memory it should still be looped and
        extracted and pruned eventually, no need for it to take up space" and "we want an automated
        system auto healing and cleaning itself."

        The old rule did not make anything safer — it made the loop UNFINISHABLE. The reels were
        read, both lanes sealed them, retention marked them eligible and said why per reel, and
        then nothing happened because he had room. Measured at the time: 30.2 GB free, 2 reels /
        122.9 MB eligible, `removed: None`, nothing ever deleted, for weeks.

        WHAT PROTECTS HIM DID NOT CHANGE, and that is what the sibling tests below pin: eligibility
        is still reel_retention's alone, and retention_may_act still refuses on TV_AUTO_PRUNE in any
        spelling, on a board world that is drift/unknown/unreadable, and while a session is in
        flight. The floor stopped being a reason to SKIP; it was never the thing deciding WHAT.
        [[feedback-threshold-above-the-ceiling]] — a gate that can never act is not a safe gate."""
        # ⚠ THE BOARD WORLD MUST BE CONFIRMED, OR THIS TEST ONLY EVER PASSES ON HIS MAC.
        # v2167 made the deleter refuse on anything that is not a CONFIRMED world, and a CI runner
        # has never opened his board — so `board_identity_drift` answers "unknown" and the refusal
        # is CORRECT. Without this mock the test asserts a deletion that must not happen there, and
        # it went red on every CI run from v2200 for over a day while passing locally every time.
        # The sibling BELOW-the-floor case had the mock from the start; this one was written without
        # it. A test that only runs on one machine is a test that runs nowhere.
        # [[feedback-blind-fixture-green-gate]] [[regression-guard]]
        import unittest.mock as mock
        root, hist = self._tree()
        ca = self._bind(root, hist, floor=0.0)
        before = self._reels(hist)
        with mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "same claimed world"}):
            ca._retention_once()
        after = self._reels(hist)
        self.assertLess(after, before,
                        "above the floor nothing was freed, so the extract-then-prune loop still "
                        "cannot complete on merit — which is the state he asked twice to end")

    def test_BELOW_the_floor_with_everything_clear_it_acts_or_this_is_all_theatre(self):
        """The reachability half. A cycle that can never act cannot be shown to refuse correctly.
        [[feedback-blind-fixture-green-gate]]"""
        import unittest.mock as mock
        root, hist = self._tree()
        ca = self._bind(root, hist, floor=9999.0)
        before = self._reels(hist)
        # v2167 — SAY WHICH WORLD. The deleter refuses on anything that is not a CONFIRMED world,
        # and a temp tree has never recorded one, so without this it now refuses for a reason that
        # has nothing to do with what this test is about. The fixture states the precondition it
        # was always silently relying on. [[unknown-stays-unknown]]
        with mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "same claimed world"}):
            ca._retention_once()
        self.assertLess(self._reels(hist), before,
                        "nothing was deleted below the floor with clear ledgers and nothing in "
                        "flight — every refusal case below would then pass vacuously")
        self.assertTrue(retention_freed(ca), "it deleted reels and reported freeing nothing")

    def test_an_unreadable_ledger_stops_it_even_below_the_floor(self):
        root, hist = self._tree()
        ca = self._bind(root, hist, floor=9999.0)
        io.open(os.path.join(root, "vault_swept.json"), "w").write("{ not json")
        before = self._reels(hist)
        ca._retention_once()
        self.assertEqual(self._reels(hist), before,
                         "footage was deleted on the strength of a ledger nothing could open")
        self.assertIn("will not parse", ca.retention_state()["say"])

    def test_it_refuses_while_anything_is_reading_or_writing_footage(self):
        root, hist = self._tree()
        ca = self._bind(root, hist, floor=9999.0)
        for flag, job in (("running", ca._CHRON_JOB), ("running", ca._VAULT_JOB)):
            before = self._reels(hist)
            job[flag] = True
            try:
                ca._retention_once()
                self.assertEqual(self._reels(hist), before,
                                 "it deleted footage while a sweep was reading")
            finally:
                job[flag] = False

    def test_it_can_be_switched_off_and_then_only_reports(self):
        root, hist = self._tree()
        ca = self._bind(root, hist, floor=9999.0)
        os.environ["TV_AUTO_PRUNE"] = "0"
        self.addCleanup(os.environ.pop, "TV_AUTO_PRUNE", None)
        before = self._reels(hist)
        ca._retention_once()
        self.assertEqual(self._reels(hist), before)
        self.assertIn("switched off", ca.retention_state()["say"])

    def test_it_names_what_is_LOCKED_BEHIND_A_SWEEP_which_is_usually_the_real_story(self):
        """On his tree the answer to "why is nothing prunable" was never "the pruner is broken" —
        it was 11 reels nobody had read. If the cycle cannot say that, he is left guessing."""
        import json as _j
        root, hist = self._tree()
        ca = self._bind(root, hist, floor=0.0)
        chron = _j.loads(io.open(os.path.join(root, "chronicle_swept.json"), encoding="utf-8").read())
        gone = sorted(chron)[0]
        del chron[gone]                                  # one reel nobody has ever read
        io.open(os.path.join(root, "chronicle_swept.json"), "w").write(_j.dumps(chron))
        # ⚠ SAME HOST-MACHINE TRAP as the ABOVE-the-floor case. With no confirmed board world the
        # `say` reports "the board's world has never been recorded — open the board once", which is
        # a correct refusal and not the sweep story this test is about. It went red on CI from v2200
        # for over a day and green on his Mac every time, because his board HAS been recorded.
        import unittest.mock as mock
        with mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "same claimed world"}):
            ca._retention_once()
            st = ca.retention_state()
        # v2122 (#142) — AND A SURFACE MUST READ THE SIZE, not only the count. lockedMb has been
        # published all along with nothing consuming it; "11 reel(s) await a sweep" does not tell
        # him whether clearing them would even reach the floor. [[the-unjoined-end]]
        with io.open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as _fh:
            _ui = _fh.read()
        _ui_code = re.sub(r"/\*.{0,4000}?\*/", " ", _ui, flags=re.S)
        self.assertGreater(len(_ui_code), len(_ui) * 0.5, "the comment strip ate the console")
        self.assertIn("_rt.lockedMb", _ui_code,
                      "the footer names how MANY reels await a sweep and never how much they hold")
        self.assertGreaterEqual(st.get("lockedBehindASweep") or 0, 1,
                                "an unread reel was not reported as waiting on a sweep")
        self.assertIn("sweep", st["say"])

    def test_the_floor_travels_on_the_payload_so_two_sides_cannot_disagree(self):
        """v2006's own scar: the first cut compared an UNROUNDED float in python against a ROUNDED
        one on the board, so at exactly 12.0GB python warned and the board did not."""
        root, hist = self._tree()
        ca = self._bind(root, hist, floor=0.0)
        ca._retention_once()
        self.assertEqual(ca.retention_state().get("floorGb"), ca.ON_AIR_FLOOR_GB)

    def test_the_decision_is_separable_from_the_acting(self):
        """A decision buried in a `while True` is a decision nobody can put a case to."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app as ca
        ok, why = ca.retention_may_act()
        self.assertIsInstance(ok, bool)
        self.assertTrue(why)

    def test_it_is_in_the_roster_so_it_starts_in_BOTH_modes(self):
        self.assertTrue(_watcher_is_armed("tvd-retention", "_retention_loop"),
                        "the retention cycle is not armed — the prune half is manual again")

    def test_it_is_published_or_the_deleter_reports_nowhere(self):
        """It acts unattended. The one thing he must be able to see is what it did, or why not."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app as ca
        self.assertIn("retention", ca.status_payload() or {})
        with io.open(os.path.join(os.path.dirname(HERE), "tv", "control_ui.html"),
                     encoding="utf-8") as fh:
            ui = fh.read()
        self.assertIn("st.retention", ui, "nothing on the console reads it")


def retention_freed(ca):
    st = ca.retention_state()
    return bool(st.get("freedMb")) and bool(st.get("removed"))


class TestV2079TheLockedLanesRefuseAndTheTestIsNotVACUOUS(unittest.TestCase):
    """His ruling, plainly: equipment and inventory are NEVER to be told to move. v2075 wrote the
    refusal into vault_retro and nothing tested it.

    ⚠ AND THE OBVIOUS TEST PROVES NOTHING. The throw bar needs THROWOUT_MIN_WITNESSES (4)
    independent recordings. Build a fixture with three and the item is refused by the GATE, so the
    assertion "it was held" passes with the locked-lane branch DELETED. A guard that cannot tell
    which of two refusals fired is measuring neither. So every case here first proves the item
    WOULD have been thrown, and only then locks the lane.
    [[feedback-blind-fixture-green-gate]] [[gate-blind-to-unexercised-input]]"""

    def _vr(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import vault_retro
        return vault_retro

    def _flag(self, vr, name, lane, n=None):
        """n independent recordings, each at full confidence — the evidence a throw needs."""
        n = vr.THROWOUT_MIN_WITNESSES if n is None else n
        return [{"session": "s%d" % i, "frame": "s%d#0" % i, "lane": lane, "conf": 0.99,
                 "why": "junk", "witness": "s%d" % i, "ts": 1500000000000 + i}
                for i in range(n)]

    def test_the_fixture_really_would_be_thrown_or_nothing_below_means_anything(self):
        vr = self._vr()
        v = vr.gate(self._flag(vr, "Cracked Sash", "stash"), vr.THROWOUT_CONF_FLOOR,
                    vr.THROWOUT_MIN_WITNESSES, witness_field="session", witness_noun="recording")
        self.assertTrue(v["pass"],
                        "the fixture does not clear the throw bar (%s), so every 'it was held' "
                        "below would pass with the lane lock removed" % v["why"])

    def test_one_recording_short_would_be_refused_by_the_GATE_not_the_lane(self):
        """The other half of the same point: this is the refusal the lane lock must not be
        confused with."""
        vr = self._vr()
        v = vr.gate(self._flag(vr, "x", "stash", vr.THROWOUT_MIN_WITNESSES - 1),
                    vr.THROWOUT_CONF_FLOOR, vr.THROWOUT_MIN_WITNESSES,
                    witness_field="session", witness_noun="recording")
        self.assertFalse(v["pass"])
        self.assertIn("independent recording", v["why"])

    def test_equipment_and_inventory_are_both_locked(self):
        vr = self._vr()
        self.assertEqual(set(vr.LOCKED_LANES), {"equipment", "inventory"},
                         "a lane he ruled on left the lock, or one was added without his say")

    def test_the_refusal_names_the_LANE_as_the_reason(self):
        """The `why` is what the Vault manager shows him. If it says "not enough recordings" about
        an item on his character, the next ruling will be about a bar that was never the reason."""
        vr = self._vr()
        for lane in vr.LOCKED_LANES:
            v = vr.gate(self._flag(vr, "Cracked Sash", lane), vr.THROWOUT_CONF_FLOOR,
                        vr.THROWOUT_MIN_WITNESSES, witness_field="session",
                        witness_noun="recording")
            self.assertTrue(v["pass"], "the %s fixture must clear the bar first" % lane)
        import inspect
        src = inspect.getsource(vr.plan) if hasattr(vr, "plan") else ""
        if "LOCKED_LANES" not in src:
            src = "".join(inspect.getsource(getattr(vr, n)) for n in dir(vr)
                          if callable(getattr(vr, n, None))
                          and getattr(getattr(vr, n), "__module__", "") == vr.__name__
                          and "LOCKED_LANES" in (inspect.getsource(getattr(vr, n))
                                                 if hasattr(getattr(vr, n), "__code__") else ""))
        self.assertIn("LOCKED lane", src,
                      "nothing in vault_retro refuses a throw on lane grounds")
        self.assertIn("if key[1] in LOCKED_LANES:", src,
                      "the lane check is gone, or moved somewhere the gate runs first")

    def test_the_lane_check_runs_BEFORE_the_evidence_is_weighed(self):
        """Order is the point. If the gate ran first, an item on his character with four recordings
        would be thrown and the lock would only ever catch the ones that were failing anyway."""
        import inspect
        vr = self._vr()
        src = "".join(inspect.getsource(getattr(vr, n)) for n in dir(vr)
                      if hasattr(getattr(vr, n, None), "__code__")
                      and "LOCKED_LANES" in (inspect.getsource(getattr(vr, n)) or ""))
        lane_at = src.index("if key[1] in LOCKED_LANES:")
        gate_at = src.index("THROWOUT_MIN_WITNESSES,\n", lane_at - 4000) if \
            "THROWOUT_MIN_WITNESSES,\n" in src else src.index("THROWOUT_CONF_FLOOR")
        self.assertLess(lane_at, gate_at,
                        "the evidence is weighed before the lane is checked — an item on his "
                        "character can be thrown by having enough witnesses")


class TestV2079TheArtTestsFinallyREADTheBoard(unittest.TestCase):
    """#19. The art guards counted *.png in a directory and checked four gem files existed. Neither
    half ever opened bible.html, so the JOIN — does every picture the board asks for actually
    resolve — was checked by nothing.

    Both halves can be perfectly healthy while the page shows placeholders: the corpus floor is met
    because 1265 files are present, and the four gems are present, and a path the page asks for is
    still absent. [[the-unjoined-end]]"""

    REF = re.compile(r"['\"](art/[A-Za-z0-9_./-]+\.(?:png|jpg|jpeg|webp|svg))['\"]")

    def setUp(self):
        self.repo = os.path.dirname(HERE)
        self.bible = os.path.join(self.repo, "bible.html")
        if not os.path.isfile(self.bible):
            self.skipTest("bible.html is not on this machine")

    def _referenced(self):
        with io.open(self.bible, encoding="utf-8") as fh:
            return sorted(set(self.REF.findall(fh.read())))

    def test_the_board_asks_for_a_lot_of_art_or_this_guard_is_blind(self):
        """A regex that stops matching would report zero missing files forever — the quiet
        direction. [[feedback-suspect-the-instrument]]"""
        self.assertGreater(len(self._referenced()), 800,
                           "only %d art path(s) found in bible.html — the matcher broke, and a "
                           "broken matcher can only ever report success"
                           % len(self._referenced()))

    def test_every_picture_the_board_asks_for_EXISTS(self):
        missing = [r for r in self._referenced()
                   if not os.path.exists(os.path.join(self.repo, r))]
        self.assertEqual(missing, [],
                         "bible.html asks for %d file(s) that are not on disk — the board draws a "
                         "placeholder and every art guard stays green: %s"
                         % (len(missing), ", ".join(missing[:6])))


class TestV2080TheFoldNeverEatsALiveRecording(unittest.TestCase):
    """THE MOST DANGEROUS THING WRITTEN THIS NIGHT, and it was mine.

    A recording in progress IS a pile of loose frames — that is not a race, it is the steady state.
    While he films, every new frame lands directly in hist/ as `f_<ms>.jpg` and only becomes a reel
    at SEAL. That is exactly the population orphan_fold targets. v2080 put the fold behind an
    automatic healer on a ten-minute timer, so armed, it would have moved the frames of the session
    he was filming into a reel and sealed it as finished — unattended, with no undo.

    The cluster boundary cannot tell a finished recording from one still being written: both end at
    "the newest frame I can see". So the rule is TIME."""

    def _of(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import orphan_fold
        return orphan_fold

    def _tree(self, old=10, live=0):
        of = self._of()
        root = tempfile.mkdtemp(prefix="livefold_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        for i in range(old):                      # 2017 stamps — nothing of his is ever near them
            io.open(os.path.join(hist, "f_%d.jpg" % (1500000000000 + i * 1500)), "w").write("x" * 400)
        now = int(time.time() * 1000)
        for i in range(live):
            io.open(os.path.join(hist, "f_%d.jpg" % (now - i * 1500)), "w").write("x" * 400)
        return of, hist

    def _by_age(self, clusters):
        old = [c for c in clusters if c["t0"] < 1600000000000]
        live = [c for c in clusters if c["t0"] >= 1600000000000]
        return old, live

    def test_a_FINISHED_recording_is_still_foldable_or_the_guard_broke_the_feature(self):
        """The reachability half. A fold that refuses everything protects nothing and fixes
        nothing. [[feedback-blind-fixture-green-gate]]"""
        of, hist = self._tree(old=10)
        old, _ = self._by_age(of.plan(hist_dir=hist)["clusters"])
        self.assertTrue(old and old[0]["eligible"],
                        "a recording from 2017 is not foldable — the time guard is refusing "
                        "everything, so the case below would pass for the wrong reason")

    def test_a_recording_STILL_IN_PROGRESS_is_refused(self):
        of, hist = self._tree(old=10, live=10)
        old, live = self._by_age(of.plan(hist_dir=hist)["clusters"])
        self.assertTrue(live, "the live frames did not form their own cluster — fixture is wrong")
        self.assertFalse(live[0]["eligible"],
                         "the fold would seal a session he is still filming")
        self.assertIn("STILL IN PROGRESS", live[0]["why"])
        self.assertTrue(old[0]["eligible"], "and the finished one must still go")

    def test_apply_LEAVES_the_live_frames_exactly_where_they_are(self):
        """The plan refusing is not the same as apply honouring it."""
        of, hist = self._tree(old=10, live=10)
        p = of.plan(hist_dir=hist)
        of.apply_plan(p, yes=True)
        loose = [f for f in _fx_tmp.list_own(hist)
                 if f.endswith(".jpg") and int(f[2:-4]) >= 1600000000000]
        self.assertEqual(len(loose), 10,
                         "apply_plan moved %d live frame(s) out from under the recorder"
                         % (10 - len(loose)))
        reels = [d for d in _fx_tmp.list_own(hist) if d.startswith("reel_")]
        self.assertEqual(len(reels), 1, "the finished recording was not folded")

    def test_the_boundary_is_the_same_gap_that_defines_a_cluster(self):
        """Not a second, independently-tuned constant. A window whose last frame is newer than the
        gap has not been SHOWN to be over, which is exactly what the gap already means.
        [[feedback-threshold-above-the-ceiling]]"""
        import inspect
        of = self._of()
        src = inspect.getsource(of.plan)
        # v2082 — AND A CALLER MAY NOT TUNE IT BELOW THE DEFAULT. The first cut compared against the
        # caller's gap_ms directly, so `--gap-s 0` — which the shipped CLI accepts — made
        # `(now_ms - hi) < 0` unsatisfiable and removed the refusal entirely. A review measured it:
        # six frames of a recording IN PROGRESS became six separate minted session ids, the exact
        # forgery this module exists to prevent. The window a caller may widen is how far apart two
        # clusters must be; it is NOT how recent a recording may be before we call it finished.
        self.assertIn("(now_ms - hi) < max(gap_ms, GAP_MS)", src,
                      "the live-recording boundary is tunable below the cluster gap again")

    def test_a_caller_CANNOT_disable_the_refusal_with_gap_zero(self):
        """The behavioural half — the assertion above only proves an expression is present."""
        of = self._of()
        d = tempfile.mkdtemp(prefix="gapzero_")
        self.addCleanup(shutil.rmtree, d, True)
        hist = os.path.join(d, "hist")
        os.makedirs(hist)
        now = int(time.time() * 1000)
        for i in range(6):                       # a recording happening RIGHT NOW
            io.open(os.path.join(hist, "f_%d.jpg" % (now - i * 1000)), "w").write("x" * 400)
        for gap in (of.GAP_MS, 1500, 0):
            p = of.plan(hist_dir=hist, gap_ms=gap)
            eligible = [c for c in p["clusters"] if c.get("eligible")]
            self.assertEqual(eligible, [],
                             "gap_ms=%d folded a recording in progress into %d reel(s)"
                             % (gap, len(eligible)))

    def test_the_healer_refuses_to_fold_while_anything_is_in_flight(self):
        """Two guards, because this one runs unattended and there is no undo. Anchored on the CALL,
        which cannot appear in a sentence about it. [[source-reading-guard]] 4b"""
        # v2082 — ASK THE COMPILER, NOT THE TEXT. An adversarial review copied console_healer.py to
        # a temp tree, commented the ENTIRE in-flight block out, and ran these two assertions: both
        # still passed, because the comment above the call contains the same words. `co_names`
        # showed the truth — "retention_may_act" was gone.
        #
        # This was the ONLY guard on a remedy that MOVES his footage, unattended, on a ten-minute
        # timer. It was measuring my prose. [[source-reading-guard]] §1
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import console_healer as ch
        names = set(ch._remedy_fold_orphan_footage.__code__.co_names)
        # v2128 (#33) — THE LAW IS "THE FOLD ASKS WHAT IS IN FLIGHT", and only the NAME it asks
        # moved. It used to call retention_may_act, which also carries the DELETER's on/off switch,
        # so TV_AUTO_PRUNE=0 silenced a remedy that deletes nothing. nothing_in_flight() is the
        # same check without the switch.
        self.assertIn("nothing_in_flight", names,
                      "the automatic fold does not REFERENCE the in-flight check — a comment "
                      "mentioning it is not a call")
        self.assertNotIn("retention_may_act", names,
                         "the fold is asking the DELETER's question again, so the documented way "
                         "to stop pruning also stops folding — which deletes nothing")
        # and it must act on the answer, not merely ask
        import inspect
        body = "\n".join(ln for ln in inspect.getsource(ch._remedy_fold_orphan_footage).splitlines()
                          if not ln.lstrip().startswith("#"))
        self.assertIn("if not ok:", body, "it asks and ignores the answer")

    def test_the_fold_REALLY_refuses_while_something_is_in_flight(self):
        """And a behavioural case, because the assertion above can only ever prove a NAME is
        referenced. Nothing anywhere tested that the refusal actually stops the move."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import console_healer as ch
        import control_app as ca
        d = tempfile.mkdtemp(prefix="foldflight_")
        self.addCleanup(shutil.rmtree, d, True)
        hist = os.path.join(d, "hist")
        os.makedirs(hist)
        for i in range(10):                       # 2017 stamps, a finished recording
            io.open(os.path.join(hist, "f_%d.jpg" % (1500000000000 + i * 1500)), "w").write("x" * 400)
        prev_h, prev_a = os.environ.get("TV_HIST"), os.environ.get("TV_AUTO_HEAL")
        os.environ["TV_HIST"] = hist
        os.environ["TV_AUTO_HEAL"] = "1"
        self.addCleanup(lambda: (os.environ.__setitem__("TV_HIST", prev_h) if prev_h
                                 else os.environ.pop("TV_HIST", None),
                                 os.environ.__setitem__("TV_AUTO_HEAL", prev_a) if prev_a
                                 else os.environ.pop("TV_AUTO_HEAL", None)))
        ca._CHRON_JOB["running"] = True
        try:
            did, said = ch._remedy_fold_orphan_footage()
        finally:
            ca._CHRON_JOB["running"] = False
        self.assertIsNot(did, True,
                         "the fold MOVED his footage while a sweep was reading: %s" % said)
        loose = [f for f in _fx_tmp.list_own(hist) if f.endswith(".jpg")]
        self.assertEqual(len(loose), 10, "frames were moved despite the refusal")


class TestV2080TheFixtureHoldIsCheckedWHEREVERTheSuiteRUNS(unittest.TestCase):
    """A SKIP IS NOT A PASS, and the guards this fixes are the ones that stop his footage being
    deleted.

    Three cases about the deleter call `rr.plan()` with no argument and skipTest when his footage is
    absent — so on CI, on the Windows machine, and in any clean checkout, they never run at all. One
    of them says the disease in its own docstring: "The suite did not go red — those cases skipTest
    when the footage is absent — so a real check silently became a permanent skip." It diagnosed
    that and then had it.

    These are the twins. Same questions, asked of a FIXTURE tree, so they run everywhere and go red
    for the subject's reasons on any machine. The his-tree versions stay: they are an extra
    observation about his actual footage, which is a different and also useful thing.
    [[regression-guard]] [[feedback-blind-fixture-green-gate]]"""

    def _tree(self, n=None):
        """⚠ v2876 — SIZED FROM KEEP_RECENT, NOT FROM A LITERAL. Konyo raised the shield
        from 5 to 8; this fixture built exactly 8 reels, so the WHOLE shelf fell inside it
        and eleven laws went red on a correct tree ("8 not less than 8"). A fixture whose
        size is tied to a constant must be DERIVED from it. [[feedback-blind-fixture-green-gate]]
        """
        import reel_retention as _rr_keep
        if n is None:
            n = _rr_keep.KEEP_RECENT + 3
        import json as _j
        root = tempfile.mkdtemp(prefix="fixhold_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        chron = {}
        names = []
        for i in range(n):
            sid = "s_150000000%04d" % i
            d = os.path.join(hist, "reel_" + sid)
            os.makedirs(d)
            io.open(os.path.join(d, "f_%s_0.jpg" % sid), "w").write("x" * 200000)
            chron["reel_" + sid] = {"pages": 9}
            names.append("reel_" + sid)
        io.open(os.path.join(root, "chronicle_swept.json"), "w").write(_j.dumps(chron))
        io.open(os.path.join(root, "vault_swept.json"), "w").write(
            _j.dumps(dict((k, {"rows": 0}) for k in chron)))
        io.open(os.path.join(root, "vault_accum.json"), "w").write(_j.dumps({"owned": []}))
        io.open(os.path.join(root, "vault_seen.json"), "w").write(_j.dumps({"rows": []}))
        return root, hist, names

    def _plan(self, root, hist, fixtures=()):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import frame_authority as fa
        import reel_retention as rr
        self.addCleanup(setattr, rr, "HERE", rr.HERE)
        rr.HERE = root
        old = fa.test_referenced_reels
        self.addCleanup(setattr, fa, "test_referenced_reels", old)
        fa.test_referenced_reels = lambda *a, **k: set(fixtures)
        return rr.plan(hist_dir=hist)

    def test_the_fixture_is_deletable_WITHOUT_the_hold_or_nothing_below_is_proven(self):
        """The sabotage that showed the original guard proved nothing: after a prune his tree had no
        eligible fixture left, so removing the hold changed nothing and every test stayed green."""
        root, hist, names = self._tree()
        p = self._plan(root, hist, fixtures=())
        self.assertIn(names[0], {c["reel"] for c in p["candidates"]},
                      "the oldest reel is not eligible even with no fixture hold — the tree cannot "
                      "demonstrate that the hold does anything")

    def test_a_reel_the_SUITE_opens_is_never_offered_for_deletion(self):
        root, hist, names = self._tree()
        p = self._plan(root, hist, fixtures={names[0]})
        self.assertNotIn(names[0], {c["reel"] for c in p["candidates"]},
                         "a reel the test suite opens by name was offered for deletion — deleting "
                         "it does not turn a test red, it turns one into a permanent skip")

    def test_the_fixture_hold_is_checked_FIRST_so_the_REASON_is_right(self):
        """If `recent` or `eligible` were checked first, a fixture would be held under the wrong
        reason and the coverage line would say the fixture rule never fired.

        ⚠ THE REEL MUST BE BOTH. Marking the OLDEST reel as a fixture cannot test order at all:
        `recent` would not have claimed it either way, so moving the fixture check below `recent`
        changes nothing and the sabotage passes. Proven — that is exactly what happened to the first
        cut of this case. The subject has to be a reel that TWO rules both want.
        [[source-reading-guard]] 4c"""
        root, hist, names = self._tree()
        newest = names[-1]                       # also one of the 5 most recent
        p = self._plan(root, hist, fixtures={newest})
        held = dict((k["reel"], k["why"] or "") for k in p["kept"])
        self.assertIn(newest, held)
        self.assertIn("TEST SUITE", held[newest],
                      "a reel that is BOTH a fixture and recent was held under the wrong reason "
                      "(%s) — the fixture rule now reads as never fired" % held[newest][:60])
        self.assertEqual(p["coverage"]["test-fixture"], 1)
        by_reason = [r for r, w in held.items() if "TEST SUITE" in w]
        self.assertEqual(by_reason, [newest],
                         "the counter and the reasons disagree about which reels were held as "
                         "fixtures: %r" % by_reason)

    def test_every_declared_rule_still_has_a_counter(self):
        """A branch that forgets to call _rule() is invisible to the coverage report."""
        root, hist, names = self._tree()
        p = self._plan(root, hist, fixtures={names[0]})
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import reel_retention as rr
        import inspect
        declared = set(re.findall(r'_rule\(\s*"([a-z-]+)"', inspect.getsource(rr.plan)))
        self.assertTrue(declared)
        self.assertEqual(declared - set(p["coverage"]), set(),
                         "a rule fires and is never counted, so the coverage report cannot say "
                         "whether it ran")


class TestV2080TheLedgerBackupNeverLosesRows(unittest.TestCase):
    """The healer's other remedy REWRITES his ledger. Every case here is about not losing a row.

    The backup exists because a repair needs something to repair FROM and nothing in this tree ever
    wrote one. That makes the bank/restore pair the most data-destructive code in the healer, and
    the failure modes are quiet: overwrite a good backup with a shrunken one and the loss is only
    discovered the day it is needed."""

    def _ch(self, root):
        """v2080 — point TV_SCAR_ROOT, not HERE. The healer resolves every store path through
        _root() so a test can never reach his real files; patching HERE no longer redirects
        anything, which is the whole point of moving the guard to the PATH."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import console_healer
        old = os.environ.get("TV_SCAR_ROOT")
        os.environ["TV_SCAR_ROOT"] = root
        self.addCleanup(lambda: os.environ.__setitem__("TV_SCAR_ROOT", old) if old
                        else os.environ.pop("TV_SCAR_ROOT", None))
        self.addCleanup(setattr, console_healer, "LEDGER", console_healer.LEDGER)
        console_healer.LEDGER = os.path.join(root, ".console_scars.json")
        console_healer._DISARMED.clear()
        return console_healer

    def _root(self):
        d = tempfile.mkdtemp(prefix="bak_")
        self.addCleanup(shutil.rmtree, d, True)
        return d

    def _w(self, root, name, blob):
        import json as _j
        io.open(os.path.join(root, name), "w").write(
            blob if isinstance(blob, str) else _j.dumps(blob))

    def _rows(self, ch, root, name):
        import json as _j
        try:
            with io.open(os.path.join(root, name), encoding="utf-8") as fh:
                return len(ch._rows_of(_j.load(fh)))
        except Exception:
            return None

    def _owned(self, n):
        return {"owned": [{"name": "item-%d" % i} for i in range(n)]}

    def test_a_SHRUNKEN_ledger_never_overwrites_a_larger_backup(self):
        """The moment a backup is most valuable is exactly the moment it is most dangerous to
        replace: the live store has just lost rows."""
        root = self._root()
        ch = self._ch(root)
        self._w(root, "vault_accum.json", self._owned(3))
        ch.back_up_healthy_stores()
        self._w(root, "vault_accum.json", self._owned(1))
        ch.back_up_healthy_stores()
        self.assertEqual(self._rows(ch, root, "vault_accum.json.healer_bak"), 3,
                         "a shrunken ledger overwrote the backup — the rows are gone from both")

    def test_a_GROWN_ledger_does_move_the_backup_up(self):
        """The reachability half: a bank that never updates is a backup frozen at row one."""
        root = self._root()
        ch = self._ch(root)
        self._w(root, "vault_accum.json", self._owned(3))
        ch.back_up_healthy_stores()
        self._w(root, "vault_accum.json", self._owned(5))
        ch.back_up_healthy_stores()
        self.assertEqual(self._rows(ch, root, "vault_accum.json.healer_bak"), 5)

    def test_a_CORRUPT_store_is_never_banked_over_a_good_backup(self):
        root = self._root()
        ch = self._ch(root)
        self._w(root, "vault_swept.json", {"rows": [1, 2, 3]})
        ch.back_up_healthy_stores()
        self._w(root, "vault_swept.json", "}{ garbage")
        ch.back_up_healthy_stores()
        self.assertEqual(self._rows(ch, root, "vault_swept.json.healer_bak"), 3,
                         "garbage was banked as a backup")

    def test_a_restore_KEEPS_the_corrupt_bytes(self):
        """Nothing of his is thrown away to make a check go green."""
        root = self._root()
        ch = self._ch(root)
        self._w(root, "vault_accum.json", self._owned(4))
        ch.back_up_healthy_stores()
        self._w(root, "vault_accum.json", "}{ garbage")
        did, said = ch._remedy_restore_a_vault_store()
        self.assertTrue(did, said)
        self.assertEqual(self._rows(ch, root, "vault_accum.json"), 4)
        self.assertTrue(os.path.exists(os.path.join(root, "vault_accum.json.corrupt")),
                        "the corrupt copy was destroyed rather than kept")

    def test_a_restore_SAYS_how_old_the_bytes_are(self):
        """A backup is only refreshed when the live store parses and has not shrunk, so it can be
        days behind. Reporting a row count alone reads as "recovered" when it may be "recovered to
        last Tuesday". [[stale-reading]]"""
        root = self._root()
        ch = self._ch(root)
        self._w(root, "vault_accum.json", self._owned(4))
        ch.back_up_healthy_stores()
        self._w(root, "vault_accum.json", "}{ garbage")
        _did, said = ch._remedy_restore_a_vault_store()
        self.assertRegex(said, r"(minute|hour)\(s\) old|age UNKNOWN",
                         "the restore does not say how old the backup was: %r" % said)

    def test_with_NO_healthy_backup_it_refuses_and_changes_nothing(self):
        root = self._root()
        ch = self._ch(root)
        self._w(root, "vault_seen.json", {"rows": [{"name": "a"}]})
        ch.back_up_healthy_stores()
        self._w(root, "vault_seen.json", "}{ garbage")
        self._w(root, "vault_seen.json.healer_bak", "}{ also garbage")
        before = io.open(os.path.join(root, "vault_seen.json"), encoding="utf-8").read()
        did, _said = ch._remedy_restore_a_vault_store()
        self.assertFalse(did)
        self.assertEqual(io.open(os.path.join(root, "vault_seen.json"), encoding="utf-8").read(),
                         before, "it touched the live store with nothing to restore from")


class TestV2080TheReviewFindings(unittest.TestCase):
    """Eight defects an independent review reproduced in the v2079 bytes. Six were mine, all were
    real, and three of them shipped. Each case here is the reviewer's own input."""

    def _mods(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import console_healer, frame_authority, reel_retention
        return frame_authority, reel_retention, console_healer

    # ── 1 ────────────────────────────────────────────────────────────────────────────────────
    def _fa_tree(self, durable=True):
        import json as _j
        root = tempfile.mkdtemp(prefix="fa_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        # ⚠ v2876 — derived from the shield, not 7. See the _REELS note in
        # TestV2062OneDeletionAuthority: a fixture sized against a constant must move with it.
        import reel_retention as _rr_keep
        for i in range(_rr_keep.KEEP_RECENT + 2):
            sid = "s_17000000000%02d_1" % i
            d = os.path.join(hist, "reel_" + sid)
            os.makedirs(d)
            io.open(os.path.join(d, "f_%s_0.jpg" % sid), "w").write("x" * 4000)
        io.open(os.path.join(root, "vault_swept.json"), "w").write(
            _j.dumps({"s_1700000000000_1": {"rows": 7, "extracted": ["name", "location", "provenance"]}}))
        if durable:
            io.open(os.path.join(root, "vault_accum.json"), "w").write(_j.dumps({"owned": []}))
            io.open(os.path.join(root, "vault_seen.json"), "w").write(_j.dumps({"rows": []}))
        return root, hist

    def test_1_with_NO_durable_store_the_frame_deleter_holds_everything(self):
        """v2079 released a frame v2077 held. Splitting absent from unreadable made `ok` True on a
        tree with no durable store — a complete picture of nothing — so every frame read as
        "witnessed nothing", which for this module means DELETABLE. Measured on the reviewer's
        input: v2077 kept 7, v2079 pruned 1, and reel_retention HELD the same reel throughout.
        Two deletion authorities, opposite answers, same footage."""
        fa, _rr, _ch = self._mods()
        root, hist = self._fa_tree(durable=False)
        p = fa.plan_frames(hist, root=root)
        self.assertEqual(len(p["prunable"]), 0,
                         "frames were offered for deletion with no durable store in existence — "
                         "nothing there can prove a frame IS a witness, and unprovable is not no")
        self.assertFalse(p["haveIndex"])

    def test_1b_with_a_durable_store_present_it_can_still_prune_or_the_guard_is_a_wall(self):
        fa, _rr, _ch = self._mods()
        root, hist = self._fa_tree(durable=True)
        p = fa.plan_frames(hist, root=root)
        self.assertTrue(p["haveIndex"])
        self.assertGreater(len(p["prunable"]), 0,
                           "nothing is prunable even with a healthy empty index — the hold has "
                           "become unconditional and the case above proves nothing")

    def test_1c_the_two_deleters_agree_about_that_reel(self):
        fa, rr, _ch = self._mods()
        root, hist = self._fa_tree(durable=False)
        self.addCleanup(setattr, rr, "HERE", rr.HERE)
        rr.HERE = root
        offered = {c["reel"] for c in rr.plan(hist_dir=hist)["candidates"]}
        frames = {os.path.basename(os.path.dirname(f)) for f in
                  (fa.plan_frames(hist, root=root)["prunable"] or [])}
        # v2082 — THE INTERSECTION COULD NOT FAIL IN EITHER DIRECTION. On this fixture both sides
        # are empty, and `frames` is guaranteed empty by the case one method above — so `offered &
        # frames` stays empty however wrong `offered` becomes. A review restored exact v2079
        # behaviour (haveIndex forced True): the disagreement this case is NAMED for appeared —
        # reel deleter offered nothing, frame deleter offered reel_s_1700000000000_1 — and it
        # still passed.
        #
        # The real property is DIRECTIONAL: a reel the REEL deleter holds must not have frames the
        # FRAME deleter offers. That is the contradiction; an intersection of two empties is not.
        self.assertEqual(frames - offered, set(),
                         "the FRAME deleter offers frames from %s, which the REEL deleter is "
                         "holding — two authorities, opposite answers, same footage"
                         % sorted(frames - offered))

    # ── 4 ────────────────────────────────────────────────────────────────────────────────────
    def _rr_tree(self):
        import json as _j
        root = tempfile.mkdtemp(prefix="say_")
        self.addCleanup(shutil.rmtree, root, True)
        hist = os.path.join(root, "hist")
        os.makedirs(hist)
        chron = {}
        # ⚠ v2876 — derived from the shield, not 6. See the _REELS note above.
        import reel_retention as _rr_keep
        for i in range(_rr_keep.KEEP_RECENT + 2):
            sid = "s_150000000%04d" % i
            d = os.path.join(hist, "reel_" + sid)
            os.makedirs(d)
            io.open(os.path.join(d, "f_%s_0.jpg" % sid), "w").write("x" * 3000)
            chron["reel_" + sid] = {"pages": 9}
        io.open(os.path.join(root, "chronicle_swept.json"), "w").write(_j.dumps(chron))
        io.open(os.path.join(root, "vault_accum.json"), "w").write(_j.dumps({"owned": []}))
        io.open(os.path.join(root, "vault_seen.json"), "w").write(_j.dumps({"rows": []}))
        return root, hist

    def test_4_a_CORRUPT_ledger_is_never_described_as_an_absent_one(self):
        """`say` branched on bool(vault), falsy for both. The sweep consumer copies ONLY `say` onto
        his console, so the true `unreadable` field never reached a screen and the most alarming
        state was described as the most innocent one."""
        _fa, rr, _ch = self._mods()
        root, hist = self._rr_tree()
        self.addCleanup(setattr, rr, "HERE", rr.HERE)
        rr.HERE = root
        io.open(os.path.join(root, "vault_swept.json"), "w").write("{ half a flush")
        p = rr.plan(hist_dir=hist)
        self.assertEqual(p["unreadable"], ["vault_swept.json"])
        self.assertNotIn("does not exist", p["say"],
                         "a ledger that will not parse was reported as one that was never written")
        self.assertIn("NOT PARSE", p["say"])

    def test_4b_an_ABSENT_ledger_is_still_described_as_absent(self):
        _fa, rr, _ch = self._mods()
        root, hist = self._rr_tree()
        self.addCleanup(setattr, rr, "HERE", rr.HERE)
        rr.HERE = root
        p = rr.plan(hist_dir=hist)
        self.assertEqual(p["unreadable"], [])
        self.assertIn("does not exist", p["say"])

    # ── 5 ────────────────────────────────────────────────────────────────────────────────────
    def _iso(self):
        _fa, _rr, ch = self._mods()
        d = tempfile.mkdtemp(prefix="wipe_")
        self.addCleanup(shutil.rmtree, d, True)
        prev = os.environ.get("TV_SCAR_ROOT")
        os.environ["TV_SCAR_ROOT"] = d
        self.addCleanup(lambda: os.environ.__setitem__("TV_SCAR_ROOT", prev) if prev
                        else os.environ.pop("TV_SCAR_ROOT", None))
        self.addCleanup(setattr, ch, "LEDGER", ch.LEDGER)
        ch.LEDGER = os.path.join(d, ".console_scars.json")
        ch._DISARMED.clear()
        return ch

    def test_5_a_corrupt_scar_ledger_is_KEPT_not_overwritten(self):
        """The same absent-vs-unparsable collapse this commit fixed in two other modules, made in
        its own store. One stray byte erased every firstSeen, every returns count — and every
        heal.disarmed flag, which made ledger corruption the only thing that can RE-ARM a remedy
        LAW 2 disarmed for lying."""
        ch = self._iso()
        red = [{"check": "visual lock", "state": "missing", "why": "drifted"}]
        ch.record(red, now_ms=1000)
        with io.open(ch.LEDGER, "a", encoding="utf-8") as fh:
            fh.write("!")
        ch.record(red, now_ms=2000)
        kept = [f for f in _fx_tmp.list_own(os.path.dirname(ch.LEDGER)) if ".corrupt" in f]
        self.assertTrue(kept, "the unreadable ledger was overwritten instead of being kept")

    def test_5b_a_second_corruption_does_not_overwrite_the_first(self):
        ch = self._iso()
        red = [{"check": "visual lock", "state": "missing", "why": "drifted"}]
        for i in range(3):
            ch.record(red, now_ms=1000 + i)
            with io.open(ch.LEDGER, "a", encoding="utf-8") as fh:
                fh.write("!")
        ch.record(red, now_ms=9000)
        kept = [f for f in _fx_tmp.list_own(os.path.dirname(ch.LEDGER)) if ".corrupt" in f]
        self.assertGreaterEqual(len(kept), 2,
                                "each corruption overwrote the last — only %d copy kept" % len(kept))

    # ── 6 ────────────────────────────────────────────────────────────────────────────────────
    def test_6_a_DESIGNED_refusal_is_not_a_failure_and_never_disarms(self):
        """orphan_fold answering "every cluster overlaps an existing reel" is the CORRECT answer.
        Treating it as a failed heal disarmed the remedy — and the disarm is written to the ledger,
        which nothing anywhere sets back to False. A remedy could be retired forever by working."""
        ch = self._iso()
        os.environ["TV_AUTO_HEAL"] = "1"
        self.addCleanup(os.environ.pop, "TV_AUTO_HEAL", None)
        old = ch.REMEDIES["footage has a reel"]
        self.addCleanup(ch.REMEDIES.__setitem__, "footage has a reel", old)
        ch.REMEDIES["footage has a reel"] = ("test double", lambda: (None, "nothing eligible"))
        scar = ch.record([{"check": "footage has a reel", "state": "missing", "why": "x"}])[0]
        state, _said = ch.heal(scar, recheck=lambda: ("missing", "still"))
        self.assertEqual(state, "nothing-to-do")
        after = ch.history(scar["key"])
        self.assertFalse((after.get("heal") or {}).get("disarmed"),
                         "a remedy was permanently disarmed for correctly having nothing to do")

    def test_6b_a_remedy_that_LIES_is_still_disarmed(self):
        """The mirror — LAW 2 must survive the fix above."""
        ch = self._iso()
        os.environ["TV_AUTO_HEAL"] = "1"
        self.addCleanup(os.environ.pop, "TV_AUTO_HEAL", None)
        old = ch.REMEDIES["footage has a reel"]
        self.addCleanup(ch.REMEDIES.__setitem__, "footage has a reel", old)
        ch.REMEDIES["footage has a reel"] = ("test double", lambda: (True, "pretended"))
        scar = ch.record([{"check": "footage has a reel", "state": "missing", "why": "x"}])[0]
        self.assertEqual(ch.heal(scar, recheck=lambda: ("missing", "still"))[0], "still-red")
        self.assertEqual(ch.heal(scar, recheck=lambda: ("missing", "still"))[0], "disarmed")

    # ── 8 ────────────────────────────────────────────────────────────────────────────────────
    def test_8_what_the_restore_PROMISES_is_what_the_restore_DOES(self):
        """The reviewer's point was that the docstring and the contract string shown to him both
        claimed a row comparison this function never made.

        My first correction ADDED the comparison — and a sabotage proved it unreachable: a store
        that parses is skipped before it, and one that does not parse has no countable rows. A
        branch that cannot execute is a guard-shaped comment, so the promise moved to where the code
        actually is. This pins that they cannot drift apart again.
        [[feedback-threshold-above-the-ceiling]]"""
        import inspect
        _fa, _rr, ch = self._mods()
        contract = ch.REMEDIES["vault stores"][0]
        doc = inspect.getdoc(ch._remedy_restore_a_vault_store) or ""
        body = inspect.getsource(ch._remedy_restore_a_vault_store)
        body = "\n".join(ln for ln in body.splitlines() if not ln.lstrip().startswith("#"))
        claims_rows = "as many rows" in contract or "as many rows" in doc.split("The row")[0]
        does_rows = "live_rows" in body
        self.assertEqual(claims_rows, does_rows,
                         "the restore %s a row comparison and %s one"
                         % ("claims" if claims_rows else "does not claim",
                            "makes" if does_rows else "does not make"))
        # and the protection it DOES rely on must still exist where it says it does
        bank = inspect.getsource(ch.back_up_healthy_stores)
        self.assertIn("_rows_of(json.load(fh))) > len(_rows_of(blob))", bank,
                      "the shrink guard the restore's docstring points at is gone")

    def test_8b_a_second_corrupt_copy_does_not_overwrite_the_first(self):
        import json as _j
        ch = self._iso()
        root = os.path.dirname(ch.LEDGER)
        fp = os.path.join(root, "vault_seen.json")
        for _ in range(2):
            io.open(fp, "w").write(_j.dumps({"rows": [{"name": "a"}, {"name": "b"}]}))
            ch.back_up_healthy_stores()
            io.open(fp, "w").write("}{ garbage")
            ch._remedy_restore_a_vault_store()
        kept = [f for f in _fx_tmp.list_own(root) if f.startswith("vault_seen.json.corrupt")]
        self.assertGreaterEqual(len(kept), 2,
                                "the second corruption overwrote the first under a message saying "
                                "it was KEPT — only %d copy survived" % len(kept))


class TestV2080TheHarnessDoesNotRunTheACTINGWatchers(unittest.TestCase):
    """A full gate run left FIVE files moved under tv/ with his console down, and the tree's own
    byte-identical canary caught it. Two of them are runtime records of DECISIONS —
    .console_scars.json (which faults have come back) and reel_tombstones.json (which reels a
    deleter removed) — and neither is a file a test may write.

    Three fixes, at three depths:
      · the scar ledger resolves through _root(), so its PATH cannot reach his tree from a fixture
      · the tombstone path resolves at CALL time, because a constant bound at import is a fixture
        guard with a race built in — `rr.HERE = root` came too late and 89 fixture tombstones
        landed in his real file
      · and this: a console a HARNESS spawned does not run the acting watchers at all"""

    def _ca(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app
        return control_app

    def test_the_ACTING_watchers_stand_down_under_TV_STUB(self):
        """They are the ones that DECIDE something about his world: what is out of sync, whether to
        relaunch, what to delete, and — since v2369 — which reels are worth paying to read. A
        fixture world has nothing to be out of sync with.

        ⚠ v2369 ADDED THE FOURTH, AND IT WAS THE WORST OFFENDER OF THE SET. tvd-retro-triage
        shipped in v2367 without being listed here. HIST_DIR honours TV_HIST, so under a harness
        it surveyed FIXTURE reels — while retro_triage's store path did NOT, so those verdicts
        were written into his real tv/retro_triage.json. Found there afterwards: reel_s_2_2 and
        reel_s_3_0, fixture names straight out of this file. A gate run was teaching the live
        store that his reels hold no panels, which is exactly the reading that stops one being
        read again. Both halves are closed — the watcher stands down, and the store follows
        TV_HIST — and the two fixture rows were purged.
        [[feedback-fixtures-never-touch-live-data]]"""
        prev = os.environ.get("TV_STUB")
        os.environ["TV_STUB"] = "1"
        self.addCleanup(lambda: os.environ.__setitem__("TV_STUB", prev) if prev
                        else os.environ.pop("TV_STUB", None))
        with inert_roster() as start:
            r = start("harness-test")
        self.assertEqual(set(r["stoodDown"]),
                         {"tvd-eagle-watch", "tvd-version-drift", "tvd-retention",
                          "tvd-retro-triage", "tvd-orphan-fold", "tvd-river-warm", "tvd-disk-sign"})
        # #151 - the disk sign's lane walks his Grok folder and his reels: a harness reads no live folder of his
        # REG-2463 (#168, M4) - the orphan-fold lane MOVES his loose frames, so it is an acting watcher too.
        for name in r["stoodDown"]:
            self.assertNotIn(name, r["started"])

    def test_the_OBSERVING_watchers_still_run_in_a_harness(self):
        """The mirror. Standing down everything would make the harness a different program from the
        one it is testing, which is its own defect."""
        prev = os.environ.get("TV_STUB")
        os.environ["TV_STUB"] = "1"
        self.addCleanup(lambda: os.environ.__setitem__("TV_STUB", prev) if prev
                        else os.environ.pop("TV_STUB", None))
        with inert_roster() as start:
            r = start("harness-test")
        for name in ("tvd-chron-autoread", "tvd-rolling-prune", "tvd-ledger-backup",
                     "tvd-space-warden", "tvd-stash-watch"):
            # ⚠ ASK THE ROSTER, NOT `started`. The arming loop skips any watcher whose thread
            # is ALREADY LIVE (`if name in live: continue`), so a watcher a previous test in
            # this class started is in NEITHER list — and this read as "it is not in the
            # roster". That made the case depend on unittest's alphabetical ordering: it
            # passed only while it happened to run BEFORE the stand-down case. Renaming that
            # case from `test_the_three_ACTING...` to `test_the_ACTING...` in v2369 moved it
            # ahead of this one and turned this red, with nothing wrong in either test.
            # `roster` is what the question was always about and it does not move.
            self.assertIn(name, r.get("roster") or [])
            self.assertNotIn(name, r["stoodDown"])

    def test_without_TV_STUB_every_watcher_runs(self):
        prev = os.environ.pop("TV_STUB", None)
        self.addCleanup(lambda: os.environ.__setitem__("TV_STUB", prev) if prev else None)
        with inert_roster() as start:
            r = start("normal-test")
        self.assertEqual(r["stoodDown"], [],
                         "watchers stood down on a real console: %r" % r["stoodDown"])

    def test_standing_down_is_SAID_not_silent(self):
        """"it did not run" and "it is not there" must never look the same."""
        import inspect
        src = inspect.getsource(self._ca().start_background_watchers)
        self.assertIn("stood down", src)
        self.assertIn('"stoodDown": stood_down', src,
                      "the payload does not carry which watchers were skipped")

    def test_the_tombstone_path_resolves_at_CALL_time(self):
        """A constant computed at import is a fixture guard with a race built into it: it is only as
        good as the moment it was evaluated. 89 fixture tombstones proved it."""
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import reel_retention as rr
        d = tempfile.mkdtemp(prefix="tomb_")
        self.addCleanup(shutil.rmtree, d, True)
        hist = os.path.join(d, "hist")
        os.makedirs(hist)
        prev = os.environ.get("TV_HIST")
        os.environ["TV_HIST"] = hist
        self.addCleanup(lambda: os.environ.__setitem__("TV_HIST", prev) if prev
                        else os.environ.pop("TV_HIST", None))
        got = rr._tombstone_path()
        self.assertTrue(got.startswith(os.path.realpath(d)),
                        "a fixture world still writes tombstones to %s" % got)
        self.assertNotIn("d2r_bible_tests/tv/reel_tombstones.json", got)


class TestV2082TheReviewOfV2080(unittest.TestCase):
    """Seven findings an independent review reproduced in the v2080 bytes. These three had NO guard
    at all — I fixed the behaviour and wrote no test, and a sabotage sweep proved it by leaving all
    three green with the fixes reverted."""

    def _ca(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app
        return control_app

    def _ch(self, root=None):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import console_healer
        if root:
            prev = os.environ.get("TV_SCAR_ROOT")
            os.environ["TV_SCAR_ROOT"] = root
            self.addCleanup(lambda: os.environ.__setitem__("TV_SCAR_ROOT", prev) if prev
                            else os.environ.pop("TV_SCAR_ROOT", None))
            self.addCleanup(setattr, console_healer, "LEDGER", console_healer.LEDGER)
            console_healer.LEDGER = os.path.join(root, ".console_scars.json")
        console_healer._DISARMED.clear()
        return console_healer

    # ── 1 ────────────────────────────────────────────────────────────────────────────────────
    def test_1_EVERY_spelling_of_off_switches_the_deleter_off(self):
        """It matched the exact byte "0" and nothing else, so `off`, `false`, `no`, `OFF` — and "0"
        with a trailing space — all ARMED an unattended, irreversible deleter. Measured by the
        review on six fixture reels: "0" held all six, every other spelling deleted.

        Its two siblings in this file are opt-IN (`!= "1"`), so this one alone failed OPEN, on the
        one thing in the tree with no undo. A typo is not permission."""
        ca = self._ca()
        prev = os.environ.get("TV_AUTO_PRUNE")
        self.addCleanup(lambda: os.environ.__setitem__("TV_AUTO_PRUNE", prev) if prev
                        else os.environ.pop("TV_AUTO_PRUNE", None))
        for spelling in ("0", "off", "OFF", "Off", "false", "False", "no", "NO", " 0 ", "off "):
            os.environ["TV_AUTO_PRUNE"] = spelling
            ok, why = ca.retention_may_act()
            self.assertFalse(ok, "TV_AUTO_PRUNE=%r left the deleter ARMED" % spelling)
            self.assertIn("switched off", why)

    def test_1b_it_is_still_ARMED_when_he_has_not_switched_it_off(self):
        """The mirror — he asked for this to be automatic. A guard that turns it off for every
        value would deliver the opposite of what he asked for and read as safety."""
        ca = self._ca()
        prev = os.environ.get("TV_AUTO_PRUNE")
        self.addCleanup(lambda: os.environ.__setitem__("TV_AUTO_PRUNE", prev) if prev
                        else os.environ.pop("TV_AUTO_PRUNE", None))
        # v2167 — this test is about the SWITCH, so the world and the busy check are held clear.
        # Otherwise an unconfirmed world (a test machine has none) refuses first and the switch is
        # never actually exercised — the assertion would pass or fail for the wrong reason.
        import unittest.mock as mock
        with mock.patch.object(ca, "board_identity_drift",
                               lambda: {"state": "ok", "why": "same claimed world"}), \
             mock.patch.object(ca, "nothing_in_flight", lambda *a, **k: (True, "clear")):
            for spelling in ("1", "yes", "on", "true", ""):
                os.environ["TV_AUTO_PRUNE"] = spelling
                ok, _why = ca.retention_may_act()
                self.assertTrue(ok, "TV_AUTO_PRUNE=%r disarmed it — he asked for automatic"
                                % spelling)
            os.environ.pop("TV_AUTO_PRUNE", None)
            self.assertTrue(ca.retention_may_act()[0], "unset disarmed it")

    def test_1c_the_off_switch_is_read_the_same_way_as_its_siblings(self):
        """Three env switches decide whether something acts on his world. Two are opt-in and one is
        opt-out; that asymmetry is deliberate (he asked for auto-prune ON) — but the PARSING must
        not differ, or the odd one out is the one that fails open."""
        import inspect
        ca = self._ca()
        # REG-1879 — the parse lives in _auto_prune_switch (the drain and the lane census read it too); the act asks it
        src = inspect.getsource(ca._auto_prune_switch)
        self.assertIn(".strip().lower()", src,
                      "the kill switch compares a raw env string again — whitespace and case decide "
                      "whether his footage is deleted")
        self.assertIn("_auto_prune_switch()", inspect.getsource(ca.retention_may_act),
                      "retention_may_act no longer asks the switch's one parse")

    # ── 2 ────────────────────────────────────────────────────────────────────────────────────
    def test_2_an_UNKNOWN_reading_never_clears_a_scar(self):
        """`measured` was every check in the reading and `red_checks` only the missing ones, so a
        check that came back UNKNOWN was "measured and not red" and its scar was stamped CLEARED —
        manufacturing the same false RETURN v2080 was written to stop, through another door.

        Everyday triggers, all in the CHEAP subset the eagle runs every ten minutes: `board is
        claimed` is UNKNOWN whenever the board window is not open; `version drift` when the console
        does not answer in 4s; `art corpus` on a machine with no art dir. Close the board, reopen
        it, and the ledger reports a regression that never happened."""
        d = tempfile.mkdtemp(prefix="unk_")
        self.addCleanup(shutil.rmtree, d, True)
        ch = self._ch(d)
        RED = [{"check": "disk headroom", "state": "missing", "why": "7.9GB free"}]
        UNK = [{"check": "disk headroom", "state": "unknown", "why": "console not answering"}]
        ch.record(RED, now_ms=1000)
        ch.record(UNK, now_ms=2000)
        out = ch.record(RED, now_ms=3000)
        self.assertEqual(out[0]["returns"], 0,
                         "an UNKNOWN reading cleared a live scar, so the next sighting was "
                         "announced as a RETURN that never happened")
        self.assertNotIn("COME BACK", ch.says(out[0]))

    def test_2b_an_OK_reading_still_clears(self):
        """The mirror: if nothing clears, nothing can ever be named a return either."""
        d = tempfile.mkdtemp(prefix="unk2_")
        self.addCleanup(shutil.rmtree, d, True)
        ch = self._ch(d)
        RED = [{"check": "disk headroom", "state": "missing", "why": "7.9GB free"}]
        OK = [{"check": "disk headroom", "state": "ok", "why": "plenty"}]
        ch.record(RED, now_ms=1000)
        ch.record(OK, now_ms=2000)
        self.assertEqual(ch.record(RED, now_ms=3000)[0]["returns"], 1,
                         "a genuine clear-and-return stopped being counted")

    # ── 6 ────────────────────────────────────────────────────────────────────────────────────
    def test_6_valid_JSON_that_is_not_a_ledger_is_KEPT_not_wiped(self):
        """`_LEDGER_UNREADABLE = False` was set BEFORE the isinstance test, so a file holding a
        valid JSON list read as healthy-and-empty: no .corrupt kept, and every firstSeen, returns
        count and heal.disarmed silently gone — including the one flag this module names as the
        only thing that can re-arm a remedy disarmed for lying. One line from the defect the same
        commit closed."""
        import json as _j
        d = tempfile.mkdtemp(prefix="nondict_")
        self.addCleanup(shutil.rmtree, d, True)
        ch = self._ch(d)
        RED = [{"check": "visual lock", "state": "missing", "why": "drifted"}]
        ch.record(RED, now_ms=1000)
        for payload in ('["a valid JSON list"]', '"a valid JSON string"', '42', 'null'):
            io.open(ch.LEDGER, "w", encoding="utf-8").write(payload)
            ch.record(RED, now_ms=2000)
            kept = [f for f in _fx_tmp.list_own(d) if ".corrupt" in f]
            self.assertTrue(kept, "a ledger holding %s was overwritten, not kept" % payload)
            for f in kept:
                os.remove(os.path.join(d, f))

    def test_6b_a_HEALTHY_ledger_is_never_set_aside(self):
        """The mirror: treating every load as suspect would litter his tree with .corrupt copies of
        perfectly good ledgers."""
        d = tempfile.mkdtemp(prefix="nondict2_")
        self.addCleanup(shutil.rmtree, d, True)
        ch = self._ch(d)
        RED = [{"check": "visual lock", "state": "missing", "why": "drifted"}]
        for i in range(4):
            ch.record(RED, now_ms=1000 + i)
        self.assertEqual([f for f in _fx_tmp.list_own(d) if ".corrupt" in f], [],
                         "a healthy ledger was set aside as corrupt")


class TestV2082SixteenUniquesTheVaultRefusedToHold(unittest.TestCase):
    """The page held TWO answers to "which uniques exist" and the vault consulted the other one.

    MEASURED on a real render: seed d2r_owned, give each the mule id suggestMule() itself returns,
    reload — 0 of 10 survive, and none reach the found ledger either. Harlequin Crest. Hellfire
    Torch. Bul-Kathos' Wedding Band.

    THE ROSTER is ITEM_VALUE (505 keys) union _UNI_EXTRA minus set pieces, matched by _norm().
    THE ACCEPT-LIST tested ITEM_REGISTRY (547 keys) — a different object. Sixteen roster names are
    true in the first and false in the second.

    It is a REBUILD, not a delete, which is why hooking Set.prototype.delete caught nothing."""

    def setUp(self):
        self.repo = os.path.dirname(HERE)
        self.bible = os.path.join(self.repo, "bible.html")
        if not os.path.isfile(self.bible):
            self.skipTest("bible.html is not on this machine")
        with io.open(self.bible, encoding="utf-8") as fh:
            self.s = fh.read()

    def test_the_accept_list_asks_the_ROSTER_not_a_second_catalogue(self):
        """One source of truth. A longer hand-list would drift again the moment either side moved."""
        i = self.s.index("owned = new Set([...owned].filter(")
        line = self.s[i:self.s.index("\n", i)]
        self.assertIn("_ROSTER_NORM[_norm(n)]", line,
                      "the vault decides what a unique is without asking the roster the rest of "
                      "the page trusts")

    def test_the_roster_set_is_built_from_the_roster_and_fails_CLOSED(self):
        """An unreachable roster must admit nothing EXTRA — never fewer names than before, and
        never a crash on a page where _gUniqueRoster has not been defined yet."""
        i = self.s.index("var _ROSTER_NORM =")
        blk = self.s[i:self.s.index("owned = new Set(", i)]
        self.assertIn("window._gUniqueRoster", blk)
        self.assertIn("catch", blk, "an unreachable roster would throw during load")
        # ⚠ `Object.create(null)` also appears in this block's CATCH branch, so asserting the bare
        # string passes with the assignment sabotaged — proven. Anchor on the ASSIGNMENT.
        # [[source-reading-guard]] §4b
        self.assertIn("var out = Object.create(null);", blk,
                      "a plain {} inherits Object.prototype, so _ROSTER_NORM['constructor'] is "
                      "truthy and any item named 'constructor' or 'toString' would be admitted "
                      "into his physical vault by accident")
        self.assertIn("catch(e){ return Object.create(null); }", blk,
                      "an unreachable roster must admit nothing EXTRA, never fewer names")

    def test_the_warning_no_longer_asserts_a_cause_it_cannot_know(self):
        """It said "items renamed/removed in a data update". For sixteen names that was the wrong
        cause — they are current items the roster actively offers — and the wrong cause is why this
        survived: it read as housekeeping. [[label-outlived-referent]]"""
        # ⚠ The old wording survives in the COMMENT that explains its removal, and the new wording
        # is SPLIT across a string concatenation ('...that no ' + 'catalogue on this page...'), so
        # neither phrase can be matched whole. Anchor on the live console.warn CALL and on a
        # contiguous fragment. A guard that greps prose fails for its own reasons.
        # [[source-reading-guard]] §4
        i = self.s.index("console.warn('[bible] dropped '")
        call = self.s[i:self.s.index(");", i)]
        self.assertNotIn("renamed/removed", call,
                         "the live warning still blames a data update for a catalogue disagreement")
        self.assertIn("catalogue on this page recognises", call)

    def test_set_pieces_are_still_excluded(self):
        """The roster excludes them by construction (_pieces()), and they have their own store.
        Admitting them here would put 127 set pieces into the physical vault."""
        # TestTheSourceGuardsDoNotGetMoreDangerous caught a fixed 1400-char window here — the
        # repo enforcing its own rule on me. A byte count is a guess about someone's prose; bound
        # by the real end of the function. [[source-reading-guard]] §3
        blk = _between(self, self.s, "function _roster()", "function _pieces()",
                       what="the roster builder")
        self.assertIn("var pc = _pieces();", blk)
        # ⚠ v2680 — THIS ASSERTED A LITERAL AND THE LITERAL MOVED, WHILE THE LAW HELD.
        # It required `if (pc[k]) return;`. v2680 added a second chronicle exclusion (the six
        # Latent sunder twins) and folded both into one predicate, so the line became
        # `if (_chronicleSkip(k)) return;` with `_chronicleSkip` defined as `pc[k] || …`. Set
        # pieces were never admitted for an instant — but the guard went red, correctly, because
        # it could only see the old spelling. A guard that greps source text fails on a refactor
        # of correct code, which is this repo's own carved lesson.
        #
        # So it now asserts the LAW in the shape that survives a refactor: `pc` decides, and BOTH
        # loops consult the same decision. Still source-reading — but reading for the rule rather
        # than for one arrangement of characters. [[source-reading-guard]]
        self.assertRegex(
            blk, r"pc\[k\]",
            "the roster no longer consults _pieces() at all, so the vault would admit 127 set pieces")
        # ⚠ LINE-WISE, NOT A MULTI-LINE REGEX. My first cut used `[^\n]*\n?[^\n]*`, which is greedy
        # enough to swallow BOTH loops as a single match and then reported "found 1". The test
        # caught my own instrument, which is what it is for. [[feedback-suspect-the-instrument]]
        skips = [ln for ln in blk.split("\n")
                 if "Object.keys(iv).forEach" in ln or "Object.keys(ue).forEach" in ln]
        self.assertEqual(len(skips), 2,
                         "expected exactly two roster loops (ITEM_VALUE and _UNI_EXTRA); found %d"
                         % len(skips))
        for loop in skips:
            self.assertTrue(
                ("pc[k]" in loop) or ("_chronicleSkip(k)" in loop),
                "a roster loop admits names without consulting the set-piece exclusion: %s"
                % loop.strip()[:120])


class TestV2082SightingsSurviveAStrayByte(unittest.TestCase):
    """vault_seen_save MERGES onto vault_seen_load(), so an unreadable store read as "no prior
    sightings" and the next save wrote only the new rows.

    MEASURED: three banked plus one new = 4 on disk; append ONE byte; the next sweep leaves 1. Four
    ungrounded sightings destroyed, silently — the evidence the two-witness bar exists to
    accumulate, and his tree holds 17 of them. The docstring said, verbatim, "an unreadable file is
    not evidence of an empty stash" and then returned []."""

    def _ca(self, root):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app as ca
        self.addCleanup(setattr, ca, "_VAULT_SEEN_PATH", ca._VAULT_SEEN_PATH)
        ca._VAULT_SEEN_PATH = os.path.join(root, "vault_seen.json")
        return ca

    def _row(self, n, s):
        return {"name": n, "lane": "stash", "kind": "item", "conf": 0.9,
                "witnesses": [{"session": s, "frame": s + "#0"}], "lastSeenTs": 1500000000000}

    def _root(self):
        d = tempfile.mkdtemp(prefix="seen_")
        self.addCleanup(shutil.rmtree, d, True)
        return d

    def test_absent_and_unreadable_are_different_answers(self):
        import json as _j
        root = self._root()
        ca = self._ca(root)
        rows, ok = ca.vault_seen_load(strict=True)
        self.assertEqual((rows, ok), ([], True), "an ABSENT store is a measurement, not an unknown")
        io.open(ca._VAULT_SEEN_PATH, "w").write(_j.dumps({"rows": [self._row("a", "s1")]}))
        self.assertEqual(ca.vault_seen_load(strict=True), ([self._row("a", "s1")], True))
        io.open(ca._VAULT_SEEN_PATH, "a").write("!")
        rows, ok = ca.vault_seen_load(strict=True)
        self.assertFalse(ok, "an UNREADABLE store still reports itself as readable-and-empty")

    def test_a_normal_sweep_still_MERGES_or_nothing_below_is_proven(self):
        import json as _j
        root = self._root()
        ca = self._ca(root)
        io.open(ca._VAULT_SEEN_PATH, "w").write(_j.dumps(
            {"rows": [self._row("a", "s1"), self._row("b", "s2"), self._row("c", "s3")]}))
        self.assertEqual(ca.vault_seen_save([self._row("d", "s4")]), 4,
                         "the merge itself is broken, so the refusal below proves nothing")

    def test_a_stray_byte_never_costs_him_a_sighting(self):
        import json as _j
        root = self._root()
        ca = self._ca(root)
        io.open(ca._VAULT_SEEN_PATH, "w").write(_j.dumps(
            {"rows": [self._row("a", "s1"), self._row("b", "s2"), self._row("c", "s3")]}))
        io.open(ca._VAULT_SEEN_PATH, "a").write("!")
        n = ca.vault_seen_save([self._row("d", "s4")])
        self.assertIsNone(n, "it merged onto an unreadable prior and erased every banked sighting")
        kept = [f for f in _fx_tmp.list_own(root) if ".corrupt" in f]
        self.assertTrue(kept, "the unreadable bytes were destroyed rather than kept")

    def test_a_second_corruption_does_not_overwrite_the_first(self):
        import json as _j
        root = self._root()
        ca = self._ca(root)
        for _ in range(2):
            io.open(ca._VAULT_SEEN_PATH, "w").write(_j.dumps({"rows": [self._row("a", "s1")]}))
            io.open(ca._VAULT_SEEN_PATH, "a").write("!")
            ca.vault_seen_save([self._row("d", "s4")])
        kept = [f for f in _fx_tmp.list_own(root) if ".corrupt" in f]
        self.assertGreaterEqual(len(kept), 2,
                                "the second corruption overwrote the first — only %d kept"
                                % len(kept))


class TestV2083AVaultedBaseSurvivesTheReload(unittest.TestCase):
    """v1987 refused a fix here and said exactly why: "chronicleApply reports `vaulted` for a base,
    yet d2r_owned does not gain it, so nothing reaches ownedPool() and nothing can be filed. That
    needs its own pass with the scope established first, not a guess at the end of an arc."

    MEASURED before the fix, a real apply then a reload:
        apply Shako · Phase Blade · Monarch · Archon Plate
          res.vaulted  all four     d2r_owned 4 ✓     muleAssign 0
        ...reload
          d2r_owned    0            .vm-cell  0
    and after: owned 4, muleAssign 4, .vm-cell 4, .vm-grid 2.

    TWO joints. The name never became KNOWN (the load-time accept-list rebuilds `owned` from the
    catalogues and a base is in none of them), and it was never FILED.

    These are source guards because the behaviour lives in a browser; the rendered half is
    tests/v2083_vaulted_base_survives.spec.ts, which runs on CI. [[test-venue]]"""

    def setUp(self):
        self.bible = os.path.join(os.path.dirname(HERE), "bible.html")
        if not os.path.isfile(self.bible):
            self.skipTest("bible.html is not on this machine")
        with io.open(self.bible, encoding="utf-8") as fh:
            self.s = fh.read()

    def _vaulted_branch(self):
        # v2265 — RE-ANCHORED, AND THE ANCHOR IS WHY. This located the block by the literal
        # `res.vaulted = res.vaulted || []; res.vaulted.push(n);`. That line was the DOUBLE-COUNT:
        # it fired beside the v2193 door's own push, so a base came back twice in res.vaulted and a
        # found unique came back zero times (measured 8-for-4 and 0-for-3). Reporting moved into one
        # idempotent _vaultReport call, so the anchor vanished and these three tests failed on their
        # OWN REACH while every behaviour they assert was untouched. `if (!_landed) {` is the branch
        # opener itself, unique in the file, and it is the thing this block IS rather than one line
        # that happened to sit at the top of it. [[source-reading-guard]]
        return _between(self, self.s, "if (!_landed) {",
                        "/* v1918", what="the vaulted branch")

    def test_a_vaulted_name_is_REMEMBERED_through_the_one_door(self):
        """_tvExtraRemember's own comment calls itself the one door "so there is one door and the
        store cannot drift from the object". This path vaults just as really and never used it."""
        blk = self._vaulted_branch()
        self.assertIn("window._tvExtraRemember(n,", blk,
                      "a base applied from a reel is never remembered, so the load-time accept-list "
                      "drops it and it exists for exactly one page-life")

    def test_the_remember_is_NOT_guarded_by_volatile_state(self):
        """`!findExtraItem(n)` asks whether the name is known RIGHT NOW — and _EXTRA_ITEM_SET holds
        entries that were never persisted, which is the v1991 defect this door exists to close.
        Measured: Shako answered KNOWN, was skipped, and vanished; Monarch and Archon Plate, which
        answered unknown, survived. A guard reading volatile state to decide a DURABLE action is
        asking the wrong question."""
        blk = self._vaulted_branch()
        self.assertNotIn("!window.findExtraItem(n)", blk,
                         "the durable remember is gated on an in-memory lookup again")

    def test_the_filing_goes_through_vaultAutoAssign_not_inline(self):
        """My first cut wrote `assign[n] = suggestMule(n).id` inline. It did nothing — `typeof
        assign` is 'undefined' in that scope, the v1987 failure verbatim. And had it worked it would
        have been WRONG: vaultAutoAssign skips equipment and inventory (his words, in capitals) and
        logs source:'auto-assign', where assignItem stamps 'filed-by-hand' — a lie about who
        decided."""
        blk = _between(self, self.s, "var res = window.chronicleApply({ wouldAdd:",
                       "out.grail", what="the apply call site")
        self.assertIn("window.vaultAutoAssign()", blk,
                      "nothing files the batch after an apply, so vaultAutoAssign has nothing to "
                      "work on and the grid stays empty")
        # ⚠ STRIP THE PROSE FIRST. The comment in that branch QUOTES `assign[n] = suggestMule(n).id`
        # to explain why it was removed, so a bare assertNotIn fails on my own explanation — the
        # third time tonight. Bound the block-comment strip so a stray `/*` cannot eat the file.
        # [[source-reading-guard]] §4
        vb = re.sub(r"/\*.{0,8000}?\*/", " ", self._vaulted_branch(), flags=re.S)
        self.assertNotIn("assign[n] =", vb,
                         "the vaulted branch files inline again — `assign` is a let in another "
                         "scope, so it silently does nothing, and it would bypass the equipment lock")
        self.assertIn("window._tvExtraRemember(n,", vb,
                      "the comment strip ate the code too — the slice is measuring nothing")

    def test_the_LOCKED_LANES_rule_is_still_where_the_filing_happens(self):
        """His words in capitals: "inventory and main character equiment (SHOULD NEVER BE TOLD TO BE
        MOVED its locked there)". Routing the apply through vaultAutoAssign is only safe while the
        filing honours that.

        #246 — THE LOCK MOVED WITH THE FILING. Every mule filing now goes through ONE door,
        window.vaultFile, and that door refuses a locked name for every caller (the sorter, the
        registrar, his hand). So the lock is asserted THERE, the sorter is asserted to file only
        through it, and to fill only EMPTY homes. [[the-unjoined-end]]"""
        blk = _between(self, self.s, "window.vaultAutoAssign = function()", "window.vaultClearUnsorted",
                       min_len=200, what="vaultAutoAssign")
        self.assertIn("if (assign[name] != null) return;", blk,
                      "auto-assign no longer fills only EMPTY homes — it can now override a "
                      "placement he made by hand")
        self.assertIn("window.vaultFile(name, _provAsWitness(_row)", blk,
                      "the sorter files around the one door, so the MAIN lock is not asked")
        door = _between(self, self.s, "window.vaultFile = function(name, witness, opts){",
                        "function _provAsWitness(row){", min_len=500, what="the one door")
        # ASSERT THE LOCK, NOT THE SENTENCE ABOUT IT (v2120) — the call and the refusal, as code
        self.assertIn("lk = (window._laneLocked && window._laneLocked(nm)) || ''", door,
                      "the one door no longer ASKS which lane the item is in")
        self.assertIn("if (lk) return { ok: false, refused: 'locked'", door,
                      "the one door asks _laneLocked and ignores the answer, so an item locked "
                      "to his equipment or inventory can be filed to a mule again")


class TestV2084TheVaultIsARoomOfItsOwn(unittest.TestCase):
    """Konyo: "the VAULT MANAGER it needs a MAIN TAB of its own inbetween tools and TV-D tab on
    top.. surgically put it there".

    It was a COLLAPSED boss-card inside Tools, opened by clicking a header, sharing that tab with
    sixteen other cards — the surface his readers feed and the one he asked to see first.

    Moving it touches seven sites and each one, missed, leaves a control that goes nowhere. The
    rendered half is tests/v2084_vault_tab.spec.ts; these are the joins a source read can pin."""

    def setUp(self):
        self.bible = os.path.join(os.path.dirname(HERE), "bible.html")
        if not os.path.isfile(self.bible):
            self.skipTest("bible.html is not on this machine")
        with io.open(self.bible, encoding="utf-8") as fh:
            self.s = fh.read()

    def test_the_tab_sits_between_the_forge_cluster_and_TVD(self):
        """His words: between Tools and TV·D. The forge three sit in that span and must stay
        adjacent, so the vault goes after fsets and before tvd."""
        import re as _re
        order = _re.findall(r'<button class="tab" data-tab="([a-z0-9]+)"', self.s)
        for t in ("tools", "fsets", "vault", "tvd"):
            self.assertIn(t, order, "%s left the tab bar" % t)
        self.assertLess(order.index("tools"), order.index("vault"))
        self.assertLess(order.index("vault"), order.index("tvd"))
        # #245 — 👤 Characters (the MANUAL side) now sits between F·Sets and the Vault, right before the room it
        # is separate from. So "fsets is immediately before vault" became two adjacencies, each as strict as the
        # one it replaces: the forge cluster still ends at fsets with nothing between it and Characters, and
        # Characters is immediately before the Vault. Nothing else may slip into that span.
        self.assertEqual(order[order.index("forge"):order.index("fsets") + 1], ["forge", "crafts", "funi", "fsets"],
                         "the forge cluster is no longer adjacent — funi/fsets moved")
        self.assertEqual(order[order.index("fsets"):order.index("vault") + 1], ["fsets", "chars", "vault"],
                         "only 👤 Characters (#245) may stand between the forge cluster and the Vault")

    def test_the_pane_uses_the_class_its_SIBLINGS_use(self):
        """⚠ THE ONE THAT ALMOST SHIPPED. I wrote class="tab-pane" — a class that appeared exactly
        ONCE in this file, on my own line. The real class is `tab-content`. Nothing threw: the pane
        simply never hid, so the Vault was visible UNDERNEATH every other tab. Measured on pixels:
        clicking Main showed `tab-main, tab-vault`. Reading the code would not have caught it;
        rendering did."""
        import re as _re
        panes = _re.findall(r'<div class="([a-z-]+)" id="tab-([a-z0-9]+)">', self.s)
        klass = dict((tab, cls) for cls, tab in panes)
        self.assertIn("vault", klass, "the #tab-vault pane is gone")
        self.assertEqual(klass["vault"], klass.get("tvd"),
                         "the vault pane uses %r while its sibling uses %r — a pane with the wrong "
                         "class never hides, and shows underneath every other tab"
                         % (klass.get("vault"), klass.get("tvd")))
        self.assertEqual(self.s.count('class="tab-pane"'), 0,
                         "a class that exists nowhere else in this file is a class nothing styles")

    def test_the_console_shell_can_reach_it(self):
        """`body.app-ctx .tabs .tab{display:none}` hides EVERY tab and one rule re-shows five by
        name. A tab added without joining it renders perfectly on the website and is unreachable in
        the app — one surface working is exactly how that split survives unnoticed."""
        blk = _between(self, self.s, "body.app-ctx .tabs .tab[data-tab=\"session\"]",
                       "display:inline-flex", what="the app-ctx re-show list")
        self.assertIn('data-tab="vault"', blk,
                      "the vault tab is invisible inside the console shell and fine on the site")

    def test_the_card_moved_and_did_not_stay(self):
        """A copy in both tabs would duplicate every id in it — 24 of them, including the render
        targets renderVault writes to."""
        self.assertEqual(self.s.count('id="mule-vault-card"'), 1,
                         "the card exists twice — every id inside it is now duplicated")
        i = self.s.index('id="tab-vault"')
        j = self.s.index('id="mule-vault-card"')
        self.assertLess(i, j, "the card is not inside the vault pane")
        # The repo's own meta-guard caught a fixed 20000-byte window here — twice tonight it has
        # enforced this rule on me. Bound by the pane's real end, not a byte count.
        # [[source-reading-guard]] §3
        pane = _between(self, self.s, 'id="tab-vault"', 'id="tab-tvd"',
                        min_len=2000, what="the vault pane")
        for el in ('id="vault-dock"', 'id="vault-shelf"'):
            self.assertIn(el, pane,
                          "renderVault's target %s did not travel with the card" % el)

    def test_every_navigator_points_at_the_room_it_is_now_in(self):
        """Three routes led to the card by switching to Tools. A jump that still switches to Tools
        lands him where the card is not, with nothing to show for the click."""
        vj = _between(self, self.s, "window.vaultJump = function()", "renderVault()",
                      what="vaultJump")
        self.assertIn("switchTab('vault')", vj, "vaultJump still opens Tools")
        self.assertNotIn("switchTab('tools')", vj)
        qi = _between(self, self.s, "var CARD = { vault:'mule-vault-card'",
                      "toggleCardCollapse(CARD[lane])", what="quickIntake")
        # ⚠ `assertIn("CARD_TAB")` also passes on `var CARD_TAB = {};` — the name survives being
        # gutted, and quickIntake('vault') then opens a card in a room he is not in. Assert the
        # MAPPING, not that the identifier exists. [[source-reading-guard]] §4b
        self.assertIn("CARD_TAB = { vault:'vault' }", qi,
                      "quickIntake's room lookup is empty — it opens the vault card without "
                      "switching to the vault tab")
        self.assertIn("window.switchTab(CARD_TAB[lane])", qi,
                      "the lookup exists and nothing consumes it")

    def test_the_tools_map_no_longer_claims_to_contain_it(self):
        """That panel says "Everything in this tab". Listing a card that left is how he goes looking
        for something that is not there. [[label-outlived-referent]]"""
        blk = _between(self, self.s, "Everything in this tab", "Rune Stash",
                       what="the Tools legend")
        self.assertNotIn("toolsLegendJump('mule-vault-card')", blk,
                         "the Tools map still jumps to the vault as an in-tab card")
        self.assertIn("its own \U0001f392 Vault tab", blk,
                      "the map does not say where the vault went")


class TestV2085TheSwitchesReachTheConsoleDrawer(unittest.TestCase):
    """Konyo: "the toggle buttons for shadow and the others put also in ADVANCED SETTINGs surgically
    put it there and typography and polish it perfectly".

    They were never website features: both call _shadowOnConsole(), which tests location.host for
    :17772/:17771, so on bull-4-u.com they hide entirely. Console controls reachable only by opening
    the board, finding Tools among sixteen cards, and scrolling to one of them."""

    def _ui(self):
        with io.open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as fh:
            return fh.read()

    def _bible(self):
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            return fh.read()

    def setUp(self):
        if not os.path.isfile(os.path.join(os.path.dirname(HERE), "bible.html")):
            self.skipTest("bible.html is not on this machine")

    def test_the_section_is_in_the_drawer_between_the_eyes_and_the_rare_paths(self):
        s = self._ui()
        i_eyes = s.index('<div class="adv-sec-h">\U0001f441 WHICH EYES READ</div>')
        i_new = s.index("WHAT WATCHES WHILE YOU PLAY")
        i_rare = s.index("RARE PATHS")
        self.assertLess(i_eyes, i_new, "the new section jumped above the eyes card")
        self.assertLess(i_new, i_rare, "the switches landed in RARE PATHS, which is where things "
                                       "he touches once a year live")

    def test_the_shadow_lane_reads_the_SAME_endpoint_the_board_reads(self):
        """One source of truth, two views. A second copy of the state is how one switch comes to
        say OFF while the lane is running."""
        s = self._ui()
        self.assertIn("fetch(API + '/api/shadow')", s,
                      "the drawer does not read /api/shadow — it is showing something it invented")
        self.assertIn("/api/shadow", self._bible(),
                      "the board stopped reading the same route, so the two can now disagree")

    def test_the_tooltip_row_reads_the_same_shadow_switch(self):
        """Konyo, 2026-09-28: the tooltip row under shadow was OFF while the shadow row was ON.
        That was a second store. Both rows paint from /api/shadow and both write it. The board
        still answers tooltipPassState, and that answer refuses a private on/off (on is null).
        """
        ui = self._ui()
        self.assertNotIn("tooltipPassState", ui,
                         "the drawer still asks the board for a second tooltip flag")
        self.assertNotIn("toggleTooltipPass", ui,
                         "the drawer still runs the pass that can start its own reel")
        paint = _between(self, ui, "function _shadowAdvPaint(j, err)",
                         "window._shadowAdvRefresh = function", what="the drawer painter")
        self.assertIn("var st = j;", paint,
                      "the tooltip row must paint the shadow payload, not a flag of its own")
        self.assertNotIn("p[1] === 'sha'", paint,
                         "branching the two rows onto different stores is the split he saw")
        # v3859 - Elad 2026-11-03: "shadow reader shouldnt be able to be turned on or off make it
        # defaulted ON always". Both rows are lamps now: no click handler, nothing POSTs.
        self.assertNotIn("[['sadv-sha', 'shadow'], ['sadv-tip', 'tooltip']]", ui,
                         "the two rows got their click handler back - the shadow reader has no switch")
        self.assertNotIn("JSON.stringify({ on: want })", ui,
                         "the drawer can POST an on/off to the shadow reader again")
        self.assertNotIn("fetch(API + '/api/shadow', { method: 'POST'", ui,
                         "the drawer POSTs /api/shadow again")
        state = _js_fn_from(self._bible(), "window.tooltipPassState = function(){")
        self.assertIn("follows: 'shadow'", state)
        self.assertIn("on: null", state,
                      "a missing private flag must not come back as OFF")
        self.assertNotIn("_TP_KEY", state)
        self.assertNotIn("d2r_tooltipPass", self._bible(),
                         "the private tooltip store is back")

    def test_an_unreachable_route_reads_UNKNOWN_not_OFF(self):
        """"I could not ask" and "he turned it off" are opposite facts. Both rows share the one
        shadow route, so one unanswered route covers both. There is no second board path.
        [[unknown-stays-unknown]]"""
        ui = self._ui()
        blk = _between(self, ui, "function _shadowAdvPaint(j, err)",
                       "window._shadowAdvRefresh = function", what="the drawer painter")
        # Strip the prose. A comment that says the word would inflate the count.
        code = re.sub(r"/\*.{0,4000}?\*/", " ", blk, flags=re.S)
        self.assertEqual(code.count("UNKNOWN"), 1,
                         "the only unreachable path is the shadow route; a second path is a second "
                         "logic. the code has %d" % code.count("UNKNOWN"))
        self.assertEqual(code.count("btn.disabled = true"), 1,
                         "a switch it could not read stays pressable. disabled-true count is %d"
                         % code.count("btn.disabled = true"))
        self.assertNotIn("say.textContent = 'OFF'", code,
                         "an unreachable lane is being reported as OFF — 'I could not ask' and 'he "
                         "turned it off' are opposite facts")

    def test_the_three_facts_are_not_averaged_into_one_lamp(self):
        """The route's own comment: "A single green light covering all three is the g5 scar:
        mode=primary, calls=0." `available` and `recording` must each reach a sentence."""
        blk = _between(self, self._ui(), "function _shadowAdvPaint(j, err)",
                       "window._shadowAdvRefresh = function", what="the drawer painter")
        self.assertIn("available", blk, "whether the lane can run at all is not reported")
        self.assertIn("recording", blk, "whether a reel is rolling is not reported")
        self.assertIn("cannot run it", blk,
                      "a lane that cannot run reads the same as one that is simply off")

    def test_the_painter_is_actually_CALLED_when_the_drawer_opens(self):
        """Built on both ends and never joined is the failure this whole file keeps finding. The
        hook lives in the ontoggle ATTRIBUTE, not a JS line — the first cut added the function and
        nothing invoked it.

        ⚠ v2428 — THE LAW IS UNCHANGED AND THE MECHANISM MOVED, so this now looks in the new
        place rather than asserting the old line. Until v2428 the drawer's ontoggle called each
        refresher by name, inline. That is exactly what broke: the attribute fires during PARSE,
        between the file's two script blocks, so `window._fleetRefresh` - defined in block 2 - did
        not exist yet and its TypeError died in an empty catch on every load. The calls now live in
        `_advFill`, declared below every function it calls and invoked outright on load.

        This test's question is still the right one and still fails for the right reason: is the
        painter actually REACHED when the drawer opens? Only the address changed.
        """
        fill = _between(self, self._ui(), "window._advFill = function", "\n  };",
                        min_len=200, what="the _advFill body")
        self.assertIn("_shadowAdvRefresh", fill,
                      "the painter exists and nothing in the drawer's fill calls it")


class TestV2086TheThreeThingsThatWereQuietlyTrue(unittest.TestCase):
    """Three latent items an adversarial review named and nobody had fixed. None was firing; all
    three are the kind that stay true and quiet until they are not."""

    def _rr(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import reel_retention
        return reel_retention

    def _ca(self):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import control_app
        return control_app

    # ── ONE FLOOR ────────────────────────────────────────────────────────────────────────────
    def setUp(self):
        """⚠ v2425 — DECLARE A WORLD. The last writer CI named, found by instrumenting the writes
        after the other six were closed: this class writes `disk_history.jsonl`. Production
        resolves that path through the fixture root now (v2423); this is the other half."""
        import tempfile as _tf, shutil as _sh, os as _os
        _d = _tf.mkdtemp(prefix="dh_")
        self.addCleanup(_sh.rmtree, _d, True)
        _old = _os.environ.get("TV_HIST")
        _os.environ["TV_HIST"] = _d
        self.addCleanup(lambda: (_os.environ.__setitem__("TV_HIST", _old) if _old is not None
                                 else _os.environ.pop("TV_HIST", None)))

    def test_the_ON_AIR_floor_exists_exactly_ONCE(self):
        """This number decides two different things: whether /api/on will RECORD, and whether the
        auto-prune may DELETE. They must be the same by construction, because the whole argument
        for deleting unattended is "below this he cannot record anyway". It lived in FOUR places —
        one constant and three bare 8.0 literals — agreeing today with nothing holding them
        together. Move one and the deleter acts at a level where recording still works.
        [[copy-drift]]"""
        import inspect
        src = inspect.getsource(self._ca())
        src = "\n".join(ln for ln in src.splitlines() if not ln.lstrip().startswith("#"))
        self.assertEqual(src.count("_free < 8.0"), 0,
                         "a bare 8.0 floor literal is back — it can drift from ON_AIR_FLOOR_GB, "
                         "and then the deleter and the recorder disagree about the same threshold")
        # v2316 — WAS: assertGreaterEqual(src.count("_free < ON_AIR_FLOOR_GB"), 2). That counted a
        # code SHAPE, and v2316 centralised the comparison into capture_preflight() so the shape
        # legitimately went from 2 sites to 1. Loosening a guard to admit my own change is how a
        # guard becomes furniture, so this asserts something STRONGER instead: the floor has one
        # definition, and EVERY door that can start a recording routes its disk decision through
        # the one preflight that reads it. Hardcode a floor in any door and this fails.
        # ⚠ ANCHORED AT LINE START. `src.count("ON_AIR_FLOOR_GB =")` also matches
        # `_ON_AIR_FLOOR_GB = ON_AIR_FLOOR_GB`, which is an alias that correctly READS the shared
        # floor — so the first cut of this guard reported the one-definition rule as broken by the
        # very line that honours it. A substring is not a definition. [[source-reading-guard]]
        import re as _re
        _defs = _re.findall(r"^ON_AIR_FLOOR_GB\s*=", src, _re.M)
        self.assertEqual(len(_defs), 1,
                         "the shared floor has %d top-level definitions — that is the drift the "
                         "original guard was built to stop" % len(_defs))
        self.assertIn("def capture_preflight(", src,
                      "the one place the floor is compared has gone")
        pre = _between(self, src, "def capture_preflight(", "\ndef _capture_door_load",
                       what="capture_preflight")
        self.assertIn("ON_AIR_FLOOR_GB", pre,
                      "capture_preflight stopped reading the shared floor, so every door that "
                      "trusts it is now deciding against nothing")
        for door in ("shadow_watch_tick", "mini_start"):
            body = _between(self, src, "def %s(" % door, "\ndef ", what=door)
            self.assertIn("capture_preflight(", body,
                          "%s stopped asking the shared preflight — it is deciding whether it can "
                          "record from its own idea of the floor again" % door)

    def test_the_deleter_and_the_recorder_use_the_SAME_number(self):
        """Read at runtime, not from the text — the property is that they are equal, not that they
        look alike."""
        ca = self._ca()
        st = ca.retention_state()
        ca._retention_once()
        st = ca.retention_state()
        self.assertEqual(st.get("floorGb"), ca.ON_AIR_FLOOR_GB,
                         "the deleter publishes a floor that is not the one it uses")

    # ── THE TOMBSTONE FOLLOWS THE TREE ───────────────────────────────────────────────────────
    def test_the_record_lands_beside_the_footage_it_records(self):
        """It resolved from rr.HERE and TV_HIST only, so a caller passing hist_dir straight to
        plan() deleted from one tree and wrote the tombstones into HIS. `_tombstone(hist, cands)`
        has always RECEIVED that path and ignored it."""
        rr = self._rr()
        d = tempfile.mkdtemp(prefix="tombtree_")
        self.addCleanup(shutil.rmtree, d, True)
        hist = os.path.join(d, "hist")
        os.makedirs(hist)
        got = rr._tombstone_path(hist)
        self.assertTrue(got.startswith(os.path.realpath(d)),
                        "a foreign tree still records its tombstones into %s" % got)

    def test_HIS_OWN_tree_still_records_where_it_always_did(self):
        """The mirror. Redirecting on any hist argument would move his real tombstone file the
        moment something passed his own path in."""
        rr = self._rr()
        mine = os.path.join(rr.HERE, "frames", "hist")
        self.assertEqual(rr._tombstone_path(mine), rr._tombstone_path(),
                         "passing his own hist moved his tombstone file")

    def test_the_under_check_is_IMPORTED_not_re_derived(self):
        """⚠ The first cut called `_under` bare — it lives in tv_diablo, not here, so it was a
        NameError swallowed by the `except Exception: pass` two lines below it. A guard that can
        never pass, hiding inside its own error handling.

        And it is imported rather than rewritten because v1897 says why: the comparison "was
        written four times tonight as h.startswith(root + os.sep), and on Windows that is a coin
        flip". His Windows machine is the other half of this project."""
        import inspect
        src = inspect.getsource(self._rr()._tombstone_path)
        self.assertIn("from tv_diablo import _under", src,
                      "the containment check is re-derived locally again")
        body = "\n".join(ln for ln in src.splitlines() if not ln.lstrip().startswith("#"))
        self.assertNotIn("startswith(", body,
                         "a hand-rolled prefix comparison is back — v1897 measured that one as a "
                         "coin flip on Windows")

    # ── A BUDGET THAT COULD ONLY FIRE ON HIS MACHINE ─────────────────────────────────────────
    def test_the_cheap_budget_admits_when_it_measured_nothing(self):
        """On a clean CI checkout every console- and footage-dependent check returns instantly, so
        the budget is unreachable there and the 16,585 ms check it caught was only ever catchable
        on his tree. A guard that fires on one machine and never on another has an opinion about
        which machine you are on. [[feedback-blind-fixture-green-gate]]"""
        import inspect
        src = inspect.getsource(self.__class__.__module__ and
                                sys.modules[self.__class__.__module__])
        i = src.index("def test_the_cheap_subset_is_actually_CHEAP")
        blk = src[i:src.index("\n    def ", i + 10)]
        # ⚠ `assertIn("did_work")` matches even when the increment is unreachable — the identifier
        # survives in the declaration and in the message. Anchor on the CONDITION that does the
        # counting. [[source-reading-guard]] §4b
        self.assertIn("if ms > 1.0:", blk,
                      "nothing counts how many checks actually did work, so a run that measured "
                      "nothing reports the same as one that measured everything")
        self.assertIn("did_work += 1", blk)
        # ⚠ "UNMEASURED" appears TWICE in that block — once in the comment explaining the rule and
        # once in the message he actually sees. Changing one leaves the other, so a bare assertIn
        # passes with the report gutted. Anchor on the sentence that reaches HIM.
        # [[source-reading-guard]] §2 — an anchor that is not unique is a guess.
        self.assertIn("A green result here is UNMEASURED, not", blk,
                      "a run that measured nothing is reported as a pass — the distinction this "
                      "whole tree is built on")


class TestV2087TheFloorIsPublishedOnATreeThatNeverRecorded(unittest.TestCase):
    """A CONSTANT IS KNOWN BEFORE ANYTHING IS MEASURED — and this one was not published until
    something was.

    v2086 pulled the 8GB floor into ON_AIR_FLOOR_GB so the deleter and the recorder could not drift
    apart, and guarded it with a runtime equality check. That guard passed on his Mac and FAILED on
    every CI checkout, because floorGb only ever reached the payload through _retention_once's
    `base` — which is built AFTER three early returns (no hist dir, disk_usage raised, plan not ok).
    A tree that has never recorded takes one of those three every time.

    WHAT IT COST: the Publish workflow went red at v2086 and stayed red. A red Publish does not
    deploy. His live site sat two versions behind while every local gate reported green — the
    failure was invisible from the machine the work was done on. [[the-unjoined-end]]

    ⚠ THIS TEST EXISTS BECAUSE ITS SIBLING COULD NOT SEE IT. The v2086 check calls _retention_once()
    on whatever tree it finds, so on a machine with footage it measures a real floor and passes. The
    property it MEANT to assert — published floor == used floor — has to be checked where nothing has
    ever been measured, which is the only place it was ever false.
    [[feedback-blind-fixture-green-gate]] [[unknown-stays-unknown]]

    Fixtures only. TV_HIST is pointed at a directory that does not exist; his tree is never read.
    [[feedback-fixtures-never-touch-live-data]]"""

    def _cold(self, body):
        """Run `body` in a CHILD process whose TV_HIST points nowhere, so this cannot be satisfied
        by state some earlier test in this process left behind."""
        import subprocess, sys as _s, tempfile, os as _o
        root = tempfile.mkdtemp(prefix="coldfloor_")
        self.addCleanup(__import__("shutil").rmtree, root, True)
        prog = ("import os,sys\n"
                "os.environ['TV_STUB']='1'\n"
                "os.environ['TV_HIST']=%r\n"
                "sys.path.insert(0,%r)\n"
                "import control_app as ca\n" + body)
        r = subprocess.run([_s.executable, "-c", prog % (_o.path.join(root, "never", "hist"),
                                                        _o.path.dirname(_o.path.abspath(__file__)))],
                           capture_output=True, text=True)
        return (r.stdout or "").strip(), (r.stderr or "").strip()

    def test_the_floor_is_published_even_though_nothing_was_ever_measured(self):
        out, err = self._cold("st=ca.retention_state()\n"
                              "print(repr(st.get('floorGb')), repr(ca.ON_AIR_FLOOR_GB))\n")
        self.assertTrue(out, "the cold-tree probe produced nothing: %s" % err[-300:])
        got, want = out.split()
        self.assertNotEqual(got, "None",
                            "a tree that never recorded publishes NO floor — which is exactly the "
                            "state every CI checkout is in, and why Publish went red at v2086")
        self.assertEqual(got, want,
                         "the published floor %s is not the floor the deleter uses %s" % (got, want))

    def test_it_is_still_right_after_a_run_that_returns_early(self):
        """_retention_once takes an early return on a tree with no footage. The floor must survive
        that, not be erased by it."""
        out, err = self._cold("ca._retention_once()\n"
                              "st=ca.retention_state()\n"
                              "print(repr(st.get('floorGb')), repr(ca.ON_AIR_FLOOR_GB))\n")
        self.assertTrue(out, "the cold-tree probe produced nothing: %s" % err[-300:])
        got, want = out.split()
        self.assertEqual(got, want,
                         "an early return left the published floor as %s while the deleter uses %s"
                         % (got, want))

    def test_the_floor_is_not_simply_hardcoded_twice(self):
        """A stamp that repeated the literal would pass the two checks above and still drift. It has
        to READ the constant."""
        src = self._src() if hasattr(self, "_src") else io.open(
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "control_app.py"),
            encoding="utf-8").read()
        i = src.index("def retention_state()")
        blk = src[i:src.index("\ndef ", i + 10)]
        blk = "\n".join(ln for ln in blk.splitlines() if not ln.lstrip().startswith("#"))
        self.assertIn('st["floorGb"] = ON_AIR_FLOOR_GB', blk,
                      "retention_state no longer stamps the floor from the shared constant")
        self.assertNotIn("8.0", blk,
                         "a bare 8.0 literal is back inside retention_state — it can drift from "
                         "ON_AIR_FLOOR_GB, which is the whole defect v2086 set out to close")


class TestV2098ASkippedReelSaysWHYItWasSkipped(unittest.TestCase):
    """A REEL SKIPPED BECAUSE NOBODY ASKED FOR IT IS NOT A REEL THAT HAS BEEN READ.

    Konyo: "how come they are still waiting on a sweep the items it says in the tooltip here" —
    11 reel(s), 609 MB, and pressing sweep never cleared them.

    chronicle_retro labelled EVERY reel in the caller's skip set "already-swept", and skip_reels
    is supplied by the caller: a TARGETED sweep narrows it to the reel it wants (v1779), so every
    reel that was merely NOT TARGETED reported itself as done.

    IT SELF-PERPETUATES, which is why it survived: the sweep skips them claiming done, the memory
    never gains an entry, retention holds them as unread, the next sweep skips them again.

    MEASURED ON HIS TREE before the fix:
        last run  30 reels · 29 noted "already-swept" · 1 read · pagesRead 0
        memory    chronicle_swept.json holds 24 entries
        mismatch  12 of the 29 appear in NO memory entry
        age       the run (17:56:14) was NEWER than the memory (17:46:20) — a real inconsistency,
                  not a stale read. Checked before claiming it. [[stale-reading]]
        after     18 already-swept · 12 not targeted this run
    And retention, independently, calls 10 of them "never chronicle-swept ... not read even once".

    Fixtures only — a COPIED tree with its own chronicle_swept.json. His is never written.
    [[feedback-fixtures-never-touch-live-data]]"""

    def _tree(self, memory):
        import shutil, tempfile, json as _j
        root = tempfile.mkdtemp(prefix="skipnote_")
        self.addCleanup(shutil.rmtree, root, True)
        for f in ("chronicle_retro.py",):
            shutil.copy2(os.path.join(HERE, f), root)
        hist = os.path.join(root, "hist"); os.makedirs(hist)
        for nm in ("reel_s_1000000000000_1", "reel_s_1000000000001_2"):
            os.makedirs(os.path.join(hist, nm))
            with open(os.path.join(hist, nm, "f_1000000000000.jpg"), "wb") as fh:
                fh.write(b"x" * 64)
        with io.open(os.path.join(root, "chronicle_swept.json"), "w", encoding="utf-8") as fh:
            fh.write(_j.dumps(memory))
        return root, hist

    def _notes(self, root, hist, skip):
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "cr_fixture_%d" % id(root), os.path.join(root, "chronicle_retro.py"))
        cr = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(cr)
        out = cr.sweep_hist(hist, lambda *a, **k: [], lambda *a, **k: {}, skip_reels=set(skip))
        return {r.get("reel"): r.get("note") for r in (out.get("reels") or [])}

    def test_a_reel_the_memory_knows_is_already_swept(self):
        root, hist = self._tree({"reel_s_1000000000000_1": {"ts": 1, "pages": 3}})
        notes = self._notes(root, hist, ["reel_s_1000000000000_1", "reel_s_1000000000001_2"])
        self.assertEqual(notes.get("reel_s_1000000000000_1"), "already-swept",
                         "a reel the sweep memory records was genuinely paid for")

    def test_a_reel_the_memory_does_NOT_know_says_it_was_not_targeted(self):
        root, hist = self._tree({"reel_s_1000000000000_1": {"ts": 1, "pages": 3}})
        notes = self._notes(root, hist, ["reel_s_1000000000000_1", "reel_s_1000000000001_2"])
        self.assertEqual(notes.get("reel_s_1000000000001_2"), "not targeted this run",
                         "a reel skipped for any reason OTHER than having been read must say so — "
                         "claiming 'already-swept' is what stranded 12 of his reels forever")

    def test_an_unreadable_memory_claims_NOTHING_is_swept(self):
        """Fail toward work, never toward a false 'done'. If the memory cannot be read, the sweep
        may not assert that any reel has been paid for."""
        root, hist = self._tree({"reel_s_1000000000000_1": {"ts": 1, "pages": 3}})
        with io.open(os.path.join(root, "chronicle_swept.json"), "w", encoding="utf-8") as fh:
            fh.write("{ this is not json")
        notes = self._notes(root, hist, ["reel_s_1000000000000_1", "reel_s_1000000000001_2"])
        self.assertEqual(sorted(set(notes.values())), ["not targeted this run"],
                         "an unreadable memory must not let any reel claim it was already swept")


class TestV2101ACraftIsOneTaskWithItsOwnPicture(unittest.TestCase):
    """v2101 — Konyo: "mission crafts render twice with mismatched art".

    v1411 appended every ready craft to `d2r_forgeSummary.now` so the console's FORGE
    QUESTS would stop under-showing them — but the payload's `crafts` key still carried
    the same rows. Two channels, one truth, and the console reads both: each craft drew
    once as `MAKE NOW` and again as `CRAFT NOW`. The pictures disagreed for the same
    reason: the `art` map is built from RUNEWORDS, so the MAKE NOW copy resolved to no
    art and the CRAFT NOW copy fell back to one generic medallion shared by all six.

    It also made the DAILY TASK FORCE hero read "Forge <b>Caster Amulet</b> — you own
    every rune" about a craft, which is not forged and needs a gem.

    Three assertions, because the bug had three faces. [[copy-drift]]
    """

    def setUp(self):
        # `os.path.dirname(HERE)` is how every other test in this file reaches the board
        # (see line ~807). There is no module-level REPO — an earlier draft of this guard
        # assumed one, and the harness that "proved" it green had silently CREATED the name
        # by assigning to it, so the guard passed in the prover and errored in the suite.
        # [[feedback-suspect-the-instrument]]
        with open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as f:
            self.board = f.read()
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()

    def test_the_bridge_publishes_crafts_on_exactly_ONE_channel(self):
        i = self.board.find("var _fsPayload = {")
        self.assertGreater(i, 0, "the console bridge payload is gone")
        j = self.board.find("\n        };", i)
        self.assertGreater(j, i, "could not find the end of the bridge payload")
        body = self.board[i:j]

        now = re.search(r"\n\s*now:\s*([^\n]+)", body)
        self.assertIsNotNone(now, "the bridge stopped publishing `now`")
        self.assertNotIn(
            "_fsNowCraft", now.group(1),
            "crafts are being poured into `now` AND published as `crafts` again — the console "
            "renders both, so every ready craft draws twice (MAKE NOW + CRAFT NOW)",
        )
        self.assertIn("crafts:", body, "the craft channel itself vanished")

    def test_every_craft_carries_its_OWN_art(self):
        # scope to the bridge payload: `crafts:` also occurs in the Forge's own scan output,
        # and an anchor that matches the WRONG occurrence reports on code it was not aiming at
        i = self.board.find("var _fsPayload = {")
        self.assertGreater(i, 0, "the console bridge payload is gone")
        j = self.board.find("\n        };", i)
        self.assertGreater(j, i, "could not find the end of the bridge payload")
        body = self.board[i:j]
        for key in ("crafts:", "craftOnestep:"):
            k = body.find(key)
            self.assertGreater(k, -1, f"{key} is gone from the bridge payload")
            line = body[k:body.find("\n", k)]
            self.assertIn(
                "art:", line,
                f"{key} ships no art, so the console falls back to ONE generic medallion for "
                f"every craft — a picture that identifies nothing",
            )

    def test_the_console_does_not_paint_every_craft_the_same(self):
        i = self.ui.find("function hdForge(")
        self.assertGreater(i, 0, "hdForge() is gone")
        j = self.ui.find("\n  function ", i + 1)
        self.assertGreater(j, i, "could not find the end of hdForge()")
        body = self.ui[i:j]
        self.assertIn("_craftArt = function", body,
                      "the per-craft art resolver is gone from hdForge()")
        # check the CHIPS themselves rather than counting artImg calls: the generic medallion is
        # legitimate as _craftArt's own fallback, so its mere presence proves nothing either way
        for marker, what in ((" · CRAFT NOW</span>", "the ready-craft chip"),
                             ("+ miss + '</span>'", "the one-step craft chip")):
            k = body.find(marker)
            self.assertGreater(k, -1, f"{what} is gone from hdForge()")
            seg = body[body.rfind("\n", 0, k):k]
            self.assertIn(
                "_craftArt(t)", seg,
                f"{what} paints a generic medallion directly again — one picture for all of "
                f"them, which is the 'mismatched art' half of his report",
            )

    def test_the_task_force_does_not_call_a_craft_a_runeword(self):
        i = self.ui.find("function hdTaskForce(")
        self.assertGreater(i, 0, "hdTaskForce() is gone")
        j = self.ui.find("\n  function ", i + 1)
        self.assertGreater(j, i, "could not find the end of hdTaskForce()")
        body = self.ui[i:j]
        self.assertIn(
            "you own the gem and the rune", body,
            "a ready CRAFT has no branch of its own, so it inherits the runeword sentence "
            "'you own every rune' — which is not what a craft needs",
        )
        self.assertIn("craftList", body, "the Task Force no longer reads the craft channel")


class TestV2102TheConsoleNoticesItIsBehind(unittest.TestCase):
    """v2102 — Konyo opened a second machine: "it's reading v945. why is it not auto
    updating itself."

    Nothing was broken. There was simply no passive check anywhere. The code that finds
    out lived entirely inside `$('foot-ver').onclick`, and the comment directly above it
    claimed "banner also paints when behind" about a banner that had never been written.
    Meanwhile /api/update's own howTo said "Relaunch TV DIABLO to auto-pull" — false on
    every platform: NO Mac launcher pulled (only the one-time install script did), and the
    Windows launcher skips the pull whenever the console is already up, which for an
    always-on console is always. So a machine could sit 1,150 versions back in silence.

    Four assertions, one per unjoined end. [[the-unjoined-end]]
    """

    def setUp(self):
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()
        with open(os.path.join(HERE, "control_app.py"), encoding="utf-8") as f:
            self.app = f.read()

    def test_the_check_runs_without_being_clicked(self):
        self.assertIn('id="fleet-bar"', self.ui, "the fleet banner markup is gone")
        # a check that only a human can start is not a check: it must be armed on load
        # AND re-armed on a timer, not merely defined
        self.assertIn("setInterval(look,", self.ui,
                      "the behind-check no longer repeats — a console left open would never "
                      "learn it went stale")
        i = self.ui.find("setInterval(look,")
        self.assertGreater(i, 0)
        window = self.ui[max(0, i - 2600):i]
        self.assertIn("/api/update", window,
                      "the periodic check does not actually ask /api/update")
        self.assertIn("look();", self.ui,
                      "the check is defined but never run at load — the banner would only "
                      "appear 30 minutes in")

    def test_the_banner_offers_an_action_that_exists(self):
        self.assertIn('id="fleet-go"', self.ui, "the UPDATE NOW button is gone")
        # v2120 (#89) — SCOPE IT TO THE HANDLER. "method: 'POST'" occurs 25 times in
        # control_ui.html and the first is the generic fetch helper ~4,600 lines above #fleet-go,
        # so reverting UPDATE NOW to a GET left this green. [[source-reading-guard]]
        go = _between(self, self.ui, "go.onclick = async function()", "\n    };",
                      what="the UPDATE NOW handler")
        self.assertIn("'/api/update'", go, "UPDATE NOW no longer talks to /api/update at all")
        self.assertIn("method: 'POST'", go,
                      "UPDATE NOW no longer POSTs — GET /api/update only REPORTS, it cannot "
                      "change anything, so the button would be decoration")
        self.assertIn('if path == "/api/update"', self.app)
        # and the POST route must reach the worker, not just report again
        self.assertIn("fleet_pull()", self.app,
                      "POST /api/update does not call the pull worker")

    def test_the_pull_refuses_on_a_dirty_tree_and_only_fast_forwards(self):
        i = self.app.find("def fleet_pull(")
        self.assertGreater(i, 0, "fleet_pull() is gone")
        body = self.app[i:self.app.find("\ndef ", i + 10)]
        self.assertIn("--untracked-files=no", body,
                      "the dirty check counts UNTRACKED files, so reels/logs/caches — which "
                      "live in this repo — would block every update forever")
        self.assertIn("--ff-only", body, "the pull is no longer fast-forward-only")
        for forbidden in ("reset", "--hard", "rebase"):
            self.assertNotIn(forbidden, body,
                             "fleet_pull must never %s — it runs unattended on his machines "
                             "and would destroy local work" % forbidden)

    def test_it_reports_the_version_on_DISK_not_the_one_in_memory(self):
        i = self.app.find("def fleet_pull(")
        body = self.app[i:self.app.find("\ndef ", i + 10)]
        # STRIP THE PROSE FIRST. The comment inside fleet_pull EXPLAINS why _app_ver() is
        # wrong here, and naming it there made this guard fire on its own documentation —
        # red for the presence of the sentence describing the fix. A guard that greps source
        # must read CODE, not the paragraph about the code. [[feedback-comments-vs-code]]
        code = "\n".join(ln for ln in body.splitlines() if not ln.lstrip().startswith("#"))
        self.assertNotIn("_app_ver()", code,
                         "_app_ver() reports the stamp of the module THIS PROCESS loaded at "
                         "boot, which after a successful pull is still the OLD code — it "
                         "would show the version unchanged and read as 'the update failed' "
                         "at the exact moment it worked")
        self.assertIn("__file__", code,
                      "the reported version is not read off disk")

    def test_relaunching_on_a_mac_actually_pulls(self):
        with open(os.path.join(HERE, "start_tvd_mac.sh"), encoding="utf-8") as f:
            sh = f.read()
        self.assertIn("pull --ff-only", sh,
                      "the Mac launcher does not pull, so 'relaunch to update' is false here")
        self.assertIn("--untracked-files=no", sh,
                      "the launcher's clean-tree check counts untracked files (reels, logs) "
                      "and would therefore never pull on a real machine")


class TestV2103AControlThatVanishesIsNotAControl(unittest.TestCase):
    """v2103 — Konyo: "when i click advanced in the console right now its like hidden the
    options there grok eye and shadow ai.. its always hidden like sometimes itsm there and
    sometimes its not lol."

    Intermittent, because it was a FETCH FAILURE. `refreshG5()` ended in
    `catch (e){ card.hidden = true; }`, and `paintG5` opened with
    `if (!st || st.present === false){ card.hidden = true; return; }`. Three different
    facts — "I could not ask", "this machine has no grok binary", and a real payload —
    collapsed into one outcome, and two of them DELETED the control he had opened
    ADVANCED to find. A moment later the next poll succeeded and it was back.

    The block 100 lines above this code already states the rule for the OTHER two
    switches in the same drawer: "AN UNREACHABLE ROUTE READS UNKNOWN, NEVER OFF." The
    eyes card simply never got it. [[unknown-stays-unknown]]
    """

    def setUp(self):
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()
        i = self.ui.find("function g5EyesUi(")
        self.assertGreater(i, 0, "the Grok Eyes card wiring is gone")
        j = self.ui.find("\n  })();", i)
        self.assertGreater(j, i, "could not find the end of g5EyesUi()")
        body = self.ui[i:j]
        # READ CODE, NOT THE PARAGRAPHS EXPLAINING IT. This fix is DESCRIBED in a block
        # comment that quotes the very expression it removed ("The first two both did
        # `card.hidden = true`"), so a naive filter on lines STARTING with // or * leaves
        # every continuation line of that paragraph in — and the guard fires on its own
        # documentation. Strip real /* */ blocks and // lines.
        # [[feedback-comments-vs-code]] [[source-reading-guard]]
        code = re.sub(r"/\*.*?\*/", " ", body, flags=re.S)
        code = re.sub(r"(?m)^\s*//.*$", "", code)
        # AND CHECK THE STRIP DID NOT DEVOUR THE CODE. An unbounded /*…*/ strip once ate
        # 16.9% of bible.html and the guard downstream went quietly green on the crumbs.
        # THE COUNT IS THE TELL. [[feedback-suspect-the-instrument]]
        self.assertGreater(
            len(code), 0.35 * len(body),
            "the comment strip removed %d%% of g5EyesUi() — that is the stripper eating code, "
            "not comments, and every assertion below would be reading crumbs"
            % round(100 * (1 - len(code) / float(len(body)))),
        )
        self.code = code

    def test_no_path_hides_the_card(self):
        self.assertNotIn(
            "card.hidden = true", self.code,
            "something still hides the Grok Eyes card. A control the user is hunting for must "
            "never disappear — an unreachable route is UNKNOWN, not absent, and a missing "
            "binary is a sentence, not a deletion",
        )

    def test_a_failed_fetch_paints_UNKNOWN_rather_than_disappearing(self):
        i = self.code.find("async function refreshG5(")
        self.assertGreater(i, 0, "refreshG5() is gone")
        body = self.code[i:i + 900]
        self.assertIn("catch", body)
        self.assertIn(
            "paintG5(null", body,
            "the catch no longer repaints the card as UNKNOWN — whatever it does instead, the "
            "control must still be on screen after a failed fetch",
        )

    def test_the_three_states_stay_separate(self):
        self.assertIn("present === false", self.code,
                      "the 'not installed on this machine' case is gone — it would now be "
                      "reported as if the server were unreachable")
        for phrase in ("UNKNOWN", "not installed on this machine"):
            self.assertIn(phrase, self.code,
                          "the card no longer distinguishes 'could not ask' from 'cannot run "
                          "here'; those are opposite facts")


class TestV2104OnePlaceStatesHowManyRunewordsExist(unittest.TestCase):
    """v2104 — his DAILY TASK FORCE read "complete at 99/100".

    The panel was RIGHT: it prints `fs.chron.total`, derived from
    `Object.keys(RUNEWORD_TIP).length` = 99. The 100 came from the AI PROMPT, which
    told Sonnet in words that the denominator was `snapshot.chronicle made/100` — so
    the model wrote a sentence around a number the app never believed. Four rendered
    surfaces printed the same literal, and three more carried it as a fallback.

    Measured live: RUNEWORD_TIP holds 99 keys; RUNEWORDS holds 101 rows / 100 distinct
    names, and the extra name is "Death's Web" — a UNIQUE listed for reference.

    A total hardcoded in one place and derived in another is exactly how the two drift.
    [[label-outlived-referent]] [[unknown-stays-unknown]]
    """

    def setUp(self):
        with open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as f:
            self.board = f.read()
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()

    def test_the_prompt_does_not_hand_the_model_a_denominator(self):
        self.assertNotIn(
            "made/100", self.board,
            "the AI prompt states the runeword denominator as a literal again — the model "
            "will write a sentence around it, which is exactly how '99/100' reached his panel",
        )

    def test_there_is_one_source_and_it_is_the_roster(self):
        self.assertIn("window._rwTotalN = function()", self.board,
                      "the single-source runeword total helper is gone")
        # every reader must go through it, not re-derive with a literal floor
        self.assertNotIn(
            "Object.keys(RUNEWORD_TIP).length:100", self.board,
            "a reader falls back to a literal 100 again. An invented denominator is worse "
            "than none: at 99 made, `_mN === _tot` would be false and the CHRONICLE COMPLETE "
            "moment — the one that branch exists to fire — would be suppressed",
        )

    def test_no_rendered_prose_claims_a_hundred(self):
        for phrase in ("100-runeword", "100 runeword", "the Chronicle's 100"):
            self.assertNotIn(
                phrase, self.board,
                "a surface still tells him the roster is 100. It is 99 — the 100th distinct "
                "name in RUNEWORDS is Death's Web, which is a unique, not a runeword",
            )

    def test_the_one_step_rows_wear_the_runewords_picture(self):
        i = self.ui.find("function hdTaskForce(")
        self.assertGreater(i, 0)
        j = self.ui.find("\n  function ", i + 1)
        body = self.ui[i:j]
        self.assertIn(
            "art: 'runes', g: '🎯'", body,
            "the ONE STEP hero is back to a raw 🎯. A ONE STEP row names a RUNEWORD, and this "
            "project already ruled 🎯 means 'nothing could be resolved' "
            "(tests/v1628_board_quality_tokens asserts it never renders on a card)",
        )
        self.assertNotIn(
            '<span class="tf-g">◈</span>', body,
            "the ONE STEP roster rows are back to a bare glyph instead of the runeword art the "
            "chronicle row two lines below already paints",
        )


class TestV2105TheHintWearsTheConsolesSkin(unittest.TestCase):
    """v2105 — Konyo: "all these tooltips are like regular windows i want them HD art
    upgraded for allround and across the platform be creative with it just like the mouse
    cursor" — and, when asked which: "the cursor mouse floating tooltips im talking about".

    v1616 already called the native box "the one thing on this console that does not look
    like this console" and replaced it FOR ITEMS. This is that ruling applied to the rest.
    v1618 settled the shape in advance: "no need to create a new one just sync the current
    one" — so it is a LANE on #itip, never a second element. [[copy-drift]]

    Measured on the pixels before this guard was written: hovering a real control gave
    `tip-say on tip-side-left`, 340x56, mono 13px, `pre-wrap`; the host title was borrowed
    so no native box could open; aria-describedby pointed at the tip; and on leaving, the
    title came back with ZERO stray [data-tip-held] left on the page.
    """

    def setUp(self):
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()

    def test_there_is_ONE_tooltip_element_not_two(self):
        # a second floating card is how the two skins drift apart
        self.assertIn(".tip-say", self.ui, "the prose lane is gone")
        self.assertEqual(
            self.ui.count("el.id = 'itip'"), 1,
            "something creates a second tooltip element; the prose lane must be a LANE on "
            "#itip, which is what v1618 asked for in as many words",
        )

    def test_the_native_box_is_suppressed_by_REMOVING_the_attribute(self):
        # CSS cannot hide a native tooltip; only the absent attribute stops it opening
        self.assertIn("removeAttribute('title')", self.ui,
                      "nothing removes `title`, so the OS grey box still opens over the skin")
        self.assertIn("data-tip-held", self.ui,
                      "the borrowed title is not parked anywhere — a stuck steal would be "
                      "invisible and unassertable")

    def test_the_title_is_BORROWED_and_always_given_back(self):
        # _between, not a byte count: this file's own ratchet forbids new byte-counted
        # slices, and it is right to — a window a later comment outgrows comes back empty,
        # and assertNotIn PASSES on an empty string. [[source-reading-guard]]
        body = _between(self, self.ui, "release: function()", "hide: function()",
                        what="the release path")
        self.assertIn("setAttribute('title'", body, "release does not restore the title")
        self.assertIn("hasAttribute('title')", body,
                      "release does not check first, so it can clobber a title that a "
                      "re-render already put back")
        # every exit path must run it
        _binder = _between(self, self.ui, "function _itipBind()", "\n  })();",
                           what="the console tooltip binder")
        for hook in ("pagehide", "focusout", "Escape"):
            # v2120 (#99) — SCOPE IT TO THE BINDER. 'Escape' occurs 16 times in control_ui.html,
            # so deleting the tooltip's own keydown listener left this green. Its v2109 sibling
            # already scopes the identical loop to the lane body. [[source-reading-guard]]
            self.assertIn(hook, _binder, "the %s exit path is gone" % hook)

    def test_screen_readers_and_keyboards_are_not_worse_off(self):
        self.assertIn("aria-describedby", self.ui,
                      "the tip is shown without describing its anchor to assistive tech")
        self.assertIn("_itemTip.say(hint, true)", self.ui,
                      "focus does not open the tip. A native tooltip never opens on focus in "
                      "any browser, so this path is the one thing sighted keyboard users GAIN "
                      "— and it must never steal the attribute, because no native box is racing it")

    def test_the_item_card_wins_over_the_prose_lane(self):
        # 672 elements on the board carry BOTH an item anchor and a title
        body = _between(self, self.ui,
                        "var node = e.target && e.target.closest && e.target.closest('[data-itip]');",
                        "}, true);", what="the mousemove handler")
        a, b = body.find("_itemTip.show(node)"), body.find("_itemTip.say(hint")
        self.assertGreater(a, -1, "the item lane is gone from the handler")
        self.assertGreater(b, -1, "the prose lane is gone from the handler")
        self.assertLess(a, b, "the prose lane is consulted before the item card, so an element "
                              "carrying both would get the sentence instead of its item card")
        self.assertIn("iframe,html,body", self.ui,
                      "the board iframe is not excluded — #tvd-eng covers the whole pane and its "
                      "own title would fire the moment the pointer crossed it")


class TestV2107TheDrawerOpensWHEREHeCanSeeIt(unittest.TestCase):
    """v2107 — Konyo, for the third time about this panel: "advanced settings is still not
    rendering when clicked on.. nothing collapses it shows an arrow down.. but nothing there."

    It WAS rendering, in full, below the fold. Measured at the size control_app.py actually
    creates the window (1120x660): the rail is 490px tall holding 1,191px of content, so with
    the drawer open `g5-eyes-card` landed at y=510 and `shadow-adv` at y=752 — against a
    viewport that ends at 660. v2076 anticipated this and added a scrollIntoView, but chose
    `block:'nearest'` "so it moves the least it can", and for a card one pixel inside the
    viewport the least is one pixel. Nothing moved and the panel read as empty.

    After `block:'start'`, at the same 1120x660: the card is at y=180 with all 188px visible
    and the switches at y=422 with all 96px visible. [[visual-regression-detector]]
    """

    def setUp(self):
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()

    def test_opening_ADVANCED_brings_it_to_the_top_not_merely_nearest(self):
        body = _between(self, self.ui, "window._advOpened = function", "\n  };",
                        what="the ADVANCED open handler")
        code = re.sub(r"/\*.*?\*/", " ", body, flags=re.S)
        # A RATIO IS THE WRONG BOUND HERE. This handler is deliberately ~80% explanation, so
        # "code must be >25% of the block" fails on a correct strip. What actually needs proving
        # is that the strip left executable code behind, not how much prose it removed.
        self.assertGreater(len(code.strip()), 80,
                           "the comment strip left almost nothing — it ate the handler")
        self.assertIn("function", code, "the strip removed the handler itself, not its comments")
        self.assertNotIn(
            "block: 'nearest'", code,
            "back to `nearest`, which moves the least it can — at his 1120x660 window that is "
            "nothing, and the drawer opens entirely below the fold while looking empty",
        )
        # v2113 — AND IT MUST NOT DEPEND ON scrollIntoView's OPTIONS BAG. His console is a
        # pywebview window, so the engine is WebKit; every check of this panel was run in
        # headless CHROME, where both v2076's `nearest` and v2107's `start` behave. He reported
        # the same empty drawer THREE times against builds that measured correct on my side.
        # Assigning scrollTop is the flattest thing there is and no engine has an opinion
        # about it. [[test-venue]]
        self.assertIn("scrollTop =", code,
                      "the drawer is back to asking scrollIntoView to place it — that is the "
                      "call whose behaviour differs between his WebKit window and my Chrome")
        self.assertIn("overflowY", code,
                      "nothing finds the scrolling ancestor, so the scroll would be applied to "
                      "the wrong box or to nothing at all")


class TestV2107ItFetchesItselfButAsksBeforeRestarting(unittest.TestCase):
    """v2107 — Konyo, watching the banner report a version skew: "cant it automate that too
    and auto update?"

    It can, and the two halves are NOT equally safe. The PULL is fast-forward-only on a clean
    tree, touches nothing running, and is undone by a checkout — asking him to press a button
    to fetch bytes was ceremony. The RELAUNCH replaces the process, and control_app's own
    `drift_may_relaunch()` already spells out why that must not be automatic: it refuses while
    a sweep is reading, while a mini is recording, and while the agent is alive — "the one that
    means HE IS FILMING. Restarting then both interrupts the session and ORPHANS the frames of
    the session it kills."
    """

    def setUp(self):
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()
        with open(os.path.join(HERE, "control_app.py"), encoding="utf-8") as f:
            self.app = f.read()

    def test_it_pulls_without_being_asked(self):
        # ⚠ v2248 — THIS USED THE LATCH AS ITS EVIDENCE, which is a proxy for the thing it cares
        # about. The law is "a pull fires with nobody clicking", and the proof of that is a POST to
        # /api/update inside the polling function itself, not the presence of any particular flag.
        # [[feedback-verify-not-proxy]]
        i = self.ui.index("async function look()")
        body = self.ui[i:self.ui.index("\n    look();", i)]
        self.assertIn("'/api/update', { method: 'POST' }", body,
                      "the automatic pull is gone from the poll — he is back to pressing a button "
                      "to fetch bytes")
        self.assertIn("a newer console is on GitHub — fetching it…", self.ui,
                      "nothing tells him a fetch is happening on its own")

    def test_a_repeating_pull_still_CANNOT_spin(self):
        """v2248 — PIN THE LAW, NOT THE MECHANISM.

        This test used to assert `pulledThisSession = true`, i.e. once per launch. v2107 was right
        about the risk — "a checker that re-pulls every tick is a loop, not an update" — and wrong
        that once-per-launch was the cure. That latch is precisely what left Dean's console 85
        versions behind: the 30-minute check kept reporting "N behind" and nothing was allowed to
        act on it, so the disk never changed and auto-relaunch, which watches the disk, waited
        forever.

        What actually prevents a spin is not the latch. It is that a pull needs NEWS and needs
        TIME: it only fires when the server says behind > 0, on a clean tree, and never twice
        inside the cooldown. A pull that changes nothing leaves `behind` at 0, so the next check
        does not pull. v2107's protection survives; its implementation does not.
        [[regression-guard]] [[label-outlived-referent]]"""
        self.assertNotIn("pulledThisSession", self.ui,
                         "the once-per-launch latch is back — a console left open will never put "
                         "a new build on disk")
        self.assertIn("PULL_COOLDOWN_MS", self.ui, "nothing bounds how often a pull may fire")
        self.assertIn("lastPullMs", self.ui, "the cooldown has no clock to compare against")
        i = self.ui.index("lastPullMs) > PULL_COOLDOWN_MS")
        guard = self.ui[self.ui.rindex("if (", 0, i):i]
        self.assertIn("!j.dirty", guard,
                      "the repeating pull no longer refuses on a dirty tree — it could clobber "
                      "uncommitted work on the one machine that edits")

    def test_the_RESTART_is_still_his_click(self):
        self.assertIn("'/api/relaunch'", self.ui, "the relaunch action is gone from the banner")
        self.assertIn("stage === 'ready'", self.ui,
                      "the button no longer distinguishes 'fetch it' from 'run it'")
        # and the safety that makes this defensible must still exist server-side
        self.assertIn("def drift_may_relaunch", self.app,
                      "the gate that refuses to restart while he is filming is gone")
        # ⚠ v2210 — THE FIFTH SITE STILL SAYING "OPT-IN". v2153 armed auto-relaunch ON BY DEFAULT
        # at his own repeated request; the other four were two launcher comments and two of my own.
        # A label that outlived its referent reads as a rule and is a fossil. [[label-outlived-referent]]
        self.assertIn("TV_AUTO_RELAUNCH", self.app,
                      "the env override is gone — he would have no way to force auto-relaunch on "
                      "or off from outside the console")
        # and the switch he can actually reach, which is the half that did not exist until v2210
        self.assertIn('if path == "/api/auto_relaunch":', self.app,
                      "the auto-relaunch route is gone — auto_relaunch_set goes back to having no "
                      "caller and he goes back to having no way to turn it off")

    def test_a_torn_connection_reads_as_success_not_failure(self):
        # execv kills the socket mid-reply; treating that as an error would tell him the
        # relaunch failed at the moment it worked
        # ANCHOR ON THE BRANCH, NOT THE NAME. `stage === 'ready'` now appears TWICE — v2110
        # added an early-return with the same test inside look() — so `find()` landed on the
        # first mention and sliced a region that never contained the relaunch code at all.
        # That is exactly the failure _between's own comment records ("an anchor that matched
        # the FIRST mention of a name instead of its definition, twice"): the helper reports a
        # missing needle honestly, but it cannot know I aimed it at the wrong occurrence.
        # The trailing brace is unique to the branch. [[source-reading-guard]]
        body = _between(self, self.ui, "stage === 'ready'){", "go.disabled = false;",
                        what="the relaunch branch")
        self.assertIn("relaunching…", body,
                      "the catch no longer reports the torn connection as the relaunch it is")




class TestV2109TheBoardHintWearsTheSameSkin(unittest.TestCase):
    """v2109 — the board half of the ask: "across the platform".

    v2105 replaced the OS grey box on the CONSOLE. This does the board, on #arttip, as a
    second SKIN on the card that already exists — v1618's ruling, "no need to create a new
    one just sync the current one". Not one line of the item driver changed: it is scarred
    code (v654's compact-anchor rule, v171's orphan-scroll fix, v441's orb mirror), so the
    prose lane is a separate listener on the same element.

    Verified on the pixels before this was written: `tip-say on tip-side-left` at z-index
    100002, the title borrowed and returned with zero strays, and an element carrying BOTH a
    data-arttip and a title correctly rendering `tip-rich tip-r-unique` with the prose lane
    deferring and the title left intact.
    """

    def setUp(self):
        with open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as f:
            self.board = f.read()

    def test_it_is_the_SAME_card_not_a_second_one(self):
        self.assertIn(".tip-say", self.board, "the board prose lane is gone")
        self.assertIn("#arttip.tip-say", self.board,
                      "the prose lane no longer rides #arttip — a second floating element is how "
                      "the two skins drift apart")

    def test_it_opens_ABOVE_the_theatre(self):
        # .tvz-theatre computes 99991 and holds titled controls of its own; the item lane's
        # 9999 would put the sentence BEHIND the thing it describes
        m = re.search(r"#arttip\.tip-say\{[^}]*z-index:(\d+)", self.board)
        self.assertIsNotNone(m, "the prose lane declares no z-index of its own")
        self.assertGreater(int(m.group(1)), 99991,
                           "the prose lane sits below .tvz-theatre, so it would open behind the "
                           "theatre whose controls it is describing")

    def test_it_defers_to_the_item_card_BY_SELECTOR_not_by_timing(self):
        body = _between(self, self.board, "function _proseLane()", "\n    })();",
                        what="the board prose lane")
        self.assertIn("window.ARTTIP_SEL", body,
                      "the prose lane no longer asks the item selector. 672 elements carry BOTH a "
                      "data-arttip and a title; deciding by whether the card happens to be `.on` "
                      "would flip depending on whether mouseout beat mouseover")
        self.assertIn("window.ARTTIP_SEL = ARTTIP_SEL", self.board,
                      "the item selector is no longer published, so the prose lane cannot defer "
                      "without copying it — and a copied selector drifts the first time an anchor "
                      "is added to one and not the other")

    def test_the_title_is_borrowed_and_given_back(self):
        body = _between(self, self.board, "function _proseLane()", "\n    })();",
                        what="the board prose lane")
        self.assertIn("removeAttribute('title')", body,
                      "nothing removes `title`, so the OS grey box still opens over the skin — "
                      "CSS cannot suppress a native tooltip")
        self.assertIn("data-tip-held", body, "the borrowed title is parked nowhere")
        self.assertIn("hasAttribute('title')", body,
                      "release does not check first, so it can clobber a title a re-render "
                      "already put back")
        for hook in ("pagehide", "focusout", "Escape"):
            self.assertIn(hook, body, "the %s exit path is gone — a borrowed title could strand" % hook)


class TestV2110UpToDateIsNotTheSameAsRunningIt(unittest.TestCase):
    """v2110 — the banner answered the wrong question on the one machine that matters most.

    `behind` counts commits against origin. On the machine where the tree is EDITED that is
    permanently 0, while the running process can be several ships stale — which is exactly the
    state Konyo photographed: the footer read "CONSOLE V2105, AGENT V2106, BOARD V2106 —
    RELAUNCH" while the fleet banner, the one surface carrying a RELAUNCH button, stayed
    hidden because `behind === 0`.

    The console has measured this since v2072 (`status.drift`: "the process is serving Python
    it has never executed") and printed it in the footer. The banner simply never asked.
    Plumbing built on both ends and not joined. [[the-unjoined-end]]

    Verified against the LIVE console at v2107-running / v2109-on-disk: the banner reads
    "v2109 is on disk — this window is still running the old one" with RELAUNCH NOW.
    """

    def setUp(self):
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()
        with open(os.path.join(HERE, "control_app.py"), encoding="utf-8") as f:
            self.app = f.read()

    def test_a_zero_behind_count_does_not_end_the_check(self):
        body = _between(self, self.ui, "if (!j || !j.ok || !j.behind){", "bar.hidden = true; return;",
                        what="the up-to-date branch of the fleet check")
        self.assertIn("/api/status", body,
                      "the banner gives up as soon as it is level with GitHub, which on his own "
                      "machine is always — and never notices the process is running old code")
        # v2120 (#109) — STRIP THE PROSE. The v2110 comment inside this window says "status.drift",
        # so one of the three hits was the paragraph describing the branch. Its TestV2107 sibling
        # already strips. [[feedback-comments-vs-code]]
        _code = re.sub(r"/\*.*?\*/", " ", body, flags=re.S)
        self.assertGreater(len(_code.strip()), 120, "the comment strip ate the branch body")
        self.assertIn("drift", _code, "the banner does not consult the running-vs-disk measurement")
        self.assertIn("armRelaunch", body,
                      "a detected drift no longer offers the relaunch that resolves it")

    def test_the_measurement_it_depends_on_still_exists(self):
        self.assertIn("def drift_state", self.app,
                      "drift_state() is gone — the banner would silently stop noticing stale runs")
        self.assertTrue(_status_producer(self, self.app, "drift_state", key="drift"),
                      "drift is no longer published on /api/status, so the banner cannot read it")


class TestV2111TheQueueWasRightAboutFour(unittest.TestCase):
    """v2111 — four findings from the review queue, verified before acting on them and all
    four real. Two were defects I shipped tonight, and one was a file I never swept.

    1. /api/relaunch refused on three job flags but NOT on `_agent_alive()` — while
       `drift_may_relaunch()`, the AUTOMATIC path, checks it and says why: restarting then
       "ORPHANS the frames of the session it kills". The two paths guarded different things
       and the WEAKER one is the one v2107 put a button on.
    2. #g5-eyes-card shipped with the `hidden` attribute. v2103 made paintG5 always reveal
       it — but that only runs after the first /api/g5_status answers, so a slow or failed
       first load still opened an empty drawer.
    3. .home-dash reserved a scrollbar gutter it no longer needed once v2103 shrink-wrapped
       it — 15px of dead stripe, the remainder of the gap he reported.
    4. functions/api/ask.js — a SECOND prompt for the same model — still told it the
       Chronicle was out of 100, twice. v2104 fixed the board's prompt; I swept bible.html
       and the console for the literal and never thought to sweep the Cloudflare function.
    """

    def setUp(self):
        with open(os.path.join(HERE, "control_app.py"), encoding="utf-8") as f:
            self.app = f.read()
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()

    def test_relaunch_refuses_while_he_is_filming(self):
        """⚠⚠ REWRITTEN v3302, FROM TEXT TO BEHAVIOUR — and the rewrite is the stronger test.

        This read the route's source for `_agent_alive()`. v3301 collapsed the route's duplicate
        busy list into nothing_in_flight(), so the symbol left the route and this went red over a
        change that made the guarantee STRONGER, not weaker: the route now reaches the filming
        check through the one definition, which additionally handles the stale-mode case the
        route's own copy got wrong (a crashed agent left `_agent_mode` at "live" with no
        `_agent_alive()` test, deadlocking the BUTTON forever — REG-1115).

        The rule was never "this file contains that symbol". It is "a relaunch is refused while
        he is filming, because the reel fold runs at seal and replacing the process orphans that
        session's frames". So drive it: put the console ON AIR and require a refusal that says so.
        A behavioural test cannot be satisfied by a comment, which is the failure mode the old
        prose-strip below was defending against. [[source-reading-guard]] §1"""
        import unittest.mock as mock
        sys.path.insert(0, HERE)
        import control_app as ca

        with mock.patch.object(ca, "_agent_mode", "live"), \
             mock.patch.object(ca, "_agent_alive", lambda *a, **k: True):
            ok, why = ca.nothing_in_flight("relaunch the console")
        self.assertFalse(
            ok,
            "a relaunch was ALLOWED while the console is ON AIR. It replaces the process, and the "
            "reel fold runs at seal (v2071) — so restarting mid-session ORPHANS that session's "
            "frames, with no parent left to seal the reel. why=%r" % why)
        self.assertIn("filming", why,
                      "the refusal does not tell him he is filming, so the reason he cannot "
                      "relaunch is invisible: %r" % why)

        # ⚠ AND THE OTHER DIRECTION, or the assertion above is satisfied by a guard that refuses
        # everything. A mode label with no live process must NOT hold the door — that stale-mode
        # deadlock is exactly what left the button dead after a crash.
        with mock.patch.object(ca, "_agent_mode", "live"), \
             mock.patch.object(ca, "_agent_alive", lambda *a, **k: False), \
             mock.patch.object(ca, "_reel_is_growing", lambda *a, **k: False):
            ok2, why2 = ca.nothing_in_flight("relaunch the console")
        self.assertTrue(
            ok2,
            "a STALE 'live' mode with no process behind it still refused the relaunch. "
            "`_agent_mode` is written only by start/stop, so after a crash it stays 'live' "
            "forever — and this is the door he uses to RECOVER from that crash. why=%r" % why2)

        # and the route must still be the thing that asks
        route = _between(self, self.app, 'path == "/api/relaunch"', 'if path == "/api/',
                         what="the relaunch route", min_len=200)
        code = "\n".join(ln for ln in route.splitlines() if not ln.lstrip().startswith("#"))
        self.assertIn('nothing_in_flight("relaunch the console")', code,
                      "/api/relaunch no longer asks nothing_in_flight, so the behaviour proven "
                      "above is not reached by the button he presses. [[the-unjoined-end]]")

    def test_the_eyes_card_does_not_ship_hidden(self):
        i = self.ui.find('id="g5-eyes-card"')
        self.assertGreater(i, 0, "the Grok Eyes card is gone")
        tag = self.ui[i:self.ui.find(">", i)]
        self.assertNotIn(
            " hidden", tag,
            "the card ships hidden again, so it only appears once a fetch answers — the drawer "
            "opens empty on a slow or failed first load, which is the complaint v2103 closed",
        )

    def test_the_dash_does_not_reserve_a_gutter_it_does_not_need(self):
        self.assertIn(".home-dash { scrollbar-gutter: auto; }", self.ui,
                      "the dash reserves a scrollbar gutter again — 15px of dead stripe down its "
                      "full height whether or not it overflows")
        # the surfaces that DO scroll routinely must keep theirs, or their layout jumps
        self.assertIn(".rail, .ch-grid, .sh-grid { scrollbar-gutter: stable; }", self.ui,
                      "the routinely-scrolling panels lost their reservation; their layout will "
                      "jump each time a scrollbar appears")

    def test_the_cloudflare_prompt_states_no_denominator(self):
        ask = os.path.join(os.path.dirname(HERE), "functions", "api", "ask.js")
        self.assertTrue(os.path.isfile(ask), "functions/api/ask.js is gone")
        with open(ask, encoding="utf-8") as f:
            src = f.read()
        for bad in ("N/100", "100-runeword"):
            self.assertNotIn(
                bad, src,
                "the Cloudflare prompt tells the model the Chronicle roster is 100. It is 99, "
                "and the app already sends the real number in snapshot.chronicle — the model "
                "will write a fluent sentence around whatever denominator it is handed",
            )


class TestV2113TheBridgeCacheKeySeesTheCrafts(unittest.TestCase):
    """v2113 — the v1862 defect, re-opened by my own v2101, by the exact route v1862 named.

    `_fsCmp` decides whether `d2r_forgeSummary` is REWRITTEN at all — "write ONLY on real
    change". Until v2101 the ready crafts rode inside `now`, and `now9`, the SORTED NAMES,
    was part of the signature. v2101 gave crafts their own channel (rightly — they were
    being drawn twice) and left behind only `c9.crafts`, a COUNT. Six ready crafts becoming
    six DIFFERENT ready crafts then produced an identical signature, the bridge was never
    rewritten, and FORGE QUESTS kept showing crafts he had already made.

    v1862's own words, about the sets count: "A cache key that omits the value it is
    caching is not a cache key."

    THIS RUNS THE COMPARATOR, it does not grep it. A structural check would pass on a
    version that mentions `crafts` and still compares nothing.
    """

    def test_a_same_count_craft_swap_changes_the_signature(self):
        import subprocess, tempfile, json as _j
        node = shutil.which("node")
        if not node:
            self.skipTest("node is not on PATH — the comparator cannot be executed here")
        board = os.path.join(os.path.dirname(HERE), "bible.html")
        with open(board, encoding="utf-8") as f:
            src = f.read()
        i = src.find("var _fsCmp = function(x)")
        self.assertGreater(i, 0, "the bridge comparator is gone")
        j = src.find("if (_fsCmp(_fsOld)", i)
        self.assertGreater(j, i, "could not find the end of the comparator")
        body = src[i:j].strip().rstrip(";")

        script = """
const _fsCmp = %s;
const base = { now:['Insight'], pipeline:[], onestep:[{rw:'Fortitude',sub:'runes'}],
  counts:{now:1,deferred:0,pipeline:0,onestep:1,crafts:3},
  grail:{found:278,total:403}, chron:{made:60,total:99}, sets:{found:121,total:135},
  crafts:[{name:'Caster Amulet'},{name:'Caster Ring'},{name:'Blood Belt'}],
  craftOnestep:[{name:'Safety Boots',missing:'Ral'}] };
const swap = JSON.parse(JSON.stringify(base));
swap.crafts = [{name:'Blood Gloves'},{name:'Hit Power Helm'},{name:'Safety Shield'}];
const order = JSON.parse(JSON.stringify(base));
order.crafts = [base.crafts[2], base.crafts[0], base.crafts[1]];
const step = JSON.parse(JSON.stringify(base));
step.craftOnestep = [{name:'Safety Boots',missing:'Ort'}];
console.log(JSON.stringify({
  swapSeen: _fsCmp(base) !== _fsCmp(swap),
  orderStable: _fsCmp(base) === _fsCmp(order),
  stepSeen: _fsCmp(base) !== _fsCmp(step),
}));
""" % body.replace("var _fsCmp = ", "", 1)

        with tempfile.NamedTemporaryFile("w", suffix=".mjs", delete=False, encoding="utf-8") as fh:
            fh.write(script)
            path = fh.name
        try:
            out = subprocess.run([node, path], capture_output=True, text=True, timeout=30)
            self.assertEqual(out.returncode, 0,
                             "the comparator would not execute: %s" % (out.stderr or "")[-200:])
            r = _j.loads(out.stdout.strip().splitlines()[-1])
        finally:
            os.unlink(path)

        self.assertTrue(r["swapSeen"],
                        "three ready crafts becoming three DIFFERENT ready crafts leaves the "
                        "signature IDENTICAL — the bridge is never rewritten and the console "
                        "keeps showing crafts he has already made")
        self.assertTrue(r["orderStable"],
                        "merely REORDERING the same crafts changes the signature, which rewrites "
                        "the bridge on every scan and breaks the byte-identity invariant v903.1 "
                        "and the ladder bleed-proof both depend on")
        self.assertTrue(r["stepSeen"],
                        "a one-step craft needing a DIFFERENT rune leaves the signature identical")


class TestV2114ABorrowedTitleStaysBorrowed(unittest.TestCase):
    """v2114 — Konyo, with both tooltips on screen at once: "the tooltip in the bottom i want
    HD art only not double, one is rendering a regular OS message box."

    The element was #foot-ver, whose `title` the console REWRITES on its own poll (~:7418,
    the version-skew line). The sequence: hover -> the prose lane steals the title -> the poll
    puts it back a second later -> the native box is eligible again -> both render, ours
    anchored and the grey one under the cursor.

    Borrowing an attribute from a surface that repaints itself is not a one-time act. Both
    lanes now watch the attribute for the length of the hover and re-take it, keeping the
    NEWEST wording so the bubble cannot go stale either.

    Verified on the LIVE console: title still borrowed after ~7s of repaints, restored on
    leave, zero stray [data-tip-held].
    """

    def setUp(self):
        with open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as f:
            self.ui = f.read()
        with open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as f:
            self.board = f.read()

    def test_both_surfaces_watch_the_attribute(self):
        for src, who in ((self.ui, "the console"), (self.board, "the board")):
            self.assertIn(
                "attributeFilter: ['title']", src,
                "%s stops watching the borrowed title. A surface that repaints itself hands the "
                "attribute back mid-hover and the OS grey box opens on top of the skinned one — "
                "which is exactly what he photographed" % who,
            )
            self.assertIn("MutationObserver", src, "%s has no observer for the steal" % who)

    def test_the_observer_is_disconnected_on_release(self):
        # an observer that outlives the hover keeps stealing from an element nobody is on
        for src, who in ((self.ui, "the console"), (self.board, "the board")):
            i = src.find("release: function()")
            if i < 0:
                i = src.find("function release()")
            self.assertGreater(i, 0, "%s has no release path" % who)
            # v2116 — _between, not a byte count: this file's own ratchet forbids new
            # byte-counted slices, and it is right to. A window a later comment outgrows comes
            # back short, and assertIn on a short slice fails for the wrong reason.
            end = "say: function(" if "say: function(" in src[i:] else "function say("
            body = _between(self, src[i:], "release", end, what="%s release path" % who)
            self.assertIn("disconnect()", body,
                          "%s never disconnects the observer, so it keeps re-stealing the title "
                          "of an element the pointer has already left" % who)

    def test_the_re_steal_keeps_the_newest_wording(self):
        # the repaint usually means the SENTENCE changed; showing the old one is a stale reading
        for src, who in ((self.ui, "the console"), (self.board, "the board")):
            self.assertIn("held = back", src.replace("sayHeld", "held"),
                          "%s re-steals but keeps the ORIGINAL text, so the bubble would show a "
                          "sentence the surface has already replaced" % who)




class TestReg1871ATitleAboveTheHostIsBorrowedToo(unittest.TestCase):
    """REG-1871 — A TITLE ABOVE THE HOVERED WORD OPENED THE NATIVE BOX ANYWAY. The prose lane takes the hovered
    word's title so the browser has nothing to show; its nearest titled ANCESTOR was then the title the browser
    asked, and the grey box opened over the skinned bubble (the fleet row's REG-1828 was one of these). Counted in
    the static markup alone: 7 titled elements sit inside another titled element. The lane now borrows every title
    above the host for the same hover and gives each back on release.

    Drives the SHIPPED _itemTip in node over a fake DOM (no browser), including one chain per static nested pair
    read from the real markup. [[the-unjoined-end]] [[source-reading-guard]]"""

    HARNESS = r"""
function El(tag, attrs){ this.tagName = tag; this.attrs = {}; for (var k in (attrs || {})) this.attrs[k] = String(attrs[k]);
  this.parentElement = null; this.isConnected = true; this.style = { removeProperty: function(){} }; var self = this, cls = {};
  this.classList = { add: function(){ for (var i = 0; i < arguments.length; i++) cls[arguments[i]] = 1; },
                     remove: function(){ for (var i = 0; i < arguments.length; i++) delete cls[arguments[i]]; },
                     toggle: function(c, on){ if (on === undefined ? !cls[c] : on) cls[c] = 1; else delete cls[c]; },
                     contains: function(c){ return !!cls[c]; } };
  String(this.attrs['class'] || '').split(/\s+/).forEach(function(c){ if (c) cls[c] = 1; }); }
El.prototype.getAttribute = function(k){ return (k in this.attrs) ? this.attrs[k] : null; };
El.prototype.setAttribute = function(k, v){ this.attrs[k] = String(v); };
El.prototype.removeAttribute = function(k){ delete this.attrs[k]; };
El.prototype.hasAttribute = function(k){ return k in this.attrs; };
El.prototype.appendChild = function(c){ c.parentElement = this; return c; };
El.prototype.querySelector = function(){ return null; };
var HTML = new El('html'), BODY = new El('body'); BODY.parentElement = HTML;
var document = { body: BODY, documentElement: HTML, createElement: function(t){ return new El(t); },
                 getElementById: function(){ return null; } };
var window = { innerWidth: 1440, innerHeight: 900 };
var OBS = [];
function MutationObserver(cb){ this.cb = cb; this.targets = []; this.live = true; OBS.push(this); }
MutationObserver.prototype.observe = function(t){ this.targets.push(t); };
MutationObserver.prototype.disconnect = function(){ this.live = false; };
function setTimeout(){ return 0; } function clearTimeout(){}
function esc(s){ return String(s); }
function chain(specs){ var parent = BODY, out = [];
  specs.forEach(function(sp){ var e = new El(sp[0], sp[1]); e.parentElement = parent; parent = e; out.push(e); });
  return out; }
function titles(list){ return list.map(function(e){ return e.getAttribute('title'); }); }
function held(list){ return list.map(function(e){ return e.getAttribute('data-tip-held'); }); }
function repaint(e, t){ e.setAttribute('title', t); OBS.forEach(function(o){ if (o.live && o.targets.indexOf(e) >= 0) o.cb([]); }); }
"""

    @classmethod
    def setUpClass(cls):
        cls.node = shutil.which("node")
        with io.open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as fh:
            cls.ui = fh.read()
        start, end = "  var _itemTip = (function(){\n", "  window._itemTip = _itemTip;"
        assert cls.ui.count(start) == 1 and cls.ui.count(end) == 1, "the hint lane's anchors moved"
        i = cls.ui.index(start)
        cls.lane = cls.ui[i:cls.ui.index(end, i)]

    @staticmethod
    def _nested_pairs(src):
        """Each static titled element inside another titled one, as its chain of titled ancestors. -> [[[tag, title]]]
        Scripts and styles are skipped, so JS-built markup is not seen: a count of the STATIC markup only."""
        from html.parser import HTMLParser

        class _P(HTMLParser):
            VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "source", "wbr"}

            def __init__(self):
                super().__init__()
                self.stack, self.pairs, self.skip = [], [], 0

            def handle_starttag(self, tag, attrs):
                if tag in ("script", "style"):
                    self.skip += 1
                    return
                if self.skip:
                    return
                a = dict(attrs)
                if "title" in a and any(t for _, t in self.stack):
                    self.pairs.append([[x, t] for x, t in self.stack if t] + [[tag, a["title"]]])
                if tag not in self.VOID:
                    self.stack.append((tag, a.get("title")))

            def handle_endtag(self, tag):
                if tag in ("script", "style"):
                    self.skip = max(0, self.skip - 1)
                    return
                if self.skip:
                    return
                for k in range(len(self.stack) - 1, -1, -1):
                    if self.stack[k][0] == tag:
                        del self.stack[k:]
                        break
        p = _P()
        p.feed(src)
        return p.pairs

    def _run(self, body):
        if not self.node:
            self.skipTest("node is not installed — the shipped lane cannot be driven here (UNKNOWN, not a pass)")
        prog = self.HARNESS + self.lane + ";(function(){ var OUT = {};\n" + body + \
            "\nprocess.stdout.write(JSON.stringify(OUT)); })();\n"
        r = subprocess.run([self.node, "-"], input=prog, capture_output=True, text=True, timeout=60)
        self.assertEqual(r.returncode, 0, "the shipped hint lane would not run: %s" % r.stderr[-900:])
        return json.loads(r.stdout)

    def test_every_title_above_the_host_is_borrowed_and_given_back(self):
        o = self._run("""
var c = chain([['div', {title: 'the row'}], ['span', {}], ['div', {title: 'the card'}], ['b', {title: 'the word'}]]);
_itemTip.say(c[3], false);
OUT.during = titles(c); OUT.heldDuring = held(c);
_itemTip.hide();
OUT.after = titles(c); OUT.heldAfter = held(c);""")
        self.assertEqual(o["during"], [None, None, None, None],
                         "a title stayed on the hovered word's chain, so the native box opens over the bubble: %r"
                         % o["during"])
        self.assertEqual(o["heldDuring"], ["the row", None, "the card", "the word"])
        self.assertEqual(o["after"], ["the row", None, "the card", "the word"], "a borrowed title was not given back")
        self.assertEqual(o["heldAfter"], [None, None, None, None], "a stray data-tip-held is left at rest")

    def test_an_ancestor_that_repaints_mid_hover_is_retaken_with_its_newest_words(self):
        o = self._run("""
var c = chain([['div', {title: 'v1 of the row'}], ['b', {title: 'the word'}]]);
_itemTip.say(c[1], false);
repaint(c[0], 'v2 of the row');
OUT.during = titles(c);
_itemTip.hide();
OUT.after = titles(c);""")
        self.assertEqual(o["during"], [None, None], "a repainted ancestor title opened the native box mid-hover")
        self.assertEqual(o["after"], ["v2 of the row", "the word"], "release gave back a stale ancestor sentence")

    def test_moving_onto_the_ancestor_says_the_ancestor(self):
        o = self._run("""
var c = chain([['div', {title: 'the row'}], ['b', {title: 'the word'}]]);
_itemTip.say(c[1], false);
_itemTip.say(c[0], false);
OUT.during = titles(c); OUT.heldDuring = held(c);
_itemTip.hide();
OUT.after = titles(c);""")
        self.assertEqual(o["during"], [None, "the word"], "the word was not given back when the pointer moved up")
        self.assertEqual(o["heldDuring"], ["the row", None])
        self.assertEqual(o["after"], ["the row", "the word"])

    def test_focus_borrows_nothing(self):
        o = self._run("""
var c = chain([['div', {title: 'the row'}], ['b', {title: 'the word'}]]);
_itemTip.say(c[1], true);
OUT.during = titles(c);""")
        self.assertEqual(o["during"], ["the row", "the word"], "focus opens no native box, so nothing may be taken")

    def test_every_nested_pair_in_the_static_markup_is_covered(self):
        """The count, before and after: each static titled element inside another titled one, rebuilt as its real
        chain of titled ancestors and hovered."""
        pairs = self._nested_pairs(self.ui)
        # GrokBot tick 371 named this one: "GROK ONLY" (#btn-g5-only) inside the titled #g5-eyes-card
        self.assertTrue(any(pr[-1][1].startswith("Grok reads every frame")
                            and any(t.startswith("Optional Grok vision lane") for _, t in pr[:-1]) for pr in pairs),
                        "the GROK ONLY button inside the eyes card is not among the pairs this drives")
        self.assertGreaterEqual(len(pairs), 7, "the static nested pairs were not found — this grades nothing")
        o = self._run("""
var pairs = %s; OUT.left = [];
pairs.forEach(function(pr){
  var c = chain(pr.map(function(x){ return [x[0], {title: x[1]}]; }));
  _itemTip.say(c[c.length - 1], false);
  var t = titles(c).filter(function(v){ return v !== null; });
  if (t.length) OUT.left.push(t);
  _itemTip.hide();
});
OUT.n = pairs.length;""" % json.dumps(pairs))
        self.assertEqual(o["n"], len(pairs))
        self.assertEqual(o["left"], [], "%d of %d nested pairs still hand the browser a title while hovered"
                         % (len(o["left"]), o["n"]))

    def test_the_board_lane_borrows_the_titles_above_too(self):
        """The board carries its own prose lane (bible.html _proseLane), the same rule, driven through its own
        mouseover listener. 16 nested pairs sit in the board's static markup."""
        if not self.node:
            self.skipTest("node is not installed — the shipped lane cannot be driven here (UNKNOWN, not a pass)")
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            board = fh.read()
        start = "    (function _proseLane(){\n"
        self.assertEqual(board.count(start), 1, "the board's prose lane moved")
        i = board.index(start)
        lane = board[i:board.index("\n    })();", i) + len("\n    })();")]
        # the lane borrows through arttipInit's shared pair (REG-1871): lift the SHIPPED helpers, never a copy
        h0 = board.index("    function _tipBorrowAbove(node, into){\n")
        h1 = board.index("\n    }\n", board.index("    function _tipGiveBack(list){\n", h0)) + len("\n    }\n")
        lane = board[h0:h1] + lane
        prog = self.HARNESS + r"""
El.prototype.closest = function(sel){
  for (var e = this; e && e !== BODY && e !== HTML; e = e.parentElement)
    if (e.hasAttribute('title') || e.hasAttribute('data-tip-held')) return e;
  return null; };
El.prototype.matches = function(sel){ return /^(iframe|html|body)$/.test(this.tagName); };
var LIS = {};
document.addEventListener = function(k, f){ (LIS[k] = LIS[k] || []).push(f); };
window.addEventListener = function(){};
var tip = new El('div');
""" + lane + """
;(function(){ var OUT = {};
var c = chain([['div', {title: 'the routine bar'}], ['span', {title: 'the letter'}]]);
LIS.mouseover.forEach(function(f){ f({ target: c[1] }); });
OUT.during = titles(c);
LIS.keydown.forEach(function(f){ f({ key: 'Escape' }); });
OUT.after = titles(c); OUT.heldAfter = held(c);
var pairs = __PAIRS__; OUT.left = [];
pairs.forEach(function(pr){
  var k = chain(pr.map(function(x){ return [x[0], {title: x[1]}]; }));
  LIS.mouseover.forEach(function(f){ f({ target: k[k.length - 1] }); });
  var t = titles(k).filter(function(v){ return v !== null; });
  if (t.length) OUT.left.push(t);
  LIS.keydown.forEach(function(f){ f({ key: 'Escape' }); });
});
OUT.n = pairs.length;
process.stdout.write(JSON.stringify(OUT)); })();
"""
        pairs = self._nested_pairs(board)
        self.assertGreaterEqual(len(pairs), 16, "the board's static nested pairs were not found — this grades nothing")
        prog = prog.replace("__PAIRS__", json.dumps(pairs))
        r = subprocess.run([self.node, "-"], input=prog, capture_output=True, text=True, timeout=60)
        self.assertEqual(r.returncode, 0, "the board's shipped lane would not run: %s" % r.stderr[-900:])
        o = json.loads(r.stdout)
        self.assertEqual(o["during"], [None, None],
                         "the board's titled ancestor stayed, so its native box opens over the bubble: %r" % o["during"])
        self.assertEqual(o["after"], ["the routine bar", "the letter"], "the board did not give a title back")
        self.assertEqual(o["heldAfter"], [None, None])
        self.assertEqual((o["n"], o["left"]), (len(pairs), []),
                         "%d of %d of the board's nested pairs still hand the browser a title" % (len(o["left"]), o["n"]))


class TestReg2116TheItemCardBorrowsLikeTheProseLane(unittest.TestCase):
    """REG-2116 (#220) - THE ITEM CARD NEVER BORROWED. `_itemTip.show()` - the [data-itip] lane - only called release():
    it gave the prose lane's titles back and never took the hovered node's own title or any title above it. So a
    [data-itip] node carrying a title, or sitting inside a titled card or row, painted the rich card with the grey OS
    box over it (GrokBot ticks 392 / 407 / 422: the eyes card, a stray 'default OFF' tip, the Accumulator LOCKED box).

    Drives the SHIPPED lane in node over REG-1871's fake DOM - the same harness, never a copy of the lane."""

    HARNESS = TestReg1871ATitleAboveTheHostIsBorrowedToo.HARNESS + r"""
var _itemArtImg = function(){ return ''; }, _rarCls = function(){ return ''; }, _pieceLabel = function(s){ return s; };
function item(){ return {'data-itip': JSON.stringify({name: 'Shako'}), title: 'the item'}; }
"""
    setUpClass = classmethod(TestReg1871ATitleAboveTheHostIsBorrowedToo.setUpClass.__func__)
    _run = TestReg1871ATitleAboveTheHostIsBorrowedToo._run

    def test_a_hover_borrows_the_item_and_every_title_above_it_and_gives_them_back(self):
        o = self._run("""
var c = chain([['div', {title: 'the card'}], ['span', {}], ['button', item()]]);
_itemTip.show(c[2]); _itemTip.show(c[2]);
OUT.during = titles(c); OUT.heldDuring = held(c);
_itemTip.hide();
OUT.after = titles(c); OUT.heldAfter = held(c);""")
        self.assertEqual(o["during"], [None, None, None],
                         "a title stayed on the item's chain, so the OS box opens over the item card: %r" % o["during"])
        self.assertEqual(o["heldDuring"], ["the card", None, "the item"])
        self.assertEqual(o["after"], ["the card", None, "the item"], "a borrowed title was not given back")
        self.assertEqual(o["heldAfter"], [None, None, None], "a stray data-tip-held is left at rest")

    def test_a_title_repainted_mid_hover_is_retaken_with_its_newest_words(self):
        o = self._run("""
var c = chain([['div', {title: 'v1 of the row'}], ['button', item()]]);
_itemTip.show(c[1]);
repaint(c[0], 'v2 of the row'); repaint(c[1], 'v2 of the item');
OUT.during = titles(c);
_itemTip.hide();
OUT.after = titles(c);""")
        self.assertEqual(o["during"], [None, None], "a repainted title opened the OS box over the item card mid-hover")
        self.assertEqual(o["after"], ["v2 of the row", "v2 of the item"], "release gave back a stale sentence")

    def test_focus_borrows_nothing_and_still_sheds_the_prose_lane(self):
        o = self._run("""
var c = chain([['div', {title: 'the card'}], ['button', item()]]);
var w = chain([['div', {title: 'a row'}], ['b', {title: 'a word'}]]);
_itemTip.say(w[1], false);
_itemTip.show(c[1], true);
OUT.item = titles(c); OUT.word = titles(w);""")
        self.assertEqual(o["item"], ["the card", "the item"], "focus opens no OS box, so nothing may be taken")
        self.assertEqual(o["word"], ["a row", "a word"], "the prose lane kept its borrowed titles under the item card")

    def test_moving_from_a_word_to_an_item_gives_the_word_back(self):
        o = self._run("""
var w = chain([['div', {title: 'a row'}], ['b', {title: 'a word'}]]);
var c = chain([['button', item()]]);
_itemTip.say(w[1], false);
_itemTip.show(c[0]);
OUT.word = titles(w); OUT.item = titles(c);""")
        self.assertEqual(o["word"], ["a row", "a word"], "the word's titles were not given back when the item card opened")
        self.assertEqual(o["item"], [None], "the item's own title stayed")


class TestReg1871ATitledControlInsideAnItemCardSpeaksForItself(unittest.TestCase):
    """REG-1871 (#189), the three sites GrokBot photographed on v3600, each a native strip over a styled box:

      1. the fleet box's river line (console): `.fs-l` reasons sit inside the titled `.fx-sys`. The nested-title
         rule (TestReg1871ATitleAboveTheHostIsBorrowedToo) covers it; driven here on the SHIPPED markup.
      2. the vault REGISTERED row's ◉ (board): a titled button inside an item-card anchor (`.vrg-row[data-arttip]`).
         The prose lane deferred to the item card for anything inside an anchor, and the card held only the
         anchor's own title, so nobody took the button's.
      3. the mule tile's "?" evidence badge (board): a titled button inside a tile window.d2Tip owns. The mule box
         already let the UNLOCK badge be the prose lane's; the evidence badge never joined it.

    One rule now for both board item lanes: a titled element strictly inside the anchor is the prose lane's, the
    card steps aside, and ONE box carries the words the pointer is on. Driven in node over a fake DOM whose closest()
    answers only the selectors the shipped code is known to pass — any other throws, so a new selector cannot slip
    through as a quiet pass. [[the-unjoined-end]]"""

    @classmethod
    def setUpClass(cls):
        cls.node = shutil.which("node")
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            cls.board = fh.read()
        b = cls.board

        def once(start, end, inclusive=True):
            assert b.count(start) == 1, "anchor moved: %r" % start[:60]
            i = b.index(start)
            j = b.index(end, i)
            return b[i:j + (len(end) if inclusive else 0)]
        cls.art_init = once("  function arttipInit(){\n", "\n  }\n  if (document.readyState==='loading') document.addEventListener('DOMContentLoaded', arttipInit);", False) + "\n  }\n"
        import re as _re
        cls.ART = _re.search(r"\n    var ARTTIP_SEL = '([^']+)';", b).group(1)
        assert b.count("e.target.closest('%s')" % cls.ART) == 1, "the art lane's own selector is not the published one"
        sel = _re.search(r"\n  var SEL = ('#vault-detail[^\n]+');\n", b)
        assert sel, "the mule window's anchor selector moved"
        cls.D2SEL = sel.group(1)[1:-1]
        cls.d2 = ("  var SEL = %s;\n" % sel.group(1)
                  + once("  window.D2TIP_OWNS = function(t){", "};\n")
                  + once("  function anchorOf(target){\n", "\n  }\n"))

    HARNESS = TestReg1871ATitleAboveTheHostIsBorrowedToo.HARNESS + r"""
var TILE = '#vault-detail .mp .vd-item[data-key], #vault-detail .mp .vd-item[data-dbkey], #vault-detail .mp .mp-slot.mp-has';
var PRED = { '[title],[data-tip-held]': function(e){ return e.hasAttribute('title') || e.hasAttribute('data-tip-held'); },
             '.vd-unlock': function(e){ return /(^| )vd-unlock( |$)/.test(e.attrs['class'] || ''); },
             '#cb-modal': function(){ return false; }, '#cb-modal .mp-pick': function(){ return false; } };
PRED[__ART__] = function(e){ return !!e.art; };
PRED[__D2SEL__] = function(e){ return !!e.mule; };
PRED[TILE] = function(e){ return !!e.tile; };
El.prototype.closest = function(sel){ var f = PRED[sel]; if (!f) throw new Error('unmapped selector: ' + sel);
  for (var e = this; e && e !== HTML; e = e.parentElement) if (f(e)) return e; return null; };
El.prototype.contains = function(o){ for (var e = o; e; e = e.parentElement) if (e === this) return true; return false; };
El.prototype.matches = function(sel){
  if (sel === 'iframe,html,body') return /^(iframe|html|body)$/.test(this.tagName);
  var f = PRED[sel]; if (!f) throw new Error('unmapped selector: ' + sel); return f(this); };
El.prototype.getBoundingClientRect = function(){ return { left: 0, top: 0, right: 100, bottom: 20, width: 100, height: 20 }; };
El.prototype.addEventListener = function(){};
var STUB = {};
El.prototype.querySelector = function(q){ return STUB[q] || (STUB[q] = new El('div')); };
Object.defineProperty(El.prototype, 'innerHTML', { set: function(){}, get: function(){ return ''; } });
El.prototype.offsetParent = BODY;
var LIS = {};
document.addEventListener = function(k, f){ (LIS[k] = LIS[k] || []).push(f); };
document.readyState = 'complete';
var MADE = [];
document.createElement = function(t){ var e = new El(t); MADE.push(e); return e; };
window.addEventListener = function(){};
function over(t){ (LIS.mouseover || []).forEach(function(f){ try { f({ target: t, buttons: 0 }); } catch (e) { OUT_ERR.push(String(e && e.message)); } }); }
function esc_(){ (LIS.keydown || []).forEach(function(f){ try { f({ key: 'Escape' }); } catch (e) {} }); }
function leave(){ (LIS.mouseleave || []).forEach(function(f){ try { f({}); } catch (e) { OUT_ERR.push(String(e && e.message)); } }); }
var OUT_ERR = [];
"""

    def _run(self, body):
        if not self.node:
            self.skipTest("node is not installed — the shipped lanes cannot be driven here (UNKNOWN, not a pass)")
        prog = (self.HARNESS.replace("__ART__", json.dumps(self.ART)).replace("__D2SEL__", json.dumps(self.D2SEL))
                + self.d2 + self.art_init + "\narttipInit();\nvar TIP = MADE[0];   // the item card arttipInit made first\n"
                + ";(function(){ var OUT = {};\n" + body + "\nOUT.err = OUT_ERR; process.stdout.write(JSON.stringify(OUT)); })();\n")
        r = subprocess.run([self.node, "-"], input=prog, capture_output=True, text=True, timeout=60)
        self.assertEqual(r.returncode, 0, "the shipped board lanes would not run: %s" % r.stderr[-900:])
        o = json.loads(r.stdout)
        self.assertEqual(o["err"], [], "a lane threw inside its listener (an unmapped selector reads as a pass "
                                       "otherwise): %r" % o["err"][:4])
        return o

    def test_the_vault_rows_button_speaks_and_the_item_card_steps_aside(self):
        o = self._run(r"""
var row = new El('div', {'data-arttip': 'Shako', 'class': 'vrg-row'}); row.art = true; row.parentElement = BODY;
var btn = new El('button', {'class': 'vrg-rcpt', title: 'why is this here? — show the frame that witnessed it'}); btn.parentElement = row;
over(btn);
OUT.during = titles([row, btn]); OUT.held = btn.getAttribute('data-tip-held');
esc_();
OUT.after = titles([row, btn]); OUT.heldAfter = held([row, btn]);""")
        self.assertEqual(o["during"], [None, None], "the ◉'s title stayed, so the grey box opens over the item card")
        self.assertEqual(o["held"], "why is this here? — show the frame that witnessed it",
                         "the prose lane did not take the ◉'s sentence")
        self.assertEqual(o["after"], [None, "why is this here? — show the frame that witnessed it"])
        self.assertEqual(o["heldAfter"], [None, None])

    def test_the_item_card_does_not_open_for_a_control_inside_its_anchor(self):
        """The card's first act on a hover is to clear tip-grey; a card that stepped aside never gets that far."""
        o = self._run(r"""
var row = new El('div', {'data-arttip': 'Shako'}); row.art = true; row.parentElement = BODY;
var btn = new El('button', {title: 'why is this here?'}); btn.parentElement = row;
var name = new El('span', {}); name.parentElement = row;
TIP.classList.add('tip-grey'); over(btn); OUT.onButton = TIP.classList.contains('tip-grey');
esc_();
TIP.classList.add('tip-grey'); over(name); OUT.onName = TIP.classList.contains('tip-grey');""")
        self.assertTrue(o["onButton"], "the item card started opening over the ◉ — two boxes")
        self.assertFalse(o["onName"], "the item card no longer opens on the anchor itself — the sabotage-proof baseline")

    def test_the_mule_tiles_evidence_badge_speaks_and_the_tile_box_steps_aside(self):
        o = self._run(r"""
var tile = new El('div', {'class': 'vd-item', 'data-key': 'k1', title: 'inventory 2,3 — drag to move'}); tile.mule = true; tile.tile = true; tile.parentElement = BODY;
var art = new El('span', {'aria-label': 'Shako', 'class': 'd2art-wrap'}); art.mule = true; art.art = true; art.parentElement = tile;
var ev = new El('button', {'class': 'vd-ev ev-none', title: 'no provenance recorded — nothing says who or what filed this'}); ev.parentElement = tile;
OUT.ownsBadge = window.D2TIP_OWNS(ev);
OUT.ownsArt = window.D2TIP_OWNS(art);
over(ev);
OUT.during = titles([tile, ev]); OUT.held = ev.getAttribute('data-tip-held');
esc_();
OUT.after = titles([tile, ev]);""")
        self.assertFalse(o["ownsBadge"], "the mule box still claims the evidence badge, so its title opens natively")
        self.assertTrue(o["ownsArt"], "the mule box no longer owns its own tile's art — the baseline that makes the badge case mean something")
        self.assertEqual(o["during"], [None, None], "a title stayed on the badge's chain: %r" % o["during"])
        self.assertEqual(o["held"], "no provenance recorded — nothing says who or what filed this")
        self.assertEqual(o["after"], ["inventory 2,3 — drag to move",
                                      "no provenance recorded — nothing says who or what filed this"])

    def test_the_vault_cells_size_line_is_held_over_the_glove_card(self):
        """GrokBot tick 371: the native "— 2×2 = 4 cells" strip over the Laying of Hands card. The vault cell is an
        item-card anchor with that title, and the card opens for the glove's ART inside it — a nearer anchor — so the
        card held only the art's title and the cell's opened natively. The card now borrows every title above its
        anchor, and the cell's size line, an anchor above it, becomes the card's footer instead of a second box."""
        o = self._run(r"""
artUrl = function(){ return 'art/laying_of_hands.png'; };
_arttipResolve = function(n){ return { artName: n, rich: true, desc: '<b>' + n + '</b> · Bramble Mitts' }; };
var cell = new El('div', {'class': 'vm-cell', 'data-vault-item': 'Laying of Hands', 'data-arttip': 'Laying of Hands',
                          title: 'Laying of Hands — 2×2 = 4 cells'}); cell.art = true; cell.parentElement = BODY;
var box = new El('span', {'class': 'vm-cell-art'}); box.parentElement = cell;
var wrap = new El('span', {'class': 'd2art-wrap lg', role: 'img', 'aria-label': 'Laying of Hands'}); wrap.art = true; wrap.parentElement = box;
var img = new El('img', {}); img.parentElement = wrap;
over(img);
OUT.on = TIP.classList.contains('on');
OUT.during = titles([cell, box, wrap, img]); OUT.held = cell.getAttribute('data-tip-held');
OUT.foot = (STUB['.att-go'] || {}).textContent || '';
leave();
OUT.after = cell.getAttribute('title'); OUT.heldAfter = cell.getAttribute('data-tip-held');""")
        self.assertTrue(o["on"], "the glove card did not open — the case this grades never happened")
        self.assertEqual(o["during"], [None, None, None, None],
                         "the cell's size line stayed a title, so the grey strip opens over the glove card: %r" % o["during"])
        self.assertEqual(o["held"], "Laying of Hands — 2×2 = 4 cells")
        self.assertEqual(o["foot"], "Laying of Hands — 2×2 = 4 cells",
                         "the cell's size line was hidden for the hover instead of carried by the card")
        self.assertEqual((o["after"], o["heldAfter"]), ("Laying of Hands — 2×2 = 4 cells", None),
                         "the cell did not get its title back when the pointer left")

    def test_every_static_titled_control_inside_an_item_card_anchor_is_covered(self):
        """The count, before and after: each titled element in the board's static markup that sits strictly inside an
        item-card anchor (the ARTTIP_SEL classes and attributes), hovered through the shipped lanes."""
        from html.parser import HTMLParser
        CLS = ("colossal-tile", "vm-item-name", "vault-chip", "top-drop-row", "road-node", "road-branch")
        ATT = ("data-arttip", "data-art-logo", "data-boss-tip", "data-aura-logo")

        def is_anchor(a):
            c = (a.get("class") or "").split()
            return (any(k in a for k in ATT) or any(k in c for k in CLS)
                    or ("d2art-wrap" in c and "aria-label" in a) or ("cw-name-ex" in c and "data-craftex" in a))

        class _P(HTMLParser):
            VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "source", "wbr"}

            def __init__(self):
                super().__init__()
                self.stack, self.found, self.skip = [], [], 0

            def handle_starttag(self, tag, attrs):
                if tag in ("script", "style"):
                    self.skip += 1
                    return
                if self.skip:
                    return
                a = dict(attrs)
                if "title" in a and not is_anchor(a) and any(x[1] for x in self.stack):
                    anc = [x for x in self.stack if x[1]][-1]
                    self.found.append([anc[2], anc[3], tag, a["title"]])
                if tag not in self.VOID:
                    self.stack.append((tag, is_anchor(a), tag, a.get("title")))

            def handle_endtag(self, tag):
                if tag in ("script", "style"):
                    self.skip = max(0, self.skip - 1)
                    return
                if self.skip:
                    return
                for k in range(len(self.stack) - 1, -1, -1):
                    if self.stack[k][0] == tag:
                        del self.stack[k:]
                        break

        p = _P()
        p.feed(self.board)
        self.assertGreater(len(p.found), 0, "no static titled control inside an item-card anchor was found — this grades nothing")
        o = self._run(r"""
var sites = %s; OUT.left = [];
sites.forEach(function(st){
  var a = new El(st[0], st[1] === null ? {} : {title: st[1]}); a.art = true; a.parentElement = BODY;
  var c = new El(st[2], {title: st[3]}); c.parentElement = a;
  over(c);
  var t = titles([a, c]).filter(function(v){ return v !== null; });
  if (t.length) OUT.left.push(t);
  esc_();
});
OUT.n = sites.length;""" % json.dumps(p.found))
        self.assertEqual(o["n"], len(p.found))
        self.assertEqual(o["left"], [], "%d of %d titled controls inside an item card still hand the browser a title"
                         % (len(o["left"]), o["n"]))

    def test_the_fleet_boxs_river_line_is_covered_on_its_shipped_markup(self):
        """Site 1, console: the SHIPPED _fleetSysHtml inside the SHIPPED .fx-sys wrapper, every nested pair hovered."""
        import test_the_fleet_card_says_how_each_pc_films_and_drains as F
        if F.NODE is None:
            self.skipTest("node is not installed (UNKNOWN, not a pass)")
        ui = TestReg1871ATitleAboveTheHostIsBorrowedToo.ui if hasattr(TestReg1871ATitleAboveTheHostIsBorrowedToo, "ui") else \
            io.open(os.path.join(HERE, "control_ui.html"), encoding="utf-8").read()
        wrap = "_sys = '<div class=\"fx-sys\" title=\"how this PC films D2R, where its reels are in the river, and its triage lane\">'"
        self.assertEqual(ui.count(wrap), 1, "the fleet box's river wrapper moved")
        fx = F._fixture()["online"][1]                       # the ALT: a stuck river, so every line carries a reason
        inner = F._run("OUT.h = _fleetSysHtml(%s, Date.now());" % json.dumps(fx))["h"]
        html = '<div class="fx-sys" title="how this PC films D2R, where its reels are in the river, and its triage lane">' + inner + "</div>"
        pairs = TestReg1871ATitleAboveTheHostIsBorrowedToo._nested_pairs(html)
        self.assertGreater(len(pairs), 0, "the shipped river line carries no nested title — this grades nothing")
        lane = TestReg1871ATitleAboveTheHostIsBorrowedToo
        case = lane("test_focus_borrows_nothing")
        lane.setUpClass()
        o = case._run("""
var pairs = %s; OUT.left = [];
pairs.forEach(function(pr){
  var c = chain(pr.map(function(x){ return [x[0], {title: x[1]}]; }));
  _itemTip.say(c[c.length - 1], false);
  var t = titles(c).filter(function(v){ return v !== null; });
  if (t.length) OUT.left.push(t);
  _itemTip.hide();
});
OUT.n = pairs.length;""" % json.dumps(pairs))
        self.assertEqual((o["n"], o["left"]), (len(pairs), []),
                         "the river line still hands the browser the box's title while a reason is hovered")


class TestV2122TheBorrowSurvivesAMoveInsideTheAnchor(unittest.TestCase):
    """v2121 (#130) — LEAVING A CHILD IS NOT LEAVING THE WRAP.

    v2119 borrowed the native `title` on enter and gave it back on four exit paths. One of those
    is `mouseout`, which fires on every child-to-child move INSIDE the anchor (img -> label,
    padding -> img) — and `e.target.closest(ARTTIP_SEL)` is still `cur`, so it restored the title
    and hid the rich card while the pointer had not left anything. The OS grey box #107 exists to
    clear flickered straight back on the same anchors.

    VERIFIED ON THE LIVE BOARD at v2121, on a real `.d2art-wrap.d2art-r-unique`:

        after enter        title=null   held='THE OS BOX TEXT'   card on
        after child move   title=null   held='THE OS BOX TEXT'   card on     <- this case
        after real leave   title restored, held cleared, card off

    The mousemove handler beside it already got this right (`over !== cur` keeps the card), so the
    two listeners contradicted each other. [[feedback-contradiction-is-the-finding]]
    """

    def setUp(self):
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            board = fh.read()
        body = _between(self, board, "document.addEventListener('mouseout'", "mouseleave",
                        what="the art lane's mouseout handler")
        # code only — this handler's comment describes the very bug it fixes
        self.code = re.sub(r"/\*.*?\*/", " ", body, flags=re.S)
        self.assertGreater(len(self.code.strip()), 60, "the comment strip ate the handler")

    def test_it_asks_where_the_pointer_WENT(self):
        self.assertIn("relatedTarget", self.code,
                      "mouseout gives the title back without asking where the pointer went, so a "
                      "move onto the anchor's own child restores the OS grey box mid-hover")

    def test_it_keeps_the_borrow_while_the_pointer_is_still_inside(self):
        self.assertIn("contains", self.code,
                      "nothing checks whether the pointer is still INSIDE the anchor — leaving a "
                      "child is being treated as leaving the wrap")
        self.assertIn("return", self.code,
                      "the guard computes the answer and does not act on it")

class TestV2115AnUnreadableStoreIsNotAnEmptyOne(unittest.TestCase):
    """v2115 — from the queue's P0 batch (#22 / #7 / #34 / #25), and it is a data-loss class.

    Four loaders did `except Exception: return {}` and four savers wrote back inside the SAME
    function (_vault_sweep_run, _chron_sweep_run). One bad read — a torn write, a file being
    written as it was read, a permissions blip — gave:

        load -> {} -> the sweep treats everything as never-swept -> save -> the ledger is gone

    The savers were already torn-write safe since v1209 (tmp + fsync + os.replace). That
    protects a write that is INTERRUPTED and does nothing about a write of the WRONG THING,
    which is this. ABSENT and UNREADABLE are different facts and only one is safe to
    overwrite. [[unknown-stays-unknown]]

    This corrupts a real file on disk and checks the bytes survive. A structural check would
    pass on a version that records the failure and writes anyway.
    """

    def _mod(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "ca_v2115", os.path.join(HERE, "control_app.py"))
        mod = importlib.util.module_from_spec(spec)
        try:
            spec.loader.exec_module(mod)
        except SystemExit:
            pass
        return mod

    def test_valid_JSON_of_the_WRONG_SHAPE_is_also_unknown(self):
        """v2119 (#113) — the hole this class left open, and it is the same data-loss class.

        The three cases above feed TRUNCATED json, an ABSENT file and a REPAIRED dict — all of
        which the parser rejects or accepts wholesale. None feeds a file that PARSES FINE and
        holds the wrong thing. `_json_store_load` discarded the unreadable mark BEFORE testing the
        shape and then only swapped the RETURN value, so a store holding `[]` (or a string, a
        number, or null) read as a clean empty dict, `_store_write_blocked()` answered False, and
        the next save overwrote the only copy.

        Parsing is not reading: the shape is part of the read. [[unknown-stays-unknown]]"""
        import json as _json
        import tempfile
        ca = self._mod()
        for payload, why in (("[]", "a list"), ('"x"', "a string"), ("42", "a number"),
                             ("null", "a null")):
            d = tempfile.mkdtemp(prefix="shape-")
            path = os.path.join(d, "store.json")
            with io.open(path, "w", encoding="utf-8") as fh:
                fh.write(payload)
            before = io.open(path, encoding="utf-8").read()

            got = ca._json_store_load(path, {})
            self.assertEqual(got, {}, "%s should still hand the caller a usable empty" % why)
            self.assertTrue(ca._store_write_blocked(path),
                            "%s parsed, so the store was treated as a CLEAN empty and the next "
                            "save is free to overwrite the only copy" % why)

            # and the bytes must actually survive a save attempt, not merely be flagged
            try:
                ca._vault_json_save(path, {"wiped": True})
            except Exception:
                pass
            self.assertEqual(io.open(path, encoding="utf-8").read(), before,
                             "%s was overwritten despite being unreadable-by-shape" % why)

    def test_a_correctly_shaped_store_still_loads_and_is_writable(self):
        """The mirror. A guard that refuses everything is the same defect wearing a helmet —
        this class must be seen NOT firing. [[feedback-blind-fixture-green-gate]]"""
        import tempfile
        ca = self._mod()
        d = tempfile.mkdtemp(prefix="shape-ok-")
        path = os.path.join(d, "store.json")
        with io.open(path, "w", encoding="utf-8") as fh:
            fh.write('{"a": 1}')
        self.assertEqual(ca._json_store_load(path, {}), {"a": 1})
        self.assertFalse(ca._store_write_blocked(path),
                         "a store that read perfectly is being refused writes")

    def test_a_corrupt_store_is_read_as_unknown_and_never_overwritten(self):
        import tempfile
        ca = self._mod()
        d = tempfile.mkdtemp(prefix="v2115_")
        self.addCleanup(shutil.rmtree, d, True)
        path = os.path.join(d, "vault_ledger.json")

        # a REAL ledger, then a torn write over it
        good = '{"Shako": {"mule": "uni-armor"}, "SoJ": {"mule": "uni-small"}}'
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(good)
        with open(path, "w", encoding="utf-8") as fh:
            fh.write('{"Shako": {"mule": "uni-arm')          # truncated mid-write
        torn = open(path, encoding="utf-8").read()

        got = ca._json_store_load(path, {})
        self.assertEqual(got, {}, "the caller still gets an empty dict to work with")
        self.assertTrue(ca._store_write_blocked(path),
                        "an unreadable file was not recorded, so the save that follows will "
                        "overwrite a store nobody managed to read")

        wrote = ca._vault_json_save(path, {"only": "what the sweep rebuilt from nothing"})
        self.assertFalse(wrote, "the save went ahead over an unreadable store")
        self.assertEqual(open(path, encoding="utf-8").read(), torn,
                         "THE FILE WAS OVERWRITTEN. Whatever was in it is now gone, replaced by "
                         "what a sweep inferred from an empty dict it was handed by a failed read")

    def test_an_ABSENT_store_is_still_freely_writable(self):
        # the opposite failure: refusing to write on a first run would mean nothing ever persists
        import tempfile
        ca = self._mod()
        d = tempfile.mkdtemp(prefix="v2115b_")
        self.addCleanup(shutil.rmtree, d, True)
        path = os.path.join(d, "never_existed.json")

        got = ca._json_store_load(path, {})
        self.assertEqual(got, {}, "an absent store is honestly empty")
        self.assertFalse(ca._store_write_blocked(path),
                         "a file that does not exist was treated as unreadable — a first run "
                         "would then never be able to save anything at all")
        self.assertTrue(ca._vault_json_save(path, {"first": "run"}), "the first write was refused")
        self.assertIn("first", open(path, encoding="utf-8").read())

    def test_a_store_that_reads_clean_again_unblocks(self):
        import tempfile
        ca = self._mod()
        d = tempfile.mkdtemp(prefix="v2115c_")
        self.addCleanup(shutil.rmtree, d, True)
        path = os.path.join(d, "s.json")
        with open(path, "w", encoding="utf-8") as fh:
            fh.write("{ this will not parse")
        ca._json_store_load(path, {})
        self.assertTrue(ca._store_write_blocked(path))
        with open(path, "w", encoding="utf-8") as fh:
            fh.write('{"ok": 1}')
        ca._json_store_load(path, {})
        self.assertFalse(ca._store_write_blocked(path),
                         "the block never lifts, so one bad read would freeze writes to this "
                         "store for the life of the process")


class TestV2124FilingAnItemDoesNotChangeWhereItBelongs(unittest.TestCase):
    """#134 — Konyo asked to simulate inside the vault manager and the manager contradicted itself:
    it filed Shako to SOCKETED and then, on the same page, VAULT INTEGRITY said
    "filed in SOCKETED — belongs in UNI-ARMOR · 1 auto-fixable".

    Both doors call the SAME classifier, so the disagreement was not two rules — it was ONE rule
    answering differently before and after the item was filed. `suggestMule`'s white-base branch is
    gated on `!ex` (EXTRA_ITEMS[name]) and `_tvExtraRemember` writes the name straight into
    EXTRA_ITEMS, so registering an item removed it from the branch that had just routed it.

    MEASURED on his live board, before -> after registering the same name:

        Shako / Monarch / Archon Plate      bases -> uni-armor
        Phase Blade / Colossus Blade / Hydra Bow   bases -> uni-weap

    FIVE OF SEVEN moved. A vault row records THAT HE HAS ONE, never that the name is a catalogue
    unique — so only a row claiming a real rarity may suppress the base branch.
    [[feedback-contradiction-is-the-finding]] [[the-unjoined-end]]"""

    def setUp(self):
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            board = fh.read()
        self.body = _between(self, board, "function suggestMule(", "window.suggestMule",
                             what="suggestMule")
        self.code = re.sub(r"/\*.*?\*/", " ", self.body, flags=re.S)
        self.code = re.sub(r"(?m)^\s*//.*$", "", self.code)
        self.assertGreater(len(self.code.strip()), 2000, "the comment strip ate suggestMule")

    def test_the_base_branch_is_not_suppressed_by_a_vault_row(self):
        self.assertIn("_exIsCatalogue", self.code,
                      "the white-base branch is gated on the raw extras lookup again, so filing an "
                      "item moves where the rules say it belongs and the auditor flags the "
                      "assembler's own filing")
        self.assertNotIn("&& !it && !ex && !itip", self.code,
                         "the raw `!ex` gate is back — a TV-vault row now suppresses the base "
                         "branch exactly as it did before #134")

    def test_only_a_REAL_rarity_may_suppress_it(self):
        # _between, not a byte count: this file's own ratchet forbids new byte-counted slices, and
        # it is right to — a window a later comment outgrows comes back empty, and assertIn on an
        # empty string fails for the wrong reason while assertNotIn PASSES.
        decl = _between(self, self.code, "var _exIsCatalogue", ";",
                        what="the _exIsCatalogue declaration")
        self.assertIn("rarity", decl,
                      "the flag no longer asks what the row CLAIMS TO BE — any vault row would "
                      "suppress the base branch again")
        self.assertIn("basic", decl,
                      "the synthetic vault rarity is not excluded, so a base he has vaulted still "
                      "reads as a catalogue item")

    def test_the_behaviour_itself_is_pinned_in_a_spec_that_RUNS_it(self):
        """#148 — a Python grep cannot call suggestMule. This class can only prove the SHAPE of the
        fix; the invariant that matters is behavioural (same name, same answer, before and after
        filing) and it needs a browser. Point at the spec that does it, so deleting that spec is
        visible here rather than silent."""
        spec = os.path.join(os.path.dirname(HERE), "tests",
                            "v2124_filing_does_not_move_the_locker.spec.ts")
        self.assertTrue(os.path.isfile(spec),
                        "the behavioural half of #134 has no spec — this class greps source and "
                        "would stay green while suggestMule answered differently before and after "
                        "a filing, which is the actual defect")
        with io.open(spec, encoding="utf-8") as fh:
            body = fh.read()
        # ⚠ #149 — STRIP THE SPEC'S OWN PROSE FIRST. Its header block explains the defect and names
        # both functions, so a raw grep is satisfied by the paragraph describing the bug while the
        # actual calls are gone. Ninth time in one night. [[feedback-comments-vs-code]]
        code = re.sub(r"/\*.*?\*/", " ", body, flags=re.S)
        code = re.sub(r"(?m)^\s*//.*$", "", code)
        self.assertGreater(len(code.strip()), 400, "the comment strip ate the spec")
        self.assertIn("w.suggestMule(", code,
                      "the spec no longer CALLS the classifier — only mentions it")
        self.assertIn("_tvExtraRemember && w._tvExtraRemember(", code,
                      "the spec no longer files the item between the two readings, so it cannot "
                      "see the answer move")
        self.assertIn("tvVaultRegister(", code,
                      "the end-to-end case no longer goes through the real door")


class TestV2126TheWaitingBannerOpensTheRoomItNames(unittest.TestCase):
    """Konyo: "347 finds waiting to register but when i click it nothing happens".

    The banner's own label reads "TV·D ▸ Chronicle Sweep →" and its handler called `_shellHome()`
    alone. shellHome lights the TV·D tab but does NOT clear `data-view`, and #hd-chron is
    display:none under data-view="sessions" — which the comment directly above the banner already
    SAYS, in the sentence explaining why the banner had to exist at all. So it scrolled to a hidden
    element and nothing moved.

    MEASURED on his live console before the fix:
        before _shellHome()   view=sessions  #hd-chron visible=false  height=0
        after  _shellHome()   view=sessions  #hd-chron visible=false  height=0
    and after: view=null, visible=true, height=1087, register button reachable.
    [[the-unjoined-end]]"""

    def setUp(self):
        with io.open(os.path.join(HERE, "control_ui.html"), encoding="utf-8") as fh:
            self.ui = fh.read()
        self.body = _between(self, self.ui, "window._chronWaitingJump = function", "window._shellHome =",
                             what="the waiting-banner jump")
        self.code = re.sub(r"/\*.*?\*/", " ", self.body, flags=re.S)
        self.assertGreater(len(self.code.strip()), 120, "the comment strip ate the handler")

    def test_it_leaves_the_sessions_view_first(self):
        self.assertIn("removeAttribute('data-view')", self.code,
                      "the jump does not leave the Sessions view, so #hd-chron stays display:none "
                      "and the click lands on a 0x0 element — exactly what he reported")

    def test_it_still_goes_to_the_cockpit_and_to_the_panel(self):
        self.assertIn("shellHome()", self.code, "the jump no longer opens the TV·D cockpit")
        self.assertIn("hd-chron", self.code, "the jump no longer targets the Chronicle Sweep panel")

    def test_the_one_door_SURVIVED_the_banner(self):
        """★ v2763 — RE-POINTED, NOT DELETED. The #chron-waiting banner is gone: what it announced
        now reaches him through the chronicle inbox, and only when something is actually new (his
        proposal was 5.9 days old with 0 of 354 new — a permanent strip asking for nothing).

        THE LAW IS UNCHANGED: there must be exactly ONE door to the cockpit, not a second inline
        route that drifts from the header button and quietly stops working. `_chronWaitingJump` is
        that door and it OUTLIVES the element it was named for — so this now pins the door itself
        rather than the button that used to hold it.
        ⚠ Deleting this law with the markup would have dropped the guard that stops a second route
        being invented. A law about a MECHANISM must not die with one of its callers.
        """
        self.assertIn("window._chronWaitingJump", self.ui,
                      "the one door is gone — anything that wants the cockpit will grow its own "
                      "route, which is what drifted and broke last time")
        # ⚠⚠ v2767 — AND SOMETHING MUST OPEN IT. FOUND BY THE SECOND EYE on the v2763 diff
        # (grok-4-1-fast-reasoning, cold): "window._chronWaitingJump is now dead code unless called
        # from elsewhere." REPRODUCED — after the fold, the strip's INFORMATION reached the inbox
        # and its ACTION did not: the inbox button opens the review MODAL, a different destination,
        # so nothing anywhere called the door. THIS LAW WAS GREEN THE WHOLE TIME, because it asked
        # whether the door EXISTED and never whether anything opened it. A defined-and-uncalled
        # function is the exact shape of [[plumbing-with-no-tap]], and a gate that pins only the
        # definition makes it look supervised.
        # ⚠⚠ v2769 — THE COMMENT FILTER WAS THE DEFECT THIS LAW EXISTS TO CATCH, IN THE LAW.
        # Found by the post-ship review: it skipped lines STARTING with a comment marker, but a
        # multi-line HTML comment's continuation lines start with ordinary words. Three prose
        # mentions of _chronWaitingJump (in the v2763 and v2767 comment blocks) satisfied it, so
        # deleting the real caller left the law green over a door nothing opens — a gate passing
        # on prose about the very thing it is supposed to require.
        # Comments are STRIPPED now, not skipped line-by-line: <!-- --> and /* */ both.
        import re as _re
        _stripped = _re.sub(r"<!--.*?-->", " ", self.ui, flags=_re.S)
        _stripped = _re.sub(r"/\*.*?\*/", " ", _stripped, flags=_re.S)
        calls = [ln for ln in _stripped.split("\n")
                 if "_chronWaitingJump" in ln
                 and "window._chronWaitingJump = function" not in ln
                 and not ln.strip().startswith("//")]
        self.assertTrue(calls,
                        "`_chronWaitingJump` is defined and CALLED BY NOTHING. The one door to "
                        "TV·D ▸ Chronicle Sweep exists and cannot be opened, so the sweep's own "
                        "count can be read in the inbox with no way to act on it.")
        self.assertNotIn('id="chron-waiting"', self.ui,
                         "the banner is back on the gameplay home. What it says belongs in the "
                         "inbox, and only when something needs him.")
        self.assertIn("window._chInboxRepaint", self.ui,
                      "the inbox export is gone, so the sweep in BLOCK B can no longer reach the "
                      "painter in BLOCK A — a dead render, the 5th of that class here")

    def test_the_label_says_what_it_MEANS_not_only_where_it_goes(self):
        """His question was "what does it mean and what is it meant for?" — a state ("waiting to
        register") is not a meaning."""
        # v2199 — "grail" -> "ledger". His ruling: the word was invented and the thing is a
        # database. The guard moves WITH the copy in the same commit; a source-text assertion left
        # behind is a red gate that says nothing about the product.
        # v2278 — THE LAW SURVIVED, THE SENTENCE DID NOT. This used to pin the literal string
        # "not in your ledger yet", and that sentence turned out to be FALSE: measured on his live
        # console, all 347 proposed names were already in his foundLog and already dated. So the
        # banner now names what would CHANGE, in three states, and this guard pins the meaning
        # rather than one wording of it — which is what it was always for.
        # ⚠ A guard pinned to prose blocks the fix to that prose. Pin the law.
        # [[feedback-state-the-bar-not-the-routes]]
        states = ["not in your chronicle yet",                 # some would change
                  "you already have every one",                # none would
                  "not yet checked against your chronicle"]    # nobody could ask — never a number
        for st in states:
            self.assertIn(st, self.ui,
                          "the banner lost the %r state, so a proposal that is %s reads the same "
                          "as one that is not" % (st, st))
        self.assertNotIn("not in your grail yet", self.ui,
                         "the invented word came back on the one line he pointed at by name")
        self.assertNotIn("not in your ledger yet", self.ui,
                         "the retired claim is back — it told him 347 items were absent from a "
                         "ledger that already held every one of them")


class TestV2128TheFoldRefusesWhatIsAlreadyCovered(unittest.TestCase):
    """#11 — the overlap refusal is the one thing standing between this module and a FORGED session
    id, and it had two holes, both silent.

    1. EXACT INTERVALS. v883's seal fold already moved every IN-window frame into reel_<sid>/, so
       the leftovers of an already-SEALED session lie OUTSIDE that reel's remaining min/max BY
       CONSTRUCTION — which is the case the module's own docstring names as the harmful one, and
       the one an exact-interval test can never refuse.
    2. HOLLOW REELS. The reaper sheds jpegs and leaves index.json, and the window builder only read
       f_<ms>.jpg — so a hollow reel contributed NO window and every cluster in its span read
       eligible.

    MEASURED, before -> after, on the adjacent-leftovers fixture:
        normal reel   eligible 1 -> 0
        hollow reel   eligible 1 -> 0
        a genuinely separate cluster (10 min away) stays eligible in both
    [[unknown-stays-unknown]]"""

    def _tree(self, hollow, gap_ms):
        import json as _j, tempfile
        d = tempfile.mkdtemp(prefix="of-guard-")
        self.addCleanup(shutil.rmtree, d, True)
        hist = os.path.join(d, "hist")
        os.makedirs(hist)
        base = 1_500_000_000_000
        r = os.path.join(hist, "reel_s_%d_1" % base)
        os.makedirs(r)
        if hollow:
            with open(os.path.join(r, "index.json"), "w") as fh:
                _j.dump({"frames": [{"ts": base}, {"ts": base + 5000}]}, fh)
        else:
            for k in (0, 5000):
                with open(os.path.join(r, "f_%d.jpg" % (base + k)), "wb") as fh:
                    fh.write(b"x" * 512)
        for k in (gap_ms, gap_ms + 1000):
            with open(os.path.join(hist, "f_%d.jpg" % (base + k)), "wb") as fh:
                fh.write(b"y" * 512)
        return hist

    def _eligible(self, hist):
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import orphan_fold as of
        rows = of.plan(hist_dir=hist).get("clusters") or []
        return [c for c in rows if isinstance(c, dict) and c.get("eligible")], rows

    def test_leftovers_beside_a_sealed_reel_are_refused(self):
        for hollow in (False, True):
            elig, rows = self._eligible(self._tree(hollow, 6000))
            self.assertTrue(rows, "the fixture produced no cluster at all — nothing was measured")
            self.assertEqual(elig, [],
                             "leftovers ADJACENT to a sealed reel (hollow=%s) were offered for "
                             "folding — they would be minted under a forged session id" % hollow)

    def test_a_genuinely_separate_cluster_is_STILL_eligible(self):
        """The mirror, and the half that matters: a refusal that refuses everything is the same
        defect wearing a helmet. [[feedback-blind-fixture-green-gate]]"""
        for hollow in (False, True):
            elig, rows = self._eligible(self._tree(hollow, 10 * 60 * 1000))
            self.assertTrue(rows, "the fixture produced no cluster at all")
            self.assertEqual(len(elig), 1,
                             "a cluster ten minutes clear of every reel is being refused "
                             "(hollow=%s) — the fold can no longer do its job at all" % hollow)


class TestV2131TheDemoGateCountsItsOwnJourneys(unittest.TestCase):
    """v2130 added J10 and the runner still exited on `pass === 9`, so a 10/10 run — its own summary
    printing "DEMOS: 10/10 ✅" — exited 1 and hooks/pre-push refused the push. A gate that fails a
    green run is the mirror of one that passes a red one, and it is worse: it trains you to bypass.

    The count of journeys is not the contract. "None of them failed" is."""

    def _src(self):
        with io.open(os.path.join(HERE, "demo_console.mjs"), encoding="utf-8") as fh:
            return fh.read()

    def test_the_exit_code_is_derived_from_the_results(self):
        src = re.sub(r"(?m)^\s*//.*$", "", self._src())
        self.assertNotIn("pass === 9", src,
                         "the demo runner exits on a hardcoded journey count again — adding one "
                         "journey makes every green run fail the push")
        self.assertIn("pass === results.length", src,
                      "the exit code no longer asks whether every journey that RAN passed")

    def test_the_summary_line_is_derived_too(self):
        src = self._src()
        self.assertNotIn("${pass}/9", src,
                         "the summary prints a hardcoded denominator, so it will misreport the "
                         "moment a journey is added or removed")
        self.assertIn("${pass}/${results.length}", src,
                      "the summary no longer derives its denominator from the journeys that ran")


class TestV2132TheBorrowedSentenceIsGivenBackOnScreen(unittest.TestCase):
    """v2119 stopped the OS grey box opening over the rich card by BORROWING the anchor's `title`
    (#107). That was right and it had a cost nobody had paid: on the MOUSE path the sentence then
    went nowhere. MEASURED on the live board: 987 of 5010 art anchors carry BOTH attributes, so for
    987 anchors the hint they were written to carry became invisible the moment the card claimed the
    hover.

    Not a new treatment — the console's #itip already does exactly this with `.itip-go`, and this
    card hand-rolls the same footer for boss rows. [[copy-drift]]

    ⚠ THE ONE WAY THIS CAN LIE is a stale footer riding onto the next card: the art lane never wipes
    children it did not create. So the clear is asserted as hard as the write.
    Verified in a browser: with a title -> footer "OPEN THE ID CARD", title attribute null, card on;
    then a titleless anchor -> footer "" and hidden."""

    def setUp(self):
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            board = fh.read()
        self.body = _between(self, board, "function _artFoot(txt)", "document.addEventListener('mouseover'",
                             what="the art lane's footer + hold")
        self.code = re.sub(r"/\*.*?\*/", " ", self.body, flags=re.S)
        self.code = re.sub(r"(?m)^\s*//.*$", "", self.code)
        self.assertGreater(len(self.code.strip()), 200, "the comment strip ate the lane")

    def test_the_borrowed_text_is_rendered(self):
        self.assertIn("_artFoot(t)", self.code,
                      "the anchor's sentence is borrowed and never shown — on the mouse path it "
                      "simply disappears, which is what taking the title costs if nothing gives "
                      "it back")

    def test_an_anchor_with_nothing_to_say_CLEARS_it(self):
        self.assertGreaterEqual(self.code.count("_artFoot('')"), 2,
                                "the footer is written but not cleared, so the last card's sentence "
                                "rides onto an item that has no title at all — the art lane never "
                                "wipes children it did not create")

    def test_the_prose_lane_does_not_also_wear_it(self):
        """⚠ v2134 — MY FIRST VERSION OF THIS ASSERTED THE RULE EXISTED, and the rule could never
        win. v2132 set `go.style.display='block'`, and an INLINE declaration outranks every
        stylesheet rule — so `#arttip.tip-say .att-go{display:none}` was present, correct and
        unreachable, and a footer left from the last card stayed visible when the prose lane took
        over the shared #arttip. The sentence printed twice.

        A guard that checks for a rule must also check that nothing outranks it.
        [[d2r-css-last-rule-wins]]"""
        with io.open(os.path.join(os.path.dirname(HERE), "bible.html"), encoding="utf-8") as fh:
            board = fh.read()
        self.assertIn("#arttip.tip-say .att-go,\n#arttip.tip-say .att-go.on{display:none}", board,
                      "the prose lane no longer hides the footer in BOTH states — showing it there "
                      "prints the same sentence twice")
        self.assertIn("#arttip .att-go.on{display:block}", board,
                      "the footer's visible state is not a class, so it is being set some other way")

    def test_visibility_is_never_set_INLINE(self):
        """The specific mechanism that defeated the rule above. An inline display wins over the
        cascade, so the prose lane's hide can never apply."""
        # ⚠ SCOPE IT TO THE FUNCTION THAT OWNS THE BEHAVIOUR. My first cut asserted over the whole
        # lane slice and matched `img.style.display = 'none'` — the art card's own image error
        # handler, which is unrelated and correct. A slice too WIDE fails for the wrong reason just
        # as surely as one too narrow proves nothing.
        foot = _between(self, self.code, "function _artFoot(txt)", "function _artHold",
                        what="the footer writer")
        self.assertNotIn("style.display", foot,
                         "the footer sets `style.display` again — an inline declaration outranks "
                         "the stylesheet, so #arttip.tip-say's hide becomes unreachable and a stale "
                         "footer shows under the prose lane")
        self.assertIn("classList.toggle('on'", foot,
                      "the footer's visibility is no longer a class the cascade can override")


